Omen.__htmlPayload = [==[<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <title>Omen</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;600&display=swap" rel="stylesheet">
    <style>
*, *::before, *::after { box-sizing: border-box; }
html, body {
    margin: 0; padding: 0;
    width: 100vw; height: 100vh;
    overflow: hidden;
    background: transparent;
    font-family: 'DM Sans', -apple-system, "Segoe UI", sans-serif;
    font-weight: 500;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
    color: var(--txt-on-ink);
    user-select: none;
    cursor: none;
}
:root {
    --text-rgb: 255,255,255;
    --ink:            #000000;
    --ink-1:          #050505;
    --ink-2:          #0C0C0C;
    --ink-3:          #131313;
    --ink-4:          #1A1A1A;
    --ink-5:          #232323;
    --ink-6:          #2E2E2E;
    --ink-7:          #3B3B3B;
    --paper:          #F5F5F5;
    --paper-1:        #FAFAFA;
    --paper-2:        #EFEFEF;
    --paper-3:        #E5E5E5;
    --paper-4:        #DBDBDB;
    --paper-5:        #C8C8C8;
    --paper-6:        #A8A8A8;
    --paper-7:        #7A7A7A;
    --txt-on-ink:         #FFFFFF;
    --txt-on-ink-dim:     rgba(255,255,255,.72);
    --txt-on-ink-mute:    rgba(255,255,255,.42);
    --txt-on-ink-ghost:   rgba(255,255,255,.26);
    --txt-on-paper:       #000000;
    --txt-on-paper-dim:   rgba(0,0,0,.72);
    --txt-on-paper-mute:  rgba(0,0,0,.42);
    --txt-on-paper-ghost: rgba(0,0,0,.26);
    --stroke-ink-hair:  rgba(255,255,255,.06);
    --stroke-ink-soft:  rgba(255,255,255,.12);
    --stroke-ink-hard:  rgba(255,255,255,.28);
    --stroke-ink-glow:  rgba(255,255,255,.55);
    --stroke-paper-hair: rgba(0,0,0,.05);
    --stroke-paper-soft: rgba(0,0,0,.10);
    --stroke-paper-hard: rgba(0,0,0,.22);
    --wash-ink-004: rgba(255,255,255,.04);
    --wash-ink-006: rgba(255,255,255,.06);
    --wash-ink-010: rgba(255,255,255,.10);
    --wash-ink-015: rgba(255,255,255,.15);
    --wash-ink-020: rgba(255,255,255,.20);
    --wash-ink-032: rgba(255,255,255,.32);
    --wash-paper-004: rgba(0,0,0,.04);
    --wash-paper-008: rgba(0,0,0,.08);
    --wash-paper-012: rgba(0,0,0,.12);
    --wash-paper-020: rgba(0,0,0,.20);
    --card-shadow:
        0 4px 16px rgba(0,0,0,.55),
        0 1px 3px rgba(0,0,0,.75),
        inset 0 0 0 1px rgba(255,255,255,.05);
    --card-shadow-hover:
        0 10px 32px rgba(0,0,0,.75),
        0 2px 6px rgba(0,0,0,.85),
        inset 0 0 0 1px rgba(255,255,255,.14),
        0 0 40px rgba(255,255,255,.06);
    --menu-shadow:
        0 0 0 1px rgba(255,255,255,.08),
        0 0 0 2px rgba(0,0,0,.6),
        0 32px 90px rgba(0,0,0,.75),
        0 12px 40px rgba(0,0,0,.5),
        0 0 120px rgba(255,255,255,.04);
}
body.light-mode {
    --ink: #ECECEC; --ink-2: #F4F4F4; --ink-3: #FFFFFF;
    --txt-on-ink: #0A0A0A;
    --stroke-ink-soft: rgba(0,0,0,.12);
}
body.light-mode #menu { color: #0A0A0A; }
body.light-mode .feat .nm, body.light-mode .nm { color: #0A0A0A; }
body.omen-light {
    --text-rgb: 0,0,0;
    --ink:   #FFFFFF; --ink-1: #FAFAFA; --ink-2: #F2F2F2; --ink-3: #ECECEC;
    --ink-4: #E4E4E4; --ink-5: #D8D8D8; --ink-6: #C8C8C8; --ink-7: #B0B0B0;
    --txt-on-ink: #000000; --txt-on-ink-dim: rgba(0,0,0,.72);
    --txt-on-ink-mute: rgba(0,0,0,.45); --txt-on-ink-ghost: rgba(0,0,0,.28);
    --stroke-ink-hair: rgba(0,0,0,.06); --stroke-ink-soft: rgba(0,0,0,.12);
    --stroke-ink-hard: rgba(0,0,0,.28); --stroke-ink-glow: rgba(0,0,0,.45);
    --wash-ink-004: rgba(0,0,0,.04); --wash-ink-006: rgba(0,0,0,.06);
    --wash-ink-010: rgba(0,0,0,.10); --wash-ink-015: rgba(0,0,0,.15);
    --wash-ink-020: rgba(0,0,0,.20); --wash-ink-032: rgba(0,0,0,.32);
    --card-shadow: 0 4px 16px rgba(0,0,0,.16), 0 1px 3px rgba(0,0,0,.20), inset 0 0 0 1px rgba(0,0,0,.05);
    --card-shadow-hover: 0 10px 32px rgba(0,0,0,.22), inset 0 0 0 1px rgba(0,0,0,.12);
    --menu-shadow: 0 0 0 1px rgba(0,0,0,.10), 0 32px 90px rgba(0,0,0,.28), 0 12px 40px rgba(0,0,0,.18);
}
#menu {
    position: fixed;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    width: 1120px;
    height: 760px;
    border-radius: 14px;
    overflow: hidden;
    background: var(--ink);
    display: grid;
    grid-template-rows: 56px 1fr;
    grid-template-columns: 232px 1fr;
    grid-template-areas:
        "header header"
        "sidebar main";
    box-shadow: var(--menu-shadow);
}
#menu::before {
    content: "";
    position: absolute;
    top: 0; left: 6%; right: 6%;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,.35), transparent);
    opacity: .8;
    z-index: 10;
    pointer-events: none;
}
#header {
    grid-area: header;
    background: var(--ink);
    border-bottom: 1px solid var(--stroke-ink-soft);
    display: flex;
    align-items: center;
    padding: 0 18px;
    cursor: grab;
    position: relative;
    z-index: 5;
}
#header:active { cursor: grabbing; }
#header::after {
    content: "";
    position: absolute;
    bottom: -1px; left: 12%; right: 12%;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,.16), transparent);
    pointer-events: none;
}
.brand {
    display: flex;
    align-items: center;
    gap: 10px;
}
.brand .wordmark {
    font-family: 'DM Sans', sans-serif;
    font-weight: 900;
    font-size: 18px;
    letter-spacing: 5px;
    color: var(--txt-on-ink);
    text-shadow: 0 0 20px rgba(255,255,255,.15);
}
.ac-chip {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px 4px 8px;
    background: rgba(255,255,255,.05);
    border: 1px solid rgba(255,255,255,.14);
    border-radius: 999px;
    font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--txt-on-ink-dim);
    margin-left: 12px;
}
.ac-chip.hidden { display: none; }
.ac-chip .ac-dot {
    width: 6px; height: 6px;
    border-radius: 50%;
    background: var(--txt-on-ink);
    box-shadow: 0 0 6px var(--txt-on-ink);
    animation: acPulse 1.6s ease-in-out infinite;
}
@keyframes acPulse {
    0%, 100% { opacity: 1; }
    50%      { opacity: .45; }
}
.ac-chip .ac-lbl { color: var(--txt-on-ink-mute); }
.ac-chip .ac-val { color: var(--txt-on-ink); font-weight: 700; }
.hdr-logo {
    width: 30px; height: 30px;
    border-radius: 6px;
    object-fit: cover;
    display: block;
    margin-right: 4px;
    filter: drop-shadow(0 0 10px rgba(255,255,255,.15));
}
.hdr-search {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-left: 28px;
    padding: 6px 12px;
    background: var(--ink-3);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 6px;
    color: var(--txt-on-ink-mute);
    font-size: 12px;
    min-width: 220px;
    cursor: text;
    transition: border-color .15s ease, background .15s ease;
}
.hdr-search:hover, .hdr-search.focus {
    border-color: rgba(var(--text-rgb),.28);
    background: var(--ink-4);
    color: var(--txt-on-ink-dim);
}
.hdr-search svg {
    width: 13px; height: 13px;
    stroke: currentColor;
    stroke-width: 1.8;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
}
.hdr-search .kbd {
    margin-left: auto;
    font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px;
    padding: 2px 6px;
    background: var(--wash-ink-006);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 3px;
    color: var(--txt-on-ink-mute);
    letter-spacing: .5px;
}
.hdr-right {
    margin-left: auto;
    display: flex;
    align-items: center;
    gap: 10px;
}
.hdr-stat {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    background: var(--ink-3);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 999px;
    font-size: 10.5px;
    font-weight: 600;
    color: var(--txt-on-ink-dim);
    letter-spacing: .3px;
}
.hdr-stat .dot {
    width: 5px; height: 5px;
    border-radius: 50%;
    background: var(--txt-on-ink);
    box-shadow: 0 0 6px rgba(255,255,255,.55);
    animation: pulseDot 2s ease-in-out infinite;
}
@keyframes pulseDot {
    0%, 100% { opacity: 1; transform: scale(1); }
    50%      { opacity: .55; transform: scale(1.2); }
}
.hdr-btn {
    width: 26px; height: 26px;
    display: flex; align-items: center; justify-content: center;
    background: transparent;
    border: 1px solid transparent;
    border-radius: 5px;
    color: var(--txt-on-ink-mute);
    cursor: pointer;
    transition: all .15s ease;
}
.hdr-btn:hover {
    background: var(--wash-ink-010);
    border-color: var(--stroke-ink-soft);
    color: var(--txt-on-ink);
}
.hdr-btn svg {
    width: 12px; height: 12px;
    stroke: currentColor;
    stroke-width: 1.8;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
}
#sidebar {
    grid-area: sidebar;
    background: var(--paper);
    border-right: 1px solid var(--paper-4);
    display: flex;
    flex-direction: column;
    position: relative;
    z-index: 2;
}
#sidebar::after {
    content: "";
    position: absolute;
    top: 12%; bottom: 12%;
    right: 0;
    width: 1px;
    background: linear-gradient(180deg, transparent, rgba(0,0,0,.22), transparent);
    pointer-events: none;
}
.sb-head {
    padding: 16px 18px 10px;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 2px;
    color: var(--txt-on-paper-mute);
    text-transform: uppercase;
}
#nav {
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 0 0 12px;
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
}
#nav::-webkit-scrollbar { width: 0; }
.nav-btn {
    position: relative;
    height: 38px;
    margin: 0 8px;
    padding: 0 14px;
    border: 1px solid transparent;
    border-radius: 7px;
    display: flex;
    align-items: center;
    gap: 11px;
    color: var(--txt-on-paper-dim);
    font-size: 12.5px;
    font-weight: 500;
    cursor: pointer;
    transition:
        color .18s ease,
        background .18s ease,
        border-color .18s ease,
        transform .18s cubic-bezier(.16,1,.3,1);
}
.nav-btn .nav-ico {
    width: 16px; height: 16px;
    stroke: currentColor;
    stroke-width: 1.7;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
    flex-shrink: 0;
}
.nav-btn .nav-lbl { white-space: nowrap; flex: 1; }
.nav-btn .nav-badge {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px;
    font-weight: 600;
    padding: 1.5px 6px;
    background: var(--wash-paper-008);
    border-radius: 999px;
    color: var(--txt-on-paper);
    min-width: 18px;
    text-align: center;
}
.nav-btn:hover {
    color: var(--txt-on-paper);
    background: var(--wash-paper-004);
    border-color: var(--wash-paper-008);
    transform: translateX(1px);
}
.nav-btn.active {
    color: var(--txt-on-paper);
    background: linear-gradient(90deg, rgba(0,0,0,.08), rgba(0,0,0,0));
    border-color: rgba(0,0,0,.14);
    box-shadow:
        inset 0 0 0 1px rgba(0,0,0,.06),
        0 0 20px rgba(0,0,0,.06);
    font-weight: 600;
}
.nav-btn.active::before {
    content: "";
    position: absolute;
    left: -2px; top: 20%; bottom: 20%;
    width: 3px;
    background: linear-gradient(180deg, rgba(0,0,0,.6), #000, rgba(0,0,0,.6));
    border-radius: 2px;
    box-shadow: 0 0 12px rgba(0,0,0,.55), 0 0 20px rgba(0,0,0,.25);
    animation: paperPulse 2.2s ease-in-out infinite;
}
@keyframes paperPulse {
    0%, 100% { opacity: 1; }
    50%      { opacity: .65; }
}
.sb-foot {
    margin-top: auto;
    padding: 12px 12px;
    border-top: 1px solid var(--paper-4);
    display: block;
    background: linear-gradient(180deg, transparent 0%, rgba(0,0,0,.03) 100%);
    font-size: 11px;
}
.sb-card {
    background: var(--paper-1);
    border: 1px solid var(--paper-4);
    border-radius: 8px;
    padding: 10px 11px;
    display: flex;
    align-items: center;
    gap: 10px;
    cursor: pointer;
    transition: background .15s ease, border-color .15s ease, transform .18s cubic-bezier(.16,1,.3,1);
    position: relative;
}
.sb-card:hover {
    background: var(--paper-2);
    border-color: rgba(0,0,0,.20);
    transform: translateY(-1px);
}
.sb-card::after {
    content: "";
    position: absolute;
    right: 9px; top: 50%;
    width: 5px; height: 5px;
    border-right: 1.4px solid var(--txt-on-paper-mute);
    border-top: 1.4px solid var(--txt-on-paper-mute);
    transform: translateY(-50%) rotate(45deg);
    opacity: .55;
}
.sb-avatar {
    width: 34px; height: 34px;
    border-radius: 50%;
    background: var(--ink);
    color: var(--paper);
    display: flex; align-items: center; justify-content: center;
    font-weight: 800;
    font-size: 12px;
    letter-spacing: -.4px;
    overflow: hidden;
    flex-shrink: 0;
    border: 1px solid var(--paper-4);
    position: relative;
}
.sb-avatar img {
    width: 100%; height: 100%; object-fit: cover; display: block;
}
.sb-avatar .presence {
    position: absolute;
    right: -1px; bottom: -1px;
    width: 10px; height: 10px;
    border-radius: 50%;
    background: var(--paper);
    border: 2px solid var(--paper-1);
}
.sb-avatar .presence.on { background: var(--ink); }
.sb-body { flex: 1; min-width: 0; overflow: hidden; }
.sb-body .row1 {
    display: flex; align-items: baseline; gap: 6px;
    font-size: 12px;
    font-weight: 700;
    color: var(--txt-on-paper);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    line-height: 1.15;
}
.sb-body .row1 .at { font-weight: 500; color: var(--txt-on-paper-mute); font-size: 10.5px; }
.sb-body .row2 {
    display: flex; align-items: center; gap: 6px;
    margin-top: 3px;
    font-size: 9.5px;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--txt-on-paper-mute);
    font-weight: 600;
}
.sb-body .row2 .dot {
    width: 3px; height: 3px; border-radius: 50%;
    background: var(--txt-on-paper-ghost);
}
.sb-body .row2 .keytime {
    color: var(--txt-on-paper-dim);
    font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px;
    letter-spacing: .5px;
    text-transform: none;
    font-weight: 600;
}
.sb-body .row2 .keytime.warn { color: var(--txt-on-paper); }
.sb-body .row2 .keytime.expired { color: var(--txt-on-paper); text-decoration: line-through; }
#profileoverlay {
    position: absolute;
    inset: 0;
    background: rgba(0,0,0,.62);
    backdrop-filter: blur(6px);
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 40;
}
#profileoverlay.show { display: flex; }
#profilebox {
    width: 560px;
    max-height: 78%;
    overflow-y: auto;
    background: var(--paper);
    color: var(--txt-on-paper);
    border-radius: 12px;
    border: 1px solid rgba(0,0,0,.16);
    box-shadow: 0 24px 56px rgba(0,0,0,.55), 0 0 0 1px rgba(0,0,0,.04);
    padding: 24px 24px 22px;
    display: flex;
    flex-direction: column;
    gap: 18px;
    animation: profilePop .22s cubic-bezier(.16,1,.3,1);
}
@keyframes profilePop {
    from { opacity: 0; transform: translateY(6px) scale(.985); }
    to   { opacity: 1; transform: translateY(0)   scale(1); }
}
.p-head {
    display: flex; align-items: center; gap: 16px;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--paper-4);
}
.p-avatar {
    width: 68px; height: 68px;
    border-radius: 50%;
    background: var(--ink);
    color: var(--paper);
    display: flex; align-items: center; justify-content: center;
    font-weight: 800;
    font-size: 26px;
    overflow: hidden;
    flex-shrink: 0;
    border: 2px solid var(--paper-3);
}
.p-avatar img { width: 100%; height: 100%; object-fit: cover; }
.p-head-body { flex: 1; min-width: 0; }
.p-head-body .p-name {
    font-size: 20px; font-weight: 800; letter-spacing: -.2px;
    color: var(--txt-on-paper);
    display: flex; align-items: center; gap: 8px;
    line-height: 1.1;
}
.p-head-body .p-name .p-tag {
    font-size: 10.5px; font-weight: 700;
    letter-spacing: 1.4px; text-transform: uppercase;
    background: var(--ink);
    color: var(--paper);
    padding: 3px 8px;
    border-radius: 4px;
}
.p-head-body .p-sub {
    margin-top: 5px;
    font-size: 12px;
    color: var(--txt-on-paper-dim);
    font-weight: 500;
}
.p-head-body .p-sub .k {
    font-family: 'JetBrains Mono', monospace;
    background: var(--wash-paper-004);
    padding: 1px 5px;
    border-radius: 3px;
    color: var(--txt-on-paper);
    font-size: 10.5px;
}
.p-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px 14px;
}
.p-cell {
    background: var(--paper-1);
    border: 1px solid var(--paper-4);
    border-radius: 6px;
    padding: 9px 11px 10px;
    min-width: 0;
}
.p-cell .k {
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1.6px;
    text-transform: uppercase;
    color: var(--txt-on-paper-mute);
}
.p-cell .v {
    margin-top: 3px;
    font-size: 12.5px;
    font-weight: 600;
    color: var(--txt-on-paper);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-family: 'JetBrains Mono', monospace;
}
.p-cell .v.text { font-family: 'DM Sans', -apple-system, "Segoe UI", sans-serif; }
.p-cell .v.dim  { color: var(--txt-on-paper-mute); font-weight: 500; }
.p-cell.wide { grid-column: 1 / -1; }
.p-actions {
    display: flex; gap: 8px; justify-content: flex-end;
    padding-top: 14px;
    border-top: 1px solid var(--paper-4);
}
.p-btn {
    background: var(--ink);
    color: var(--paper);
    border: none;
    border-radius: 5px;
    padding: 8px 14px;
    font-family: inherit;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    cursor: pointer;
    transition: background .15s ease, transform .1s ease;
}
.p-btn:hover { background: var(--ink-3); }
.p-btn:active { transform: scale(.97); }
.p-btn.ghost {
    background: transparent;
    color: var(--txt-on-paper);
    border: 1px solid var(--paper-5);
}
.p-btn.ghost:hover { background: var(--paper-2); }
#main {
    grid-area: main;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: var(--ink);
    overflow: hidden;
}
#section-head {
    height: 44px;
    padding: 0 20px;
    display: flex;
    align-items: center;
    gap: 14px;
    border-bottom: 1px solid var(--stroke-ink-soft);
    background: var(--ink);
    flex-shrink: 0;
}
#section-head .section-title {
    font-size: 13px;
    font-weight: 700;
    letter-spacing: .3px;
    color: var(--txt-on-ink);
    display: flex;
    align-items: center;
    gap: 8px;
}
#section-head .section-title .sq {
    width: 6px; height: 6px;
    background: var(--txt-on-ink);
    box-shadow: 0 0 6px rgba(255,255,255,.5);
    border-radius: 1px;
}
#section-head .breadcrumb {
    font-size: 11px;
    color: var(--txt-on-ink-mute);
    font-weight: 500;
}
#section-head .breadcrumb b {
    color: var(--txt-on-ink-dim);
    font-weight: 600;
}
#section-head .section-tools {
    margin-left: auto;
    display: flex;
    align-items: center;
    gap: 8px;
}
.section-pill {
    padding: 4px 10px;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: .5px;
    background: var(--ink-3);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 999px;
    color: var(--txt-on-ink-dim);
    display: flex;
    align-items: center;
    gap: 6px;
}
.section-pill .n {
    font-family: 'JetBrains Mono', monospace;
    color: var(--txt-on-ink);
}
#panels {
    flex: 1;
    position: relative;
    overflow: hidden;
}
.panel {
    position: absolute;
    inset: 0;
    padding: 16px 20px 60px;
    overflow-y: auto;
    opacity: 0;
    pointer-events: none;
    transform: translateY(6px);
    transition: opacity .22s ease, transform .22s cubic-bezier(.34,1.2,.64,1);
}
.panel::-webkit-scrollbar { width: 0; }
.panel.on {
    opacity: 1;
    pointer-events: auto;
    transform: translateY(0);
}
.g2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    align-items: start;
}
.col {
    display: flex;
    flex-direction: column;
    gap: 14px;
}
.g2.players-layout {
    grid-template-columns: minmax(0, 1fr) 260px;
    align-items: stretch;
    height: 100%;
}
.g2.players-layout .col        { min-width: 0; }
.panel-players .g2.players-layout .action-rail { position: sticky; top: 0; }
.g2.players-layout .action-rail .card + .card { margin-top: 10px; }
.g2.players-layout .player-list-card { height: 100%; max-height: 100%; display: flex; flex-direction: column; overflow: hidden; }
.g2.players-layout .player-list-card .plist {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding-right: 4px;
}
.plist::-webkit-scrollbar { width: 6px; }
.plist::-webkit-scrollbar-track { background: transparent; }
.plist::-webkit-scrollbar-thumb { background: rgba(255,255,255,.22); border-radius: 3px; }
.g2.players-layout .player-list-card .plist::-webkit-scrollbar { width: 4px; }
.g2.players-layout .player-list-card .plist::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,.15);
    border-radius: 4px;
}
.g2.players-layout .action-rail .btn-full { width: 100%; margin-top: 8px; }
.btn-grid {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.g2.players-layout .action-rail .btn {
    width: 100%;
    justify-content: flex-start;
    padding: 10px 12px;
}
.card {
    background: var(--ink-2);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 10px;
    padding: 14px 15px;
    position: relative;
    overflow: visible;
    box-shadow: var(--card-shadow);
    transition:
        border-color .25s ease,
        box-shadow .25s ease,
        transform .25s ease;
}
.card::before {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,.32), transparent);
    pointer-events: none;
}
.card:hover {
    border-color: rgba(var(--text-rgb),.28);
    box-shadow: var(--card-shadow-hover);
    transform: translateY(-1px);
}
.card-head {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0 0 12px;
}
.card-head .card-title {
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1.8px;
    text-transform: uppercase;
    color: rgba(var(--text-rgb),.6);
    display: flex;
    align-items: center;
    gap: 8px;
}
.card-head .card-title::before {
    content: "";
    display: inline-block;
    width: 3px; height: 3px;
    background: var(--txt-on-ink);
    box-shadow: 0 0 6px rgba(255,255,255,.55);
    border-radius: 1px;
}
.card-head .card-count {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px;
    color: var(--txt-on-ink-mute);
    padding: 1px 6px;
    background: var(--wash-ink-006);
    border-radius: 3px;
    letter-spacing: .3px;
}
.card-head::after {
    content: "";
    flex: 1;
    height: 1px;
    background: linear-gradient(90deg, rgba(255,255,255,.12), transparent);
}
.feat {
    position: relative;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 7px 8px;
    border: 1px solid transparent;
    border-radius: 7px;
    cursor: pointer;
    transition: background .15s ease, border-color .15s ease;
}
.feat + .feat { margin-top: 2px; }
.pulse-highlight {
    animation: pulseHi 1.2s ease-out !important;
    border-radius: 8px;
}
@keyframes pulseHi {
    0%   { box-shadow: 0 0 0 0 rgba(255,255,255,0), 0 0 0 0 rgba(255,255,255,0); }
    30%  { box-shadow: 0 0 0 2px rgba(255,255,255,.85), 0 0 22px 4px rgba(255,255,255,.4); }
    100% { box-shadow: 0 0 0 0 rgba(255,255,255,0), 0 0 0 0 rgba(255,255,255,0); }
}
.feat::before {
    content: "";
    position: absolute;
    left: -1px; top: 20%; bottom: 20%;
    width: 2px;
    background: linear-gradient(180deg, rgba(255,255,255,.5), #FFFFFF, rgba(255,255,255,.5));
    border-radius: 2px;
    box-shadow: 0 0 6px rgba(255,255,255,.4);
    opacity: 0;
    transition: opacity .18s ease;
    pointer-events: none;
}
.feat:hover { background: var(--wash-ink-004); }
.feat.on {
    background: var(--wash-ink-006);
    border-color: rgba(var(--text-rgb),.18);
}
.feat.on:hover { background: var(--wash-ink-010); }
.feat.on::before { opacity: 1; }
.feat.on .feat-name { color: var(--txt-on-ink); }
.feat.on .feat-ico {
    background: rgba(255,255,255,.14);
    border-color: var(--stroke-ink-glow);
}
.feat.on .feat-ico svg { stroke: var(--txt-on-ink); }
.feat-ico {
    width: 28px; height: 28px;
    border-radius: 7px;
    background: var(--ink-4);
    border: 1px solid var(--stroke-ink-soft);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    transition: background .15s ease, border-color .15s ease;
}
.feat-ico svg {
    width: 14px; height: 14px;
    stroke: rgba(255,255,255,.6);
    stroke-width: 1.6;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: stroke .15s ease;
}
.feat-body { flex: 1; min-width: 0; }
.feat-name {
    font-size: 12.5px;
    font-weight: 600;
    color: rgba(var(--text-rgb),.75);
    line-height: 1.2;
    transition: color .15s ease;
}
.feat-desc {
    font-size: 10.5px;
    font-weight: 500;
    color: var(--txt-on-ink-mute);
    line-height: 1.35;
    margin-top: 2px;
}
.feat-tail {
    display: flex;
    align-items: center;
    gap: 6px;
}
.chip {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px;
    font-weight: 600;
    padding: 2px 6px;
    background: var(--wash-ink-006);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 4px;
    color: var(--txt-on-ink-dim);
    letter-spacing: .5px;
    text-transform: uppercase;
}

@keyframes swPop { 0%{transform:scale(1)} 40%{transform:scale(.9)} 100%{transform:scale(1)} }
.sw.pop { animation: swPop .28s ease; }
@keyframes knobPop { 0%{transform:scale(1)} 50%{transform:scale(1.25)} 100%{transform:scale(1)} }
.sw.pop::after { animation: knobPop .3s ease; }
.sw {
    width: 34px; height: 18px;
    border-radius: 10px;
    background: var(--ink-4);
    border: 1px solid var(--stroke-ink-soft);
    position: relative;
    flex-shrink: 0;
    transition: background .28s ease, border-color .28s ease, box-shadow .28s ease;
}
.sw::after {
    content: "";
    position: absolute;
    top: 2px; left: 2px;
    width: 12px; height: 12px;
    border-radius: 50%;
    background: #C8C8C8;
    box-shadow: inset 0 1px 2px rgba(0,0,0,.5);
    transition: left .28s cubic-bezier(.34,1.4,.64,1),
                background .28s ease,
                box-shadow .28s ease;
}
.sw.on {
    background: linear-gradient(90deg, rgba(255,255,255,.20), rgba(255,255,255,.32));
    border-color: var(--stroke-ink-glow);
    box-shadow: 0 0 12px rgba(255,255,255,.35), inset 0 0 6px rgba(255,255,255,.15);
}
.sw.on::after {
    left: 18px;
    background: linear-gradient(180deg, #FFFFFF, #E0E0E0);
    box-shadow: 0 0 8px rgba(255,255,255,.6), 0 0 14px rgba(255,255,255,.4);
}
.bind {
    width: 24px; height: 22px;
    border-radius: 5px;
    background: transparent;
    border: 1px solid transparent;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    transition: all .15s ease;
    flex-shrink: 0;
    cursor: pointer;
}
.feat:hover .bind, .feat.cursor-hover .bind, .feat.on .bind { opacity: 1; background: rgba(255,255,255,.06); border-color: rgba(255,255,255,.18); }
.bind:hover, .bind.cursor-hover {
    opacity: 1 !important;
    background: #fff !important;
    border-color: #fff !important;
    transform: scale(1.1);
}
.bind:hover svg, .bind.cursor-hover svg { stroke: #000 !important; }
.bind.set {
    opacity: 1 !important;
    background: #fff;
    border-color: #fff;
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px;
    font-weight: 800;
    color: #000;
    padding: 0 6px;
    letter-spacing: .5px;
    min-width: 24px;
}
.bind svg {
    width: 12px; height: 12px;
    stroke: rgba(255,255,255,.6);
    stroke-width: 1.6;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: stroke .15s ease;
}
.bind:hover svg { stroke: var(--txt-on-ink); }
.btn {
    position: relative;
    width: 100%;
    padding: 10px 16px;
    border-radius: 7px;
    border: 1px solid var(--stroke-ink-hard);
    background: transparent;
    color: rgba(var(--text-rgb),.9);
    font-family: inherit;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: .3px;
    cursor: pointer;
    overflow: hidden;
    transition: all .25s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}
.btn + .btn { margin-top: 6px; }
.btn::before {
    content: "";
    position: absolute;
    top: 0; left: -100%;
    width: 30%; height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,.45), transparent);
    transform: skewX(-25deg);
    transition: left .5s ease;
}
.btn:hover {
    background: var(--wash-ink-015);
    border-color: rgba(var(--text-rgb),.5);
    color: var(--txt-on-ink);
    text-shadow: 0 0 10px rgba(255,255,255,.4);
}
.btn:hover::before { left: 130%; transition: left .8s ease; }
.btn:active {
    background: var(--wash-ink-020);
    box-shadow: 0 0 20px rgba(255,255,255,.35);
    transform: scale(.97);
    transition: transform .08s ease, background .06s ease, box-shadow .06s ease;
}
.btn.primary {
    background: var(--txt-on-ink);
    color: var(--ink);
    border-color: var(--txt-on-ink);
}
.btn.primary:hover {
    background: rgba(255,255,255,.9);
    color: var(--ink);
    text-shadow: none;
    box-shadow: 0 0 20px rgba(255,255,255,.5);
}
.btn.soft {
    border-color: var(--stroke-ink-soft);
    color: var(--txt-on-ink-dim);
}
.btn.risky {
    background-image: repeating-linear-gradient(45deg,
        transparent 0 6px,
        rgba(255,255,255,.05) 6px 7px);
    animation: riskyStripe .9s linear infinite;
}
.btn.risky:hover {
    background: var(--txt-on-ink);
    color: var(--ink);
    border-color: var(--txt-on-ink);
    text-shadow: none;
    animation: riskyStripe .5s linear infinite, riskyFlash 1s ease-in-out infinite;
}
@keyframes riskyStripe {
    from { background-position: 0 0; }
    to   { background-position: 12px 0; }
}
@keyframes riskyFlash {
    0%, 100% { background: #FFFFFF; }
    50%      { background: rgba(255,255,255,.9); }
}
.btn svg {
    width: 13px; height: 13px;
    stroke: currentColor;
    stroke-width: 1.8;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
}
.btn-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
}
.btn-grid .btn { margin: 0; }
.btn-grid + .btn-grid { margin-top: 10px; }
/* -- click feedback (JS-driven, works with Lua cursor) -- */
.om-press { transform: scale(.97) !important; transition: transform .06s ease !important; }
.om-click { animation: omClick .38s ease-out; }
.btn.primary.om-click, .nav-btn.active.om-click { animation-name: omClickDark; }
@keyframes omClick {
    0%   { box-shadow: 0 0 0 0 rgba(255,255,255,.55), inset 0 0 0 999px rgba(255,255,255,.14); transform: scale(.96); }
    100% { box-shadow: 0 0 0 7px rgba(255,255,255,0),  inset 0 0 0 999px rgba(255,255,255,0);   transform: scale(1); }
}
@keyframes omClickDark {
    0%   { box-shadow: 0 0 0 0 rgba(255,255,255,.55), inset 0 0 0 999px rgba(0,0,0,.18); transform: scale(.96); }
    100% { box-shadow: 0 0 0 7px rgba(255,255,255,0),  inset 0 0 0 999px rgba(0,0,0,0);   transform: scale(1); }
}
.sl { padding: 6px 4px; }
.sl-head {
    display: flex;
    justify-content: space-between;
    margin-bottom: 8px;
    font-size: 11.5px;
}
.sl-lbl {
    color: var(--txt-on-ink-dim);
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 6px;
}
.sl-val {
    color: var(--txt-on-ink);
    font-weight: 700;
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    padding: 1px 7px;
    background: var(--wash-ink-006);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 3px;
}
.sl-track {
    position: relative;
    height: 4px;
    background: var(--ink-4);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 3px;
    cursor: pointer;
    transition: border-color .15s ease;
}
.sl-track:hover { border-color: rgba(var(--text-rgb),.35); }
.sl-fill {
    position: absolute;
    left: 0; top: 0; bottom: 0;
    border-radius: 3px;
    background: linear-gradient(90deg, #FFFFFF, #E0E0E0, #FFFFFF);
    background-size: 200% 100%;
    animation: paperShimmer 3.5s linear infinite;
    box-shadow: 0 0 8px rgba(255,255,255,.35), inset 0 0 4px rgba(255,255,255,.25);
}
.sl-thumb {
    position: absolute;
    top: -5.5px; right: -7px;
    width: 13px; height: 13px;
    border-radius: 50%;
    background: radial-gradient(circle at 30% 30%, #FFFFFF, #E5E5E5 60%, #C0C0C0 100%);
    border: 1.5px solid #FFFFFF;
    box-shadow:
        0 0 10px rgba(255,255,255,.6),
        0 0 18px rgba(255,255,255,.25),
        inset 0 1px 1px rgba(255,255,255,.6);
    transition: transform .15s cubic-bezier(.34,1.4,.64,1), box-shadow .15s ease;
}
.sl-thumb:hover {
    transform: scale(1.2);
    box-shadow: 0 0 14px rgba(255,255,255,.8), 0 0 24px rgba(255,255,255,.4);
}
@keyframes paperShimmer {
    from { background-position: 0 0; }
    to   { background-position: -200% 0; }
}
.dd { position: relative; padding: 4px 0; }
.lbl {
    display: block;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: .5px;
    color: var(--txt-on-ink-mute);
    margin: 6px 0 4px;
    text-transform: uppercase;
}
.dd-btn {
    width: 100%;
    padding: 8px 12px;
    background: var(--ink-4);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 6px;
    font-family: inherit;
    font-size: 12px;
    font-weight: 500;
    color: var(--txt-on-ink);
    text-align: left;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    transition: border-color .15s ease, box-shadow .15s ease;
}
.dd-btn::after {
    content: "";
    width: 8px; height: 8px;
    border-right: 1.5px solid var(--txt-on-ink-mute);
    border-bottom: 1.5px solid var(--txt-on-ink-mute);
    transform: rotate(45deg) translate(-2px, -2px);
    transition: transform .18s ease, border-color .18s ease;
}
.dd.open .dd-btn::after {
    transform: rotate(-135deg) translate(-2px, -2px);
    border-color: var(--txt-on-ink);
}
.dd.open .dd-btn, .dd-btn:hover {
    border-color: rgba(var(--text-rgb),.35);
    box-shadow: 0 0 10px rgba(255,255,255,.10);
}
.dd-caret { font-size: 9px; opacity: .5; margin-left: 8px; transition: transform .18s ease; display: inline-block; }
.dd.open .dd-caret { transform: rotate(180deg); opacity: .8; }
.dd-btn { display: flex; align-items: center; justify-content: space-between; }
.dd-list {
    position: absolute;
    top: calc(100% + 4px);
    left: 0; right: 0;
    max-height: 260px;
    overflow-y: auto;
    overflow-x: hidden;
    background: var(--ink-3);
    border: 1px solid rgba(255,255,255,.18);
    border-radius: 6px;
    box-shadow: 0 10px 30px rgba(0,0,0,.7), inset 0 0 0 1px rgba(255,255,255,.08);
    display: none;
    z-index: 99999;
}
.dd-list::-webkit-scrollbar { width: 6px; }
.dd-list::-webkit-scrollbar-track { background: transparent; }
.dd-list::-webkit-scrollbar-thumb { background: rgba(255,255,255,.22); border-radius: 3px; }
.dd.open .dd-list { display: block; animation: fadeIn .15s ease; }
.dd.open { z-index: 500; position: relative; }
.dd-up 
.dd.open .dd-list::-webkit-scrollbar { width: 3px; }
.dd-list::-webkit-scrollbar-thumb { background: rgba(255,255,255,.15); border-radius: 2px; }
.dd-opt {
    padding: 8px 12px;
    font-size: 12px;
    color: rgba(var(--text-rgb),.6);
    cursor: pointer;
    transition: background .15s ease, color .15s ease;
    display: flex;
    align-items: center;
    gap: 8px;
}
.dd-opt:hover { background: rgba(255,255,255,.08); color: var(--txt-on-ink); }
.dd-opt.selected {
    background: rgba(255,255,255,.05);
    color: var(--txt-on-ink);
    font-weight: 600;
}
.dd-opt.selected::before {
    content: "";
    width: 4px; height: 4px;
    background: var(--txt-on-ink);
    border-radius: 50%;
    box-shadow: 0 0 6px rgba(255,255,255,.55);
}
@keyframes ddSlideIn {
    from { opacity: 0; transform: translateY(-4px); }
    to   { opacity: 1; transform: translateY(0); }
}
.inp {
    width: 100%;
    padding: 8px 12px;
    background: var(--ink-4);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 6px;
    color: var(--txt-on-ink);
    font-family: inherit;
    font-size: 12px;
    font-weight: 500;
    outline: none;
    transition: border-color .15s ease, box-shadow .15s ease;
}
.inp::placeholder { color: rgba(var(--text-rgb),.35); }
.inp:focus {
    border-color: var(--stroke-ink-glow);
    box-shadow: 0 0 10px rgba(255,255,255,.15);
}
/* Clear "you are typing here" indicator */
.inp:focus, .inp-focused .inp, .psearch.focused .psearch-inp {
    border-color: #7c5cff !important;
    box-shadow: 0 0 0 2px rgba(124,92,255,.35), 0 0 14px rgba(124,92,255,.25) !important;
    background: var(--ink-3) !important;
}
.inp:focus, .inp-focused .inp { caret-color: #7c5cff; }
/* Focus animation: any text box you click into pops, then keeps a soft breathing glow,
   and gets a drawn blinking caret (#om-caret) since the DUI doesn't paint a native one. */
input.om-typing, textarea.om-typing {
    border-color: #7c5cff !important;
    background: var(--ink-3) !important;
    caret-color: transparent !important;
    animation: omFocusPop .32s cubic-bezier(.2,.9,.3,1.3), omFocusBreathe 1.8s ease-in-out .32s infinite;
}
@keyframes omFocusPop {
    0%   { transform: scale(1);     box-shadow: 0 0 0 0 rgba(124,92,255,.75); }
    45%  { transform: scale(1.025); box-shadow: 0 0 0 5px rgba(124,92,255,.35), 0 0 18px rgba(124,92,255,.45); }
    100% { transform: scale(1);     box-shadow: 0 0 0 2px rgba(124,92,255,.35), 0 0 14px rgba(124,92,255,.25); }
}
@keyframes omFocusBreathe {
    0%, 100% { box-shadow: 0 0 0 2px rgba(124,92,255,.35), 0 0 14px rgba(124,92,255,.25); }
    50%      { box-shadow: 0 0 0 2px rgba(124,92,255,.55), 0 0 22px rgba(124,92,255,.45); }
}
#om-caret {
    position: fixed;
    width: 2px;
    border-radius: 1px;
    background: #9d85ff;
    box-shadow: 0 0 6px rgba(124,92,255,.9);
    pointer-events: none;
    z-index: 2147483646;
    display: none;
    animation: omCaretBlink 1s steps(1) infinite;
}
@keyframes omCaretBlink { 0%, 55% { opacity: 1; } 56%, 100% { opacity: 0; } }
/* Player search bar */
.psearch {
    position: relative;
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0 0 8px;
    padding: 0 10px;
    background: var(--ink-4);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 8px;
    transition: border-color .15s ease, box-shadow .15s ease;
}
.psearch-ico { display: flex; opacity: .5; flex-shrink: 0; }
.psearch-ico svg { width: 14px; height: 14px; }
.psearch-inp {
    flex: 1;
    background: transparent;
    border: none;
    outline: none;
    color: var(--txt-on-ink);
    font-family: inherit;
    font-size: 12px;
    font-weight: 500;
    padding: 9px 0;
    caret-color: #7c5cff;
}
.psearch-inp::placeholder { color: var(--txt-on-ink-mute); }
.psearch-count {
    font-size: 10px;
    color: var(--txt-on-ink-mute);
    white-space: nowrap;
    flex-shrink: 0;
}
.seg {
    display: flex;
    background: var(--ink-4);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 6px;
    padding: 2px;
    gap: 2px;
    margin: 4px 0;
}
.seg-opt {
    flex: 1;
    padding: 6px 10px;
    font-size: 11px;
    font-weight: 600;
    color: var(--txt-on-ink-mute);
    text-align: center;
    border-radius: 4px;
    cursor: pointer;
    transition: all .15s ease;
    letter-spacing: .3px;
}
.seg-opt:hover { color: var(--txt-on-ink-dim); }
.seg-opt.on {
    background: var(--wash-ink-020);
    color: var(--txt-on-ink);
    box-shadow: 0 0 0 1px rgba(255,255,255,.18), 0 0 10px rgba(255,255,255,.06);
}
.dline {
    height: 1px;
    background: var(--stroke-ink-hair);
    margin: 8px 0;
}
.hint {
    font-size: 10.5px;
    color: var(--txt-on-ink-mute);
    line-height: 1.4;
    padding: 6px 8px;
    background: var(--wash-ink-004);
    border-left: 2px solid var(--stroke-ink-soft);
    border-radius: 0 4px 4px 0;
    margin: 4px 0;
    font-style: italic;
}
.plist { padding: 4px 0; }
.pitem {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 6px 9px;
    margin-bottom: 3px;
    border: 1px solid transparent;
    border-radius: 7px;
    cursor: pointer;
    background: rgba(255,255,255,.015);
    transition: all .15s ease;
}
.pitem + .pitem { margin-top: 2px; }
.pitem:hover { background: var(--wash-ink-006); border-color: var(--stroke-ink-soft); }
.pitem.sel { background: rgba(255,255,255,.08); border-color: rgba(255,255,255,.3); box-shadow: inset 0 0 0 1px rgba(255,255,255,.12); }
.pav {
    width: 24px; height: 24px;
    border-radius: 50%;
    background: var(--ink-5);
    border: 1px solid var(--stroke-ink-soft);
    display: flex; align-items: center; justify-content: center;
    font-size: 10px; font-weight: 700;
    color: var(--txt-on-ink-dim);
    flex-shrink: 0;
}
.pitem.sel .pav {
    background: #7c5cff;
    color: #fff;
    border-color: #a78bff;
    box-shadow: 0 0 10px rgba(124,92,255,.6);
}
.pinfo { flex: 1; min-width: 0; }
.pname {
    font-size: 11.5px;
    font-weight: 600;
    color: var(--txt-on-ink);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.psub {
    font-size: 9.5px;
    color: var(--txt-on-ink-mute);
    font-family: 'JetBrains Mono', monospace;
}
.plist { display: block; padding: 4px 0; }
/* Players tab: panel itself must NOT scroll - only the .plist scrolls.
   Height-locked so the flex list can size and scroll internally. */
.panel.panel-players { overflow: hidden; display: flex; flex-direction: column; }
.panel.panel-players .g2.players-layout { flex: 1; min-height: 0; height: auto; }
.panel.panel-players .col { min-height: 0; }
.panel-players .col { height: 100%; }
.pitem { position: relative; padding-left: 12px; }
.pitem .prail {
    position: absolute;
    left: 3px; top: 8px; bottom: 8px;
    width: 3px;
    border-radius: 3px;
    background: var(--txt-on-ink-mute);
    opacity: .55;
    transition: opacity .15s ease, background .15s ease;
}
.pitem:hover .prail, .pitem.sel .prail { opacity: 1; }
.pitem.sel .prail { background: #7c5cff; box-shadow: 0 0 8px rgba(124,92,255,.7); }
.pinfo .prow2 {
    display: flex;
    gap: 5px;
    margin-top: 2px;
    flex-wrap: nowrap;
    align-items: center;
}
.p-chip {
    font-family: 'JetBrains Mono', monospace;
    font-size: 8.5px;
    font-weight: 600;
    padding: 1.5px 5px;
    background: var(--wash-ink-006);
    border: 1px solid var(--stroke-ink-hair);
    border-radius: 3px;
    color: var(--txt-on-ink-dim);
    letter-spacing: .3px;
    line-height: 1.3;
    text-transform: uppercase;
}
.p-chip.veh { background: var(--wash-ink-015); color: var(--txt-on-ink); border-color: var(--stroke-ink-soft); }
.p-chip.dead { background: transparent; color: var(--txt-on-ink-mute); text-decoration: line-through; }
.p-chip.dot { padding: 1.5px 4px 1.5px 4px; }
.p-chip.dot::before {
    content: "";
    display: inline-block;
    width: 5px; height: 5px;
    border-radius: 50%;
    background: currentColor;
    margin-right: 4px;
    vertical-align: 1px;
    box-shadow: 0 0 4px currentColor;
}
.pitem.me { background: rgba(255,255,255,.03); border-color: var(--stroke-ink-soft); }
.pitem.me .pname::after {
    content: "YOU";
    display: inline-block;
    background: var(--txt-on-ink);
    color: var(--ink);
    font-size: 7.5px;
    font-weight: 800;
    padding: 1px 4px;
    border-radius: 2px;
    margin-left: 6px;
    vertical-align: 1px;
    letter-spacing: .8px;
}
.plist-empty {
    text-align: center;
    padding: 20px 8px;
    color: var(--txt-on-ink-mute);
    font-size: 10.5px;
    letter-spacing: 1px;
    text-transform: uppercase;
}
.cfg-item {
    position: relative;
    padding: 8px 8px 8px 12px;
    border: 1px solid transparent;
    border-radius: 7px;
    display: flex;
    align-items: center;
    gap: 10px;
    cursor: pointer;
    transition: all .15s ease;
}
.cfg-item + .cfg-item { margin-top: 2px; }
.cfg-item:hover { background: var(--wash-ink-006); border-color: var(--stroke-ink-soft); }
.cfg-item .prail {
    position: absolute; left: 3px; top: 8px; bottom: 8px;
    width: 3px; border-radius: 3px;
    background: var(--paper-6); opacity: .55;
}
.cfg-item:hover .prail { opacity: 1; }
.cfg-body { flex: 1; min-width: 0; }
.cfg-name {
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    font-weight: 600;
    color: var(--txt-on-ink);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.cfg-meta {
    font-size: 9px;
    color: var(--txt-on-ink-mute);
    letter-spacing: .5px;
    text-transform: uppercase;
    margin-top: 3px;
}
.cfg-actions { display: flex; gap: 3px; }
.cfg-btn {
    font-family: 'JetBrains Mono', monospace;
    font-size: 8.5px;
    font-weight: 700;
    letter-spacing: .8px;
    padding: 3px 7px;
    background: var(--wash-ink-006);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 3px;
    color: var(--txt-on-ink-dim);
    cursor: pointer;
    transition: all .12s ease;
}
.cfg-btn:hover { background: var(--txt-on-ink); color: var(--ink); border-color: var(--txt-on-ink); }
.cfg-btn.del:hover { background: var(--paper); color: var(--ink); }
.pping {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px;
    font-weight: 600;
    padding: 2px 6px;
    background: var(--wash-ink-006);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 4px;
    color: var(--txt-on-ink);
    letter-spacing: .5px;
}
#toasts {
    position: fixed;
    top: 20px; right: 20px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    z-index: 200;
    pointer-events: none;
}
.toast {
    position: relative;
    min-width: 240px;
    max-width: 340px;
    padding: 10px 14px 14px;
    background: linear-gradient(135deg, #0A0A0A, #141414);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 8px;
    display: flex;
    gap: 10px;
    box-shadow: 0 12px 32px rgba(0,0,0,.8);
    animation: toastEnter .35s cubic-bezier(.22,1,.36,1);
    overflow: hidden;
    pointer-events: auto;
}
.toast.leaving { animation: toastExit .2s ease forwards; }
.toast .stripe {
    position: absolute;
    top: 10px; bottom: 10px; left: 0;
    width: 3px;
    background: var(--txt-on-ink);
    border-radius: 0 2px 2px 0;
}
.toast.failure .stripe {
    background: repeating-linear-gradient(0deg,
        var(--txt-on-ink) 0 4px,
        transparent 4px 7px);
}
/* Per-severity color coding for at-a-glance reading */
.toast.success .stripe, .toast.success .bar { background: #35d07f; }
.toast.success .ico { background: rgba(53,208,127,.16); border-color: rgba(53,208,127,.5); color: #35d07f; }
.toast.failure .stripe { background: #ff5c5c; }
.toast.failure .bar    { background: #ff5c5c; }
.toast.failure .ico { background: rgba(255,92,92,.16); border-color: rgba(255,92,92,.5); color: #ff5c5c; }
.toast.info .stripe, .toast.info .bar { background: #5c8cff; }
.toast.info .ico { background: rgba(92,140,255,.16); border-color: rgba(92,140,255,.5); color: #5c8cff; }
.toast .ico svg { width: 14px; height: 14px; }
.toast .ico {
    width: 24px; height: 24px;
    border-radius: 6px;
    background: rgba(255,255,255,.14);
    border: 1px solid rgba(255,255,255,.32);
    flex-shrink: 0;
    display: flex; align-items: center; justify-content: center;
}
.toast .ico svg {
    width: 12px; height: 12px;
    stroke: var(--txt-on-ink);
    stroke-width: 2;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
}
.toast .body { flex: 1; min-width: 0; }
.toast .title {
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--txt-on-ink);
    margin-bottom: 4px;
}
.toast .msg {
    font-size: 12px;
    font-weight: 500;
    color: rgba(255,255,255,.85);
    line-height: 1.4;
}
.toast .bar {
    position: absolute;
    left: 8px; bottom: 4px;
    height: 2px;
    width: calc(100% - 16px);
    background: var(--txt-on-ink);
    transform-origin: left center;
    animation: progressDrain 2.5s linear forwards;
}
@keyframes toastEnter {
    from { opacity: 0; transform: translateX(30px); }
    to   { opacity: 1; transform: translateX(0); }
}
@keyframes toastExit {
    to { opacity: 0; transform: translateX(12px) scale(.97); }
}
@keyframes progressDrain {
    from { transform: scaleX(1); }
    to   { transform: scaleX(0); }
}
#watermark {
    display: none;
    position: fixed;
    bottom: 14px; right: 16px;
    font-family: 'DM Sans', sans-serif;
    font-size: 16px;
    font-weight: 900;
    letter-spacing: 3px;
    color: var(--txt-on-ink);
    text-shadow:
        0 0 4px rgba(0,0,0,.9),
        0 0 12px rgba(0,0,0,.85),
        0 0 22px rgba(0,0,0,.85),
        0 1px 2px #000;
    pointer-events: none;
    z-index: 300;
    user-select: none;
}
#watermark::before {
    content: "&bull;";
    margin-right: 6px;
    opacity: .7;
}
#watermark.tl { top: 12px; left: 14px; }
#watermark.tr { top: 12px; right: 14px; }
#watermark.bl { bottom: 12px; left: 14px; }
#watermark.br { bottom: 12px; right: 14px; }
#watermark.hidden { display: none; }
#admin-list {
    position: fixed;
    top: 12px; right: 14px;
    z-index: 250;
    pointer-events: none;
    background: rgba(0,0,0,.78);
    border: 1px solid rgba(255,255,255,.14);
    border-radius: 8px;
    padding: 8px 10px 6px;
    min-width: 190px;
    max-width: 260px;
    box-shadow: 0 8px 22px rgba(0,0,0,.55);
    font-family: 'DM Sans', sans-serif;
    display: none;
}
#admin-list.show { display: block; }
.al-head {
    display: flex; align-items: center; justify-content: space-between;
    gap: 8px;
    padding-bottom: 6px;
    border-bottom: 1px solid var(--stroke-ink-soft);
}
.al-title {
    font-size: 9.5px;
    font-weight: 800;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--txt-on-ink);
}
.al-count {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px;
    background: var(--txt-on-ink);
    color: var(--ink);
    padding: 1px 6px;
    border-radius: 999px;
    font-weight: 800;
}
.al-rows { display: flex; flex-direction: column; gap: 3px; padding-top: 5px; }
.al-row {
    display: flex; align-items: center; gap: 6px;
    padding: 3px 4px;
}
.al-row .al-dot {
    width: 6px; height: 6px;
    border-radius: 50%;
    background: var(--txt-on-ink);
    box-shadow: 0 0 5px var(--txt-on-ink);
    flex-shrink: 0;
}
.al-name {
    flex: 1; min-width: 0;
    font-size: 11px;
    font-weight: 600;
    color: var(--txt-on-ink);
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.al-dist {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px;
    color: var(--txt-on-ink-mute);
    letter-spacing: .3px;
}
#bubbleseeroverlay {
    position: fixed;
    top: 90px; right: 20px;
    z-index: 260;
    min-width: 180px; max-width: 230px; max-height: 55vh;
    overflow-y: auto;
    background: #0d0d0f;
    border: 1px solid rgba(255,255,255,.1);
    border-radius: 10px;
    padding: 11px 12px;
    color: #fff;
    font-family: 'DM Sans', -apple-system, sans-serif;
    display: none;
    pointer-events: none;
}
#bubbleseeroverlay.show { display: block; }
#bubbleseeroverlay::-webkit-scrollbar { width: 3px; }
#bubbleseeroverlay::-webkit-scrollbar-thumb { background: rgba(255,255,255,.2); border-radius: 2px; }
#bubbleseeroverlay .spec-head {
    font-size: 9.5px; font-weight: 700; letter-spacing: 1.6px;
    text-transform: uppercase; color: rgba(255,255,255,.5);
    margin-bottom: 8px; padding-bottom: 7px;
    border-bottom: 1px solid rgba(255,255,255,.08);
    display: flex; align-items: center; gap: 7px;
}
#bubbleseeroverlay .spec-head .dot { width: 6px; height: 6px; border-radius: 50%; background: #fff; }
#bubbleseeroverlay .spec-head .cnt {
    margin-left: auto; font-family: 'JetBrains Mono', monospace;
    font-size: 10px; font-weight: 700; color: #000;
    background: #fff; border-radius: 999px; padding: 1px 7px;
}
#bubbleseeroverlay .spec-row {
    display: flex; align-items: center; gap: 8px;
    font-size: 12px; font-weight: 600; padding: 4px 3px; color: rgba(255,255,255,.9);
}
.snm { flex: 1; font-size: 12px; font-weight: 600; color: #fff; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#bubbleseeroverlay .spec-row + .spec-row { margin-top: 1px; }
#bubbleseeroverlay .spec-row .sav {
    width: 20px; height: 20px; min-width: 20px; border-radius: 50%;
    background: rgba(255,255,255,.1); color: #fff;
    display: flex; align-items: center; justify-content: center;
    font-size: 9px; font-weight: 800;
}
#bubbleseeroverlay .spec-row .sid {
    margin-left: auto; font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px; color: rgba(255,255,255,.4);
}
#bubbleseeroverlay .spec-empty {
    font-size: 11px; color: rgba(255,255,255,.4);
    text-align: center; padding: 6px 0; font-weight: 500;
}
@keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.4} }
@keyframes ovSlideL { from { opacity: 0; transform: translateX(-24px); } to { opacity: 1; transform: none; } }
@keyframes ovSlideR { from { opacity: 0; transform: translateX(24px); } to { opacity: 1; transform: none; } }
@keyframes ovRowIn { from { opacity: 0; transform: translateX(-8px); } to { opacity: 1; transform: none; } }
@keyframes ovPulse { 0%,100% { opacity: 1; transform: scale(1); } 50% { opacity: .4; transform: scale(.8); } }
#spectatoroverlay.show { display: block; animation: ovSlideL .4s cubic-bezier(.2,.9,.3,1) both; }
#bubbleseeroverlay.show { animation: ovSlideR .4s cubic-bezier(.2,.9,.3,1) both; }
#spectatoroverlay .spec-row, #bubbleseeroverlay .spec-row { animation: ovRowIn .3s ease both; }
#spectatoroverlay .spec-head .dot, #bubbleseeroverlay .spec-head .dot { animation: ovPulse 1.5s infinite; }
#spectatoroverlay {
    position: fixed;
    top: 90px; left: 20px;
    z-index: 260;
    min-width: 180px; max-width: 230px; max-height: 55vh;
    overflow-y: auto;
    background: #0d0d0f;
    border: 1px solid rgba(255,255,255,.1);
    border-radius: 10px;
    padding: 11px 12px;
    color: #fff;
    font-family: 'DM Sans', -apple-system, sans-serif;
    display: none;
    pointer-events: none;
}
#spectatoroverlay.show { display: block; }
#spectatoroverlay::-webkit-scrollbar { width: 3px; }
#spectatoroverlay::-webkit-scrollbar-thumb { background: rgba(255,255,255,.2); border-radius: 2px; }
#spectatoroverlay .warn { color: #ffb020; }
#spectatoroverlay .spec-head {
    font-size: 9.5px; font-weight: 700; letter-spacing: 1.6px;
    text-transform: uppercase; color: rgba(255,255,255,.5);
    margin-bottom: 8px; padding-bottom: 7px;
    border-bottom: 1px solid rgba(255,255,255,.08);
    display: flex; align-items: center; gap: 7px;
}
#spectatoroverlay .spec-head .dot { width: 6px; height: 6px; border-radius: 50%; background: #fff; }
#spectatoroverlay .spec-head .cnt {
    margin-left: auto; font-family: 'JetBrains Mono', monospace;
    font-size: 10px; font-weight: 700; color: #000;
    background: #fff; border-radius: 999px; padding: 1px 7px;
}
#spectatoroverlay .spec-row {
    display: flex; align-items: center; gap: 8px;
    font-size: 12px; font-weight: 600; padding: 4px 3px; color: rgba(255,255,255,.9);
}
#spectatoroverlay .spec-row + .spec-row { margin-top: 1px; }
#spectatoroverlay .spec-row .sav {
    width: 20px; height: 20px; min-width: 20px; border-radius: 50%;
    background: rgba(255,255,255,.1); color: #fff;
    display: flex; align-items: center; justify-content: center;
    font-size: 9px; font-weight: 800;
}
#spectatoroverlay .spec-row .sid {
    margin-left: auto; font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px; color: rgba(255,255,255,.4);
}
#freecam-hud { position: fixed; inset: 0; z-index: 240; pointer-events: none; display: none; color: #fff; font-family: 'DM Sans', sans-serif; }
#freecam-hud.show { display: block; }
.fc-status { position: absolute; top: 24px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 10px;
    background: rgba(8,8,8,.8); border: 1px solid rgba(255,255,255,.14); border-radius: 999px; padding: 7px 15px 7px 11px; backdrop-filter: blur(8px); white-space: nowrap; }
.fc-dot { width: 7px; height: 7px; border-radius: 50%; background: #fff; box-shadow: 0 0 10px rgba(255,255,255,.7); animation: fcPulse 1.4s infinite; }
.fc-lbl { font-size: 11px; font-weight: 800; letter-spacing: 2.5px; }
.fc-sub { font-size: 10px; font-weight: 600; letter-spacing: 1px; color: rgba(255,255,255,.5); padding-left: 8px; border-left: 1px solid rgba(255,255,255,.15); text-transform: uppercase; }
@keyframes fcPulse { 0%,100% { opacity: 1; transform: scale(1); } 50% { opacity: .4; transform: scale(.75); } }
.fc-prompt { position: absolute; bottom: 12%; left: 50%; transform: translateX(-50%); text-align: center; width: 560px; max-width: 92%; }
.fc-opt-prev, .fc-opt-next { display: block; font-size: 15px; font-weight: 600; color: rgba(255,255,255,.22); padding: 5px 0; min-height: 22px; }
.fc-opt-cur { display: flex; align-items: center; justify-content: center; gap: 16px; font-size: 23px; font-weight: 700; color: #fff; padding: 7px 0; text-shadow: 0 2px 16px rgba(0,0,0,.9); }
.fc-bar { color: rgba(255,255,255,.4); font-weight: 400; letter-spacing: 2px; font-size: 16px; }
.fc-hint { margin-top: 18px; font-size: 11px; font-weight: 600; letter-spacing: 1px; color: rgba(255,255,255,.4); background: rgba(8,8,8,.7); border: 1px solid rgba(255,255,255,.1); border-radius: 999px; padding: 7px 16px; display: inline-block; backdrop-filter: blur(6px); }
.fc-hint b { color: #fff; font-weight: 700; }
#hulk-hud { position: fixed; inset: 0; z-index: 240; pointer-events: none; display: none; color: #fff; font-family: 'DM Sans', sans-serif; }
#hulk-hud.show { display: block; }
.hk-prompt { position: absolute; bottom: 12%; left: 50%; transform: translateX(-50%);
    display: flex; align-items: center; gap: 12px; white-space: nowrap;
    text-shadow: 0 2px 10px rgba(0,0,0,.95), 0 0 3px rgba(0,0,0,.8);
    animation: hkPromptIn .35s cubic-bezier(.2,.9,.3,1) both; }
.hk-p-icon { font-size: 20px; line-height: 1; filter: grayscale(1) brightness(2.2); }
.hk-p-key { font-family: 'JetBrains Mono', monospace; font-weight: 800; font-size: 14px; background: #fff; color: #000;
    padding: 3px 10px; border-radius: 6px; min-width: 24px; text-align: center; }
.hk-p-action { font-size: 17px; font-weight: 800; letter-spacing: .3px; color: #fff; }
.hk-p-target { font-size: 17px; font-weight: 600; color: rgba(255,255,255,.7); }
@keyframes hkPromptIn { from { opacity: 0; transform: translateX(-50%) translateY(10px); } to { opacity: 1; transform: translateX(-50%) translateY(0); } }
#killfeed {
    position: fixed;
    top: 44px;
    right: 14px;
    display: flex;
    flex-direction: column;
    gap: 5px;
    z-index: 260;
    pointer-events: none;
    max-width: 260px;
    align-items: flex-end;
}
.kf-chip {
    display: flex; align-items: center; gap: 8px;
    background: rgba(0, 0, 0, .78);
    border: 1px solid rgba(255,255,255,.14);
    border-radius: 6px;
    padding: 6px 10px 6px 8px;
    color: var(--txt-on-ink);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: .3px;
    box-shadow: 0 6px 16px rgba(0,0,0,.55);
    animation: kfIn .22s cubic-bezier(.16,1,.3,1);
    max-width: 260px;
}
.kf-chip.out { animation: kfOut .32s ease forwards; }
.kf-icon {
    width: 16px; height: 16px;
    background: var(--txt-on-ink);
    color: var(--ink);
    border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    font-size: 9px; font-weight: 900;
    flex-shrink: 0;
}
.kf-body { min-width: 0; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kf-sub {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px;
    color: var(--txt-on-ink-mute);
    margin-left: 6px;
    text-transform: uppercase;
    letter-spacing: .5px;
}
@keyframes kfIn  { from { opacity: 0; transform: translateX(24px); } to { opacity: 1; transform: translateX(0); } }
@keyframes kfOut { from { opacity: 1; } to { opacity: 0; transform: translateX(24px); } }
#eventlogoverlay, #wpoverlay, #cwoverlay {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,.62);
    backdrop-filter: blur(6px);
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 41;
}
#eventlogoverlay.show, #wpoverlay.show, #cwoverlay.show { display: flex; }
.wp-row {
    display: flex; gap: 8px; align-items: center;
    padding: 6px 10px;
    background: var(--wash-ink-004);
    border-radius: 5px;
    border: 1px solid transparent;
    transition: background .12s ease;
}
.wp-row:hover { background: var(--wash-ink-010); }
.wp-name-inp {
    background: transparent;
    border: 1px solid var(--stroke-ink-soft);
    color: var(--txt-on-ink);
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    padding: 3px 6px;
    border-radius: 4px;
    flex: 1;
    min-width: 0;
    outline: none;
}
.wp-name-inp:focus { border-color: var(--stroke-ink-hard); }
.wp-coords {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px;
    color: var(--txt-on-ink-mute);
    letter-spacing: .3px;
}
.wp-actions { display: flex; gap: 4px; }
.wp-btn {
    background: transparent;
    color: var(--txt-on-ink-dim);
    border: 1px solid var(--stroke-ink-soft);
    padding: 3px 8px;
    border-radius: 4px;
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: .8px;
    cursor: pointer;
}
.wp-btn:hover { background: var(--txt-on-ink); color: var(--ink); border-color: var(--txt-on-ink); }
.wp-btn.tp:hover { background: var(--txt-on-ink); color: var(--ink); }
.wp-btn.del:hover { background: var(--paper); color: var(--ink); }
#eventlogbox {
    width: 620px;
    max-height: 78%;
    background: var(--ink-2);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 12px;
    box-shadow: 0 24px 56px rgba(0,0,0,.7);
    display: flex;
    flex-direction: column;
    animation: profilePop .22s cubic-bezier(.16,1,.3,1);
}
.el-head {
    display: flex; align-items: center; gap: 12px;
    padding: 16px 18px;
    border-bottom: 1px solid var(--stroke-ink-soft);
}
.el-title {
    font-size: 15px; font-weight: 800;
    color: var(--txt-on-ink);
    letter-spacing: -.2px;
}
.el-sub {
    font-size: 10px;
    color: var(--txt-on-ink-mute);
    letter-spacing: 1px;
    text-transform: uppercase;
    font-family: 'JetBrains Mono', monospace;
    flex: 1;
}
.el-list {
    overflow-y: auto;
    padding: 6px;
    display: flex;
    flex-direction: column;
    gap: 2px;
    max-height: 500px;
}
.el-list::-webkit-scrollbar { width: 4px; }
.el-list::-webkit-scrollbar-thumb { background: var(--wash-ink-015); border-radius: 4px; }
.el-row {
    display: flex; align-items: center; gap: 8px;
    padding: 6px 10px;
    background: var(--wash-ink-004);
    border: 1px solid transparent;
    border-radius: 5px;
    cursor: default;
    transition: background .12s ease;
}
.el-row:hover { background: var(--wash-ink-010); border-color: var(--stroke-ink-hair); }
.el-name {
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    color: var(--txt-on-ink);
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.el-src {
    font-size: 9px;
    color: var(--txt-on-ink-mute);
    text-transform: uppercase;
    letter-spacing: .8px;
    padding: 1.5px 5px;
    background: var(--wash-ink-006);
    border-radius: 3px;
}
.el-block {
    font-size: 9px;
    font-weight: 700;
    letter-spacing: .8px;
    padding: 3px 7px;
    border: 1px solid var(--stroke-ink-soft);
    background: transparent;
    color: var(--txt-on-ink-dim);
    border-radius: 4px;
    cursor: pointer;
    font-family: 'JetBrains Mono', monospace;
    text-transform: uppercase;
}
.el-block:hover { background: var(--txt-on-ink); color: var(--ink); border-color: var(--txt-on-ink); }
.el-block.on   { background: var(--txt-on-ink); color: var(--ink); border-color: var(--txt-on-ink); }
.el-empty {
    text-align: center;
    padding: 24px;
    color: var(--txt-on-ink-mute);
    font-size: 11px;
    letter-spacing: 1px;
    text-transform: uppercase;
}
.kb-row { display: flex; align-items: center; justify-content: space-between; padding: 8px 6px; }
.kb-lbl { font-size: 13px; font-weight: 600; color: #fff; }
.kb-box { background: var(--ink-3); border: 1px solid var(--stroke-ink-soft); border-radius: 7px;
    color: rgba(255,255,255,.85); font-size: 12px; font-weight: 600; font-family: 'JetBrains Mono', monospace;
    padding: 6px 14px; min-width: 90px; cursor: pointer; transition: all .18s; }
.kb-box:hover { border-color: rgba(255,255,255,.3); background: rgba(255,255,255,.06); }
.kb-box.listening { border-color: #fff; box-shadow: 0 0 10px rgba(255,255,255,.35); color: #fff; animation: kbPulse 1s infinite; }
@keyframes kbPulse { 0%,100%{opacity:1} 50%{opacity:.6} }
.bindlist { margin-top: 12px; background: var(--ink-3); border: 1px solid var(--stroke-ink-soft); border-radius: 9px; padding: 10px 12px; }
.bl-head { font-size: 9.5px; font-weight: 700; letter-spacing: 1.6px; text-transform: uppercase; color: rgba(255,255,255,.5);
    margin-bottom: 8px; padding-bottom: 7px; border-bottom: 1px solid var(--stroke-ink-soft); display: flex; align-items: center; }
.bl-cnt { margin-left: auto; font-family: 'JetBrains Mono', monospace; font-size: 10px; font-weight: 700; color: #000;
    background: #fff; border-radius: 999px; padding: 1px 7px; }
.bl-row { display: flex; align-items: center; justify-content: space-between; font-size: 12px; padding: 4px 2px; }
.bl-row + .bl-row { border-top: 1px solid rgba(255,255,255,.04); }
.bl-name { color: rgba(255,255,255,.85); font-weight: 600; }
.bl-key { font-family: 'JetBrains Mono', monospace; font-size: 11px; font-weight: 700; color: #000; background: #fff; border-radius: 5px; padding: 2px 9px; }
.bl-empty { font-size: 11px; color: rgba(255,255,255,.35); text-align: center; padding: 6px 0; }
#cursor {
    position: fixed;
    width: 14px; height: 14px;
    pointer-events: none !important;
    z-index: 9999999;
    left: 50%; top: 50%;
    margin-left: -7px; margin-top: -7px;
    will-change: transform;
}
#cursor-ring, #cursor-dot {
    position: absolute;
    top: 50%; left: 50%;
    pointer-events: none !important;
    transform: translate(-50%, -50%);
}
#cursor-ring {
    width: 16px; height: 16px;
    border: 2px solid rgba(168,85,247,1);
    border-radius: 50%;
    box-shadow: 0 0 0 1px rgba(0,0,0,.5), 0 0 8px rgba(168,85,247,.6);
}
#cursor-dot {
    width: 6px; height: 6px;
    background: #ffffff;
    border-radius: 50%;
    box-shadow: 0 0 0 1.5px rgba(0,0,0,.6), 0 0 6px rgba(168,85,247,0.9);
}
body.cursor-on-paper body.cursor-on-paper body.cursor-hover #cursor-dot { width: 3px; height: 3px; }
body.cursor-hover #cursor-ring { width: 22px; height: 22px; }
#bindoverlay {
    position: fixed;
    inset: 0;
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 400;
    backdrop-filter: blur(14px);
    background: rgba(0,0,0,.5);
    animation: fadeIn .18s ease;
}
#bindoverlay.on { display: flex; }
#bindbox {
    background: #0A0A0A;
    border: 1px solid rgba(255,255,255,.25);
    border-radius: 12px;
    padding: 28px 34px;
    min-width: 320px;
    box-shadow: 0 12px 44px rgba(0,0,0,.6), 0 0 30px rgba(255,255,255,.12);
    text-align: center;
    animation: modalPop .22s cubic-bezier(.34,1.4,.64,1);
}
@keyframes modalPop {
    from { transform: scale(.92); opacity: 0; }
    to   { transform: scale(1); opacity: 1; }
}
#bindbox .bt {
    font-size: 9px; font-weight: 700;
    letter-spacing: 2px;
    color: var(--txt-on-ink);
    text-transform: uppercase;
    margin-bottom: 10px;
}
#bindbox .bf {
    font-size: 16px; font-weight: 700;
    color: var(--txt-on-ink);
    margin-bottom: 10px;
}
#bindbox .bh {
    font-size: 11.5px;
    color: rgba(var(--text-rgb),.6);
    margin-bottom: 18px;
}
#bindbox .bk {
    display: inline-block;
    min-width: 72px;
    padding: 14px 24px;
    background: #7c5cff;
    border: 2px solid #a78bff;
    border-radius: 10px;
    font-family: 'JetBrains Mono', monospace;
    font-size: 26px;
    font-weight: 800;
    color: #ffffff;
    box-shadow: 0 0 24px rgba(124,92,255,.7), 0 4px 16px rgba(0,0,0,.5), inset 0 0 12px rgba(255,255,255,.15);
    letter-spacing: 2px;
    text-shadow: 0 0 8px rgba(255,255,255,.4);
}
#bindbox .bx {
    display: block;
    margin: 16px auto 0;
    font-size: 11px;
    font-weight: 500;
    color: rgba(var(--text-rgb),.5);
    background: transparent;
    border: 1px solid transparent;
    padding: 6px 14px;
    border-radius: 6px;
    cursor: pointer;
    transition: all .15s ease;
}
#bindbox .bx:hover {
    color: var(--ink);
    background: rgba(255,255,255,.9);
    border-color: rgba(var(--text-rgb),.9);
}
@keyframes fadeIn {
    from { opacity: 0; }
    to   { opacity: 1; }
}
#palette {
    position: fixed;
    inset: 0;
    display: none;
    align-items: flex-start;
    justify-content: center;
    padding-top: 12vh;
    z-index: 500;
    background: rgba(0,0,0,.55);
    backdrop-filter: blur(10px);
    animation: fadeIn .16s ease;
}
#palette.on { display: flex; }
#palbox {
    width: 520px;
    max-height: 65vh;
    background: #0A0A0A;
    border: 1px solid rgba(255,255,255,.24);
    border-radius: 12px;
    box-shadow: 0 20px 60px rgba(0,0,0,.7);
    display: flex; flex-direction: column;
    overflow: hidden;
    animation: modalPop .22s cubic-bezier(.34,1.4,.64,1);
}
#pal-input {
    padding: 16px 20px;
    background: transparent;
    border: 0;
    border-bottom: 1px solid var(--stroke-ink-soft);
    color: var(--txt-on-ink);
    font-family: inherit;
    font-size: 14px;
    font-weight: 500;
    outline: none;
}
#pal-input::placeholder { color: var(--txt-on-ink-mute); }
#pal-results {
    max-height: 45vh;
    overflow-y: auto;
    padding: 6px 0;
}
#pal-results::-webkit-scrollbar { width: 4px; }
#pal-results::-webkit-scrollbar-thumb { background: rgba(255,255,255,.15); }
.pal-item {
    padding: 10px 20px;
    display: flex; align-items: center; gap: 12px;
    cursor: pointer;
    transition: background .12s ease;
}
.pal-item:hover, .pal-item.act { background: var(--wash-ink-010); }
.pal-item .pal-ico {
    width: 24px; height: 24px;
    background: var(--ink-4);
    border-radius: 5px;
    display: flex; align-items: center; justify-content: center;
    color: var(--txt-on-ink-dim);
}
.pal-item .pal-ico svg {
    width: 12px; height: 12px;
    stroke: currentColor;
    stroke-width: 1.7;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
}
.pal-item .pal-body { flex: 1; }
.pal-item .pal-name {
    font-size: 12px;
    font-weight: 600;
    color: var(--txt-on-ink);
}
.pal-item .pal-path {
    font-size: 10px;
    color: var(--txt-on-ink-mute);
    margin-top: 1px;
}
.pal-item .pal-tag {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px;
    padding: 2px 6px;
    background: var(--wash-ink-006);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 4px;
    color: var(--txt-on-ink-mute);
}
#pal-foot {
    padding: 8px 20px;
    border-top: 1px solid var(--stroke-ink-soft);
    display: flex;
    align-items: center;
    gap: 14px;
    font-size: 10px;
    color: var(--txt-on-ink-mute);
}
#pal-foot .pal-kbd {
    display: inline-flex;
    align-items: center;
    gap: 4px;
}
#pal-foot .pal-kbd .k {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9.5px;
    padding: 1px 5px;
    background: var(--wash-ink-006);
    border: 1px solid var(--stroke-ink-soft);
    border-radius: 3px;
    color: var(--txt-on-ink);
}
    </style>
</head>
<body>
    <div id="menu">
        <div id="header">
            <div class="brand">
                <span class="wordmark">OMEN</span>
                <div class="ac-chip hidden" id="ac-chip">
                    <span class="ac-dot"></span>
                    <span class="ac-lbl">AC:</span>
                    <span class="ac-val" id="ac-name">None</span>
                </div>
            </div>
            <div class="hdr-search" onclick="openPalette()">
                <svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></svg>
                <span id="hdr-search-lbl">Search features...</span>
                <span class="kbd">CTRL K</span>
            </div>
            <div class="hdr-right">
                <img class="hdr-logo" src="logo.png" alt="Omen" onerror="this.style.display='none'">
                <button class="hdr-btn" title="Minimize" onclick="toast('info','Omen','Menu hidden - INSERT to bring back',1800)">
                    <svg viewBox="0 0 24 24"><path d="M5 12h14"/></svg>
                </button>
                <button class="hdr-btn" title="Panic uninject" onclick="toast('failure','Omen','Panic - feature disabled')">
                    <svg viewBox="0 0 24 24"><path d="M18 6L6 18M6 6l12 12"/></svg>
                </button>
            </div>
        </div>
        <aside id="sidebar">
            <div class="sb-head">Navigation</div>
            <nav id="nav"></nav>
            <div class="sb-foot">
                <div class="sb-card" id="profilecard" onclick="openProfile()">
                    <div class="sb-avatar" id="sb-avatar">
                        <span id="sb-avatar-fallback">O</span>
                        <div class="presence on" id="sb-avatar-presence"></div>
                    </div>
                    <div class="sb-body">
                        <div class="row1">
                            <span id="sb-user">Omen User</span>
                        </div>
                        <div class="row2">
                            <span id="sb-tier">OMEN</span>
                            <span class="dot"></span>
                            <span class="keytime" id="sb-keytime">-</span>
                        </div>
                    </div>
                </div>
            </div>
        </aside>
        <div id="profileoverlay" onclick="if(event.target.id==='profileoverlay') closeProfile()">
            <div id="profilebox">
                <div class="p-head">
                    <div class="p-avatar" id="p-avatar">
                        <span id="p-avatar-fallback">O</span>
                    </div>
                    <div class="p-head-body">
                        <div class="p-name">
                            <span id="p-name-txt">Omen User</span>
                            <span class="p-tag" id="p-tag">PRIVATE</span>
                        </div>
                        <div class="p-sub">
                            <span class="k" id="p-discord">Omen Menu</span>
                        </div>
                    </div>
                </div>
                <div class="p-grid">
                    <div class="p-cell wide">
                        <div class="k">Server</div>
                        <div class="v text" id="p-server">-</div>
                    </div>
                    <div class="p-cell">
                        <div class="k">Server ID</div>
                        <div class="v" id="p-server-code">-</div>
                    </div>
                    <div class="p-cell">
                        <div class="k">Players</div>
                        <div class="v" id="p-server-players">-</div>
                    </div>
                    <div class="p-cell">
                        <div class="k">Session Time</div>
                        <div class="v" id="p-session">-</div>
                    </div>
                    <div class="p-cell">
                        <div class="k">Menu Version</div>
                        <div class="v text" id="p-version">Omen v0.3.0</div>
                    </div>
                </div>
                <div class="p-actions">
                    <button class="p-btn ghost" onclick="copyServerIp()">Copy Server IP</button>
                    <button class="p-btn ghost" onclick="refreshProfile()">Refresh</button>
                    <button class="p-btn" onclick="closeProfile()">Close</button>
                </div>
            </div>
        </div>
        <main id="main">
            <div id="section-head">
                <div class="section-title"><span class="sq"></span><span id="sec-title">Self</span></div>
                <div class="breadcrumb"><span id="sec-crumb">Player Actions / <b>Self</b></span></div>
                <div class="section-tools">
                    <div class="section-pill">
                        <span class="n" id="sec-on-count">0</span>
                        <span>ACTIVE</span>
                    </div>
                </div>
            </div>
            <div id="panels"></div>
        </main>
    </div>
    <div id="toasts"></div>
    <div id="watermark">omen</div>
    <div id="spectatoroverlay"></div>
    <div id="bubbleseeroverlay"></div>
    <div id="killfeed"></div>
    <div id="admin-list">
