            <span class="fc-opt-prev" id="fc-prev"></span>
            <span class="fc-opt-cur"><span class="fc-bar">&mdash;</span><span id="fc-cur">Shoot Weapon</span><span class="fc-bar">&mdash;</span></span>
            <span class="fc-opt-next" id="fc-next"></span>
            <div class="fc-hint"><b>Scroll</b> cycle &middot; <b>LClick</b> use &middot; <b>WASD</b> fly &middot; <b>U</b> exit</div>
        </div>
    </div>
    <div id="hulk-hud">
        <div class="hk-prompt" id="hk-prompt">
            <span class="hk-p-icon" id="hk-p-icon">&#9995;</span>
            <span class="hk-p-key">Y</span>
            <span class="hk-p-action" id="hk-p-action">Grab</span>
            <span class="hk-p-target" id="hk-p-target">nothing in range</span>
        </div>
    </div>
    <div id="eventlogoverlay" onclick="if(event.target.id==='eventlogoverlay') closeEventLog()">
        <div id="eventlogbox">
            <div class="el-head">
                <div class="el-title">Event Log</div>
                <div class="el-sub" id="el-count">0 events</div>
