                <button class="p-btn" onclick="closeEventLog()">Close</button>
            </div>
            <div class="el-list" id="el-list"></div>
        </div>
    </div>
    <div id="wpoverlay" onclick="if(event.target.id==='wpoverlay') closeWaypoints()">
        <div id="wpbox">
            <div class="el-head">
                <div class="el-title">Saved Waypoints</div>
                <div class="el-sub" id="wp-count">0 saved</div>
                <button class="p-btn" onclick="closeWaypoints()">Close</button>
            </div>
            <div class="el-list" id="wp-list"></div>
            <div class="el-head" style="border-top:1px solid var(--stroke-ink-soft); border-bottom:none;">
                <div class="el-sub">also saved in configs</div>
            </div>
        </div>
    </div>
    <div id="cwoverlay" onclick="if(event.target.id==='cwoverlay') closeCustomWeapons()">
