    const State = {
        activeTabId: MenuConfig.tabs[0].id,
        toggles: Object.create(null),
        sliders: Object.create(null),
        inputs:  Object.create(null),
        dropdowns: Object.create(null),
        segs:    Object.create(null),
        binds:   Object.create(null),
        selectedPlayer: null,
    };
    State.toggles.darkmode = true;
    let bindingId = null;
    let Profile = {
        user: "", sub: "", subTier: "Lifetime", subDays: null,
        pcUser: "", lang: "",
        discord: { ok: false, username: "", id: "", avatarUrl: "" },
        server:  { name: "", icon: "", players: 0, maxPlayers: 0, endpoint: "" },
        ac: "None", version: "0.3.0", sessionStart: 0, sessionSecs: 0,
    };
    let PlayerList = [];
    const __chunkBuf = {};
    // Reassemble multi-chunk array messages from Lua (SendDuiMessage splits big
    // arrays like the player list). Returns the full array on the last chunk,
    // or null while still waiting for more.
    function accumChunk(key, msg, incomingArr) {
        const arr = Array.isArray(incomingArr) ? incomingArr : [];
        const chunks = msg.chunks || 1;
        const chunk  = msg.chunk  || 1;
        if (chunks <= 1) return arr;
        if (chunk === 1) __chunkBuf[key] = [];
        __chunkBuf[key] = (__chunkBuf[key] || []).concat(arr);
        if (chunk < chunks) return null;
        const full = __chunkBuf[key];
        __chunkBuf[key] = [];
        return full;
    }
    let CfgList    = [];
    const OMEN_SID = Math.random().toString(36).slice(2, 10);
    let omenSeq = 0;
    let __omenQ = [];
    var __clipTimer = null;
    function __flushClipboard() {
        __clipTimer = null;
        // one clipboard write for all queued actions since last flush. execCommand("copy")
        // is heavy + synchronous; calling it on every click (rapid) crashes CEF. Debounced.
        try {
            const json = JSON.stringify({ q: __omenQ });
            const ta = document.createElement("textarea");
            ta.value = "OMEN:" + json;
            ta.style.cssText = "position:fixed;top:-9999px;left:-9999px;opacity:0;";
            document.body.appendChild(ta);
            ta.select();
            document.execCommand("copy");
            document.body.removeChild(ta);
        } catch (e) {}
    }
    function sendAction(payload) {
        payload._t = Date.now();
        payload._id = (++omenSeq);
        // Queue the action instantly (cheap). Lua dedupes by _id.
        __omenQ.push(payload);
        if (__omenQ.length > 30) __omenQ = __omenQ.slice(-30);
        // Debounce the actual clipboard write: coalesce rapid clicks into ONE copy op
        // ~30ms later. Prevents the execCommand flood that crashes the game on fast clicks.
        if (!__clipTimer) __clipTimer = setTimeout(__flushClipboard, 30);
        // NUI fetch as an instant bonus path (single action; Lua dedupes by _id)
        const _res = window.__omenRes || window.__omenBridgeRes;
        if (_res) {
            try {
                fetch("https://" + _res + "/omen_recv", {
                    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload)
                }).catch(function () {});
            } catch (e) {}
        }
    }
    function applyProfile(p) {
        if (!p || typeof p !== "object") return;
        Object.assign(Profile, {
            user:         p.user    || "",
            sub:          p.sub     || "",
            subTier:      p.subTier || "Lifetime",
            subDays:      (typeof p.subDays === "number") ? p.subDays : null,
            pcUser:       p.pcUser  || "",
            lang:         p.lang    || "",
            discord:      p.discord || Profile.discord,
            server:       p.server  || Profile.server,
            ac:           p.ac      || Profile.ac || "None",
            version:      p.version || Profile.version,
            sessionStart: (typeof p.sessionStart === "number") ? p.sessionStart : Profile.sessionStart,
            sessionSecs:  (typeof p.sessionSecs === "number") ? p.sessionSecs : Profile.sessionSecs,
        });
        // Only re-render when a displayed field actually changed. The 30s refresh was
        // calling this every time and rebuilding the card = visible twitch. Session time
        // updates live via its own counter, so it's excluded from the change check.
        const sig = [Profile.user, Profile.sub, Profile.subTier, Profile.pcUser, Profile.lang, Profile.discord, Profile.server, Profile.ac, Profile.version].join("|");
        if (window.__profileSig !== sig) {
            window.__profileSig = sig;
            renderProfileCard();
            renderProfileModal();
        }
    }
    function fmtSession(secs) {
        if (typeof secs !== "number" || secs < 0) return "-";
        if (secs < 60)   return secs + "s";
        if (secs < 3600) return Math.floor(secs / 60) + "m " + (secs % 60) + "s";
        return Math.floor(secs / 3600) + "h " + Math.floor((secs % 3600) / 60) + "m";
    }
    setInterval(() => {
        if (typeof Profile.sessionSecs === "number") {
            Profile.sessionSecs++;
            const el = document.getElementById("p-session");
            if (el) el.textContent = fmtSession(Profile.sessionSecs);
        }
    }, 1000);
    function renderProfileCard() {
        const av    = document.getElementById("sb-avatar");
        const avImg = av.querySelector("img");
        const avTxt = document.getElementById("sb-avatar-fallback");
        const name  = document.getElementById("sb-user");
        const tier  = document.getElementById("sb-tier");
        const kt    = document.getElementById("sb-keytime");
        const displayName = Profile.user || "Omen User";
        name.textContent = displayName;
        const acChip = document.getElementById("ac-chip");
        const acName = document.getElementById("ac-name");
        if (acChip && acName) {
            const ac = Profile.ac;
            if (ac && typeof ac === "string" && ac !== "None" && ac !== "") {
                acChip.classList.remove("hidden");
                acName.textContent = ac;
            } else {
                acChip.classList.add("hidden");
            }
        }
        if (Profile.discord && Profile.discord.avatarUrl) {
            if (avImg) {
                avImg.src = Profile.discord.avatarUrl;
            } else {
                const img = document.createElement("img");
                img.src = Profile.discord.avatarUrl;
                img.alt = "";
                img.onerror = () => { img.remove(); avTxt.style.display = ""; };
                avTxt.style.display = "none";
                av.insertBefore(img, avTxt);
            }
        } else {
            if (avImg) avImg.remove();
            avTxt.style.display = "";
            const letter = (displayName[0] || "O").toUpperCase();
            avTxt.textContent = letter;
        }
        tier.textContent = "OMEN";
        kt.classList.remove("warn", "expired");
        var _days = Profile.subDays;
        var _tier = (Profile.subTier || "").toLowerCase();
        if (_days === null || _days === undefined || _tier === "lifetime") {
            kt.textContent = "Lifetime - 9999 days";
        } else if (_days < 0) {
            kt.textContent = "Expired";
            kt.classList.add("expired");
        } else if (_days === 0) {
            kt.textContent = "Last day";
            kt.classList.add("warn");
        } else if (_days === 1) {
            kt.textContent = "1 day left";
            kt.classList.add("warn");
        } else {
            kt.textContent = _days + " days left";
            if (_days <= 7) kt.classList.add("warn");
        }
    }
    function renderProfileModal() {
        const pAv    = document.getElementById("p-avatar");
        const pAvTxt = document.getElementById("p-avatar-fallback");
        const oldImg = pAv.querySelector("img");
        if (oldImg) oldImg.remove();
        if (Profile.discord && Profile.discord.avatarUrl) {
            const img = document.createElement("img");
            img.src = Profile.discord.avatarUrl;
            img.alt = "";
            img.onerror = () => { img.remove(); pAvTxt.style.display = ""; };
            pAvTxt.style.display = "none";
            pAv.insertBefore(img, pAvTxt);
        } else {
            pAvTxt.style.display = "";
            pAvTxt.textContent = ((Profile.user || "O")[0] || "O").toUpperCase();
        }
        document.getElementById("p-name-txt").textContent = Profile.user || "Omen User";
        document.getElementById("p-tag").textContent =
            Profile.subDays === null || Profile.subDays === undefined
                ? (Profile.subTier || "LIFETIME").toString().toUpperCase()
                : (Profile.subDays < 0 ? "EXPIRED" : "ACTIVE");
        document.getElementById("p-discord").textContent =
            Profile.discord && Profile.discord.ok
                ? Profile.discord.username
                : "not connected";
        var _pset = function(id, val) { var e = document.getElementById(id); if (e) e.textContent = val; };
        _pset("p-server",         (Profile.server && Profile.server.name) || "-");
        _pset("p-server-code",    (Profile.server && Profile.server.code) || "-");
        _pset("p-server-players", (Profile.server && Profile.server.players) || "-");
        _pset("p-session",        fmtSession(Profile.sessionSecs));
        document.getElementById("p-version").textContent       = "Omen v" + (Profile.version || "0.3.0");
    }
    function openProfile() {
        sendAction({ action: "requestServer" });
        renderProfileModal();
        document.getElementById("profileoverlay").classList.add("show");
    }
    function closeProfile() {
        document.getElementById("profileoverlay").classList.remove("show");
    }
    function refreshProfile() {
        sendAction({ action: "requestProfile" });
        toast("info", "Profile", "Refreshing...");
    }
    function copyDiscordId() {
        if (!Profile.discord || !Profile.discord.id) {
            toast("info", "Discord", "Not connected");
            return;
        }
        sendAction({ action: "copyDiscord" });
    }
    window.openProfile    = openProfile;
    window.closeProfile   = closeProfile;
    window.refreshProfile = refreshProfile;
    window.copyDiscordId  = copyDiscordId;
    function copyToOS(text) {
        try {
            const ta = document.createElement("textarea");
            ta.value = text;
            ta.style.cssText = "position:fixed;top:-9999px;left:-9999px;opacity:0;";
            document.body.appendChild(ta);
            ta.select();
            document.execCommand("copy");
            document.body.removeChild(ta);
            return true;
        } catch (e) { return false; }
    }
    function copyServerIp() {
        const sv = Profile.server || {};
        const ip = sv.endpoint || (sv.code ? String(sv.code).replace(/^connect\s+/, "") : "");
        if (!ip) { toast("info", "Server", "IP not available"); return; }
        copyToOS(ip);
        toast("success", "Server", "Server IP copied");
    }
    window.copyServerIp   = copyServerIp;
    // Position the menu by its top-left corner using only transform (keeps the UI scale).
    window.__omMenuXY = null;
    window.__omPlaceMenu = function(m, x, y) {
        const sc = (State.sliders && State.sliders.menu_scale ? State.sliders.menu_scale : 100) / 100;
        window.__omMenuXY = { x: x, y: y };
        m.style.left = "0px"; m.style.top = "0px";
        m.style.transformOrigin = "0 0";
        m.style.transform = "translate3d(" + x + "px," + y + "px,0) scale(" + sc + ")";
    };
    window.handleFromLua = function(msg) {
        if (!msg || typeof msg !== "object") return;
        const a = msg.action;
        // Menu visibility toggle from Lua CapsLock
        if (a === "setVisible") {
            const menu = document.getElementById("menu");
            if (menu) {
                if (msg.v) {
                    const scale = (State.sliders && State.sliders.menu_scale ? State.sliders.menu_scale : 100) / 100;
                    menu.style.display = "grid";
                    menu.style.visibility = "visible";
                    menu.style.pointerEvents = "all";
                    menu.style.left = "50%";
                    menu.style.top = "50%";
                    menu.style.transformOrigin = "";
                    window.__omMenuXY = null;
                    // start slightly small + transparent, then animate in
                    menu.style.transition = "none";
                    menu.style.opacity = "0";
                    menu.style.transform = "translate(-50%, -50%) scale(" + (scale * 0.96) + ")";
                    requestAnimationFrame(function(){
                        menu.style.transition = "opacity .16s ease, transform .18s cubic-bezier(.34,1.3,.5,1)";
                        menu.style.opacity = "1";
                        menu.style.transform = "translate(-50%, -50%) scale(" + scale + ")";
                    });
                } else {
                    const scale = (State.sliders && State.sliders.menu_scale ? State.sliders.menu_scale : 100) / 100;
                    menu.style.transition = "opacity .14s ease, transform .14s ease";
                    menu.style.opacity = "0";
                    menu.style.transform = "translate(-50%, -50%) scale(" + (scale * 0.96) + ")";
                    setTimeout(function(){ menu.style.display = "none"; }, 150);
                }
            }
            document.body.classList.toggle("omen-hidden", !msg.v);
            return;
        }
        // Cursor + click from Lua (absolute 0..1 position). Synthesizes real DOM
        // mouse events so the existing dot/ring/hover/drag/click code all works.
        if (a === "mouse") {
            // Shadow 1:1: px/py are raw screen pixels in (sw,sh) space. Map to THIS
            // DUI's viewport so the cursor spans the full menu, edge to edge.
            const _sw = (msg.sw && msg.sw > 0) ? msg.sw : window.innerWidth;
            const _sh = (msg.sh && msg.sh > 0) ? msg.sh : window.innerHeight;
            const _nx = (msg.px != null) ? (msg.px / _sw) : (msg.x || 0);
            const _ny = (msg.py != null) ? (msg.py / _sh) : (msg.y || 0);
            const x = Math.max(0, Math.min(window.innerWidth,  _nx * window.innerWidth));
            const y = Math.max(0, Math.min(window.innerHeight, _ny * window.innerHeight));
            const el = document.elementFromPoint(x, y) || document.body;
            const opts = () => ({ bubbles: true, cancelable: true, view: window, clientX: x, clientY: y });

            // always move - drives the ring/dot, hover, and drag listeners
            el.dispatchEvent(new MouseEvent("mousemove", opts()));

            const down = msg.b === 1;
            if (down && !window.__omDown) {
                window.__omDown = true;
                window.__omDownEl = el;                 // remember what was pressed
                el.dispatchEvent(new MouseEvent("mousedown", opts()));
                const inp = el.closest("input, textarea") || (el.querySelector && el.querySelector("input, textarea"));
                if (inp) inp.focus(); else if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
            } else if (!down && window.__omDown) {
                window.__omDown = false;
                el.dispatchEvent(new MouseEvent("mouseup", opts()));
                // fire click on the element that was PRESSED (bubbles to its handler),
                // so a small cursor drift between press and release can't drop it
                const target = window.__omDownEl || el;
                target.dispatchEvent(new MouseEvent("click", opts()));
                window.__omDownEl = null;
            }

            if (msg.w) {
                // Scroll the nearest scrollable ancestor under the LIVE cursor.
                let s = document.elementFromPoint(mouseX, mouseY) || el;
                while (s && s !== document.body && s !== document.documentElement) {
                    const oy = getComputedStyle(s).overflowY;
                    if ((oy === "auto" || oy === "scroll") && s.scrollHeight > s.clientHeight + 2) break;
                    s = s.parentElement;
                }
                if (s && s.scrollHeight > s.clientHeight + 2) {
                    s.scrollTop += msg.w * 120;
                }
            }
            return;
        }
        // Open overlays requested by Lua
        if (a === "openCustomWeapons") { window.openCustomWeapons && window.openCustomWeapons(); return; }
        if (a === "openEventLog")      { window.openEventLog && window.openEventLog();       return; }
        if (a === "setDarkMode")       { document.body.classList.toggle("omen-light", msg.v === false); return; }
        if (a === "spectatorList") {
            const el = document.getElementById("spectatoroverlay");
            if (!el) return;
            const players = Array.isArray(msg.players) ? msg.players : [];
            if (msg.show) {
                // Toggle is ON -> always show the overlay (with spectators, or "clear").
                let body;
                if (players.length) {
                    body = '<div class="spec-head"><span class="dot"></span>Spectating You<span class="cnt">' + players.length + '</span></div>';
                    body += players.map(function(p){
                        const nm = p.name || "Unknown";
                        const init = nm.charAt(0).toUpperCase();
                        const id = p.sid != null ? ('#' + p.sid) : '';
                        return '<div class="spec-row"><span class="sav">' + init + '</span>' +
                               '<span class="snm">' + nm + ' <span class="warn">&#9888;</span></span>' +
                               (id ? '<span class="sid">' + id + '</span>' : '') + '</div>';
                    }).join("");
                } else {
                    body = '<div class="spec-head"><span class="dot" style="background:#4ade80"></span>Spectators</div>' +
                           '<div class="spec-empty">No one spectating</div>';
                }
                el.innerHTML = body;
                el.classList.add("show");
            } else {
                el.classList.remove("show");
            }
            return;
        }
        if (a === "bubbleSeerList") {
            const el = document.getElementById("bubbleseeroverlay");
            if (!el) return;
            const players = Array.isArray(msg.players) ? msg.players : [];
            if (msg.show) {
                let rows;
                if (players.length === 0) {
                    rows = '<div class="spec-empty">No one in bubble</div>';
                } else {
                    rows = players.map(function(p){
                        const nm = p.name || "Unknown";
                        const init = nm.charAt(0).toUpperCase();
                        const id = p.id != null ? ('#' + p.id) : '';
                        return '<div class="spec-row"><span class="sav">' + init + '</span>' +
                               '<span class="snm">' + nm + '</span>' +
                               (id ? '<span class="sid">' + id + '</span>' : '') + '</div>';
                    }).join("");
                }
                const nextHtml = '<div class="spec-head"><span class="dot"></span>Bubble Seer<span class="cnt">' + players.length + '</span></div>' + rows;
                // only touch the DOM if content changed (prevents twitch/re-render)
                if (el.__lastHtml !== nextHtml) { el.innerHTML = nextHtml; el.__lastHtml = nextHtml; }
                el.classList.add("show");
            } else {
                el.classList.remove("show"); el.__lastHtml = null;
            }
            return;
        }
        // Keyboard forwarded from Lua (typing into the focused input)
        if (a === "cur")   { window.setCursor(msg.x, msg.y); return; }
        if (a === "curDown")   { if (window.doMouseDown) window.doMouseDown(); return; }
        if (a === "curUp")     { if (window.doMouseUp) window.doMouseUp(); return; }
        if (a === "curScroll") { if (window.doScroll) window.doScroll(msg.d || 0); return; }
        if (a === "curShow")   {
            var c = document.getElementById("cursor");
            if (c) c.style.display = msg.v ? "block" : "none";
            if (msg.v && window.setCursor) window.setCursor(msg.x || window.innerWidth/2, msg.y || window.innerHeight/2);
            return;
        }
        if (a === "duiMode")   { window._duiMode = (msg.v === true); return; }
        if (a === "restoreBinds") {
            if (msg.binds && typeof msg.binds === "object") {
                State.binds = State.binds || {};
                for (const k in msg.binds) State.binds[k] = msg.binds[k];
                document.querySelectorAll(".kb-box[data-bind]").forEach(function(b){
                    const id = b.getAttribute("data-bind");
                    if (State.binds[id]) b.querySelector("span").textContent = State.binds[id];
                });
                if (typeof renderBindList === "function") renderBindList();
                // CRITICAL: tell Lua about the bind (the old DOM keydown listener never
                // fires in CEF, so this is the only path that reaches Lua).
                sendAction({ action: "bind", id: bindingId, v: bkey });
                if (typeof closeBind === "function") closeBind();
            }
            return;
        }
        if (a === "key")   { window.__omKey(msg.vk, msg.s, msg.c);  return; }
        if (a === "paste") { window.__omInsert(msg.text || "");      return; }
        // VK bridge handshake
        if (a === "pong") {
            window.__omenLinked = true;
            return;
        }
        if (a === "bridgeInfo") {
            if (msg.res)    window.__omenRes       = msg.res;
            if (msg.bridge) window.__omenBridgeRes = msg.bridge;
            sendAction({ action: "duiDims", w: window.innerWidth, h: window.innerHeight });
            return;
        }
                if (a === "pong") {
            window.__omenLinked = true;
            if (msg.via && !window.__omenVia) window.__omenVia = msg.via;
            return;
        }
        if (a === "setDropdownOptions" && msg.id) {
            State.__ddOptions = State.__ddOptions || {};
            State.__ddOptions[msg.id] = msg.options || [];
            State.dropdowns[msg.id] = (msg.options && msg.options[0]) || "";
            // Update ONLY the affected dropdown (no full renderPanel = no lag, no cursor
            // loss from rebuilding the whole panel). Refresh its button label; the option
            // list rebuilds lazily when the dropdown is next opened (buildOpts reads __ddOptions).
            try {
                document.querySelectorAll('.dd').forEach(function(dd){
                    if (dd.__ddId === msg.id) {
                        var sp = dd.querySelector('.dd-btn span');
                        if (sp) sp.textContent = State.dropdowns[msg.id] || "";
                        if (dd.__ddClose) dd.__ddClose();  // close if open so it rebuilds fresh next open
                    }
                });
            } catch (e) {}
            return;
        }
        else if (a === "syncState" && msg.states) {
            for (const [id, v] of Object.entries(msg.states)) {
                if (typeof v === "boolean") State.toggles[id] = v;
                if (id === "darkmode") document.body.classList.toggle("light-mode", v === false);
                else if (typeof v === "number") State.sliders[id] = v;
                else if (itemType(id) === "seg") State.segs[id] = v;
                else State.dropdowns[id] = v;
                if (id === "menu_scale" && typeof v === "number") {
                    const _m = document.getElementById("menu");
                    if (_m && window.__omMenuXY) window.__omPlaceMenu(_m, window.__omMenuXY.x, window.__omMenuXY.y);
                    else if (_m) _m.style.transform = "translate(-50%, -50%) scale(" + (v/100) + ")";
                }
            }
            renderPanel(State.activeTabId);
            renderSidebar(); renderHead();
        }
        else if (a === "applyProfile") applyProfile(msg.profile);
        else if (a === "applyPlayers") {
            const full = accumChunk("players", msg, msg.players);
            if (full === null) return;   // waiting for more chunks
            PlayerList = full;
            if (State.activeTabId === "players") {
                updatePlayerListInPlace();
            }
        }
        else if (a === "applyCfgList") {
            const _c = accumChunk("configs", msg, msg.configs); if (_c === null) return; CfgList = _c;
            if (State.activeTabId === "configs") renderPanelDebounced(State.activeTabId);
        }
        else if (a === "killfeed") {
            pushKillFeed(msg.line || "hit", msg.sub || "", msg.hold);
        }
        else if (a === "applyEventLog") {
            const _e = accumChunk("events", msg, msg.events); if (_e === null) return; EventLog = _e;
            if (Blocked !== null && Array.isArray(msg.blocked)) Blocked = new Set(msg.blocked);
            renderEventLog();
        }
        else if (a === "applyWaypoints") {
            const _w = accumChunk("waypoints", msg, msg.waypoints); if (_w === null) return; Waypoints = _w;
            renderWaypoints();
        }
        else if (a === "openWaypoints") {
            renderWaypoints();
            document.getElementById("wpoverlay").classList.add("show");
        }
        else if (a === "applyAdmins") {
            const _a = accumChunk("admins", msg, msg.admins); if (_a === null) return; AdminList = _a;
            renderAdminList();
        }
        else if (a === "applyCustomWeapons") {
            const _cw = accumChunk("weapons", msg, msg.weapons); if (_cw === null) return; CustomWeapons = _cw;
            renderCustomWeapons();
        }
        else if (a === "applyFreecamHud") applyFreecamHud(msg);
        else if (a === "applyHulkHud")    applyHulkHud(msg);
        else if (a === "hulkPulse")       flashHulkPulse();
        else if (a === "toast") toast(msg.severity || "success", msg.title || "Omen", msg.message || "");
    };
    function applyFreecamHud(m) {
        const el = document.getElementById("freecam-hud");
        if (!el) return;
        if (m.on === false) { el.classList.remove("show"); return; }
        el.classList.add("show");
        // scroll menu: prev / current / next option
        if (m.opts && typeof m.opt === "number") {
            var n = m.opts.length;
            var cur = ((m.opt % n) + n) % n;
            var prev = ((cur - 1) % n + n) % n;
            var next = (cur + 1) % n;
            var pe = document.getElementById("fc-prev"); if (pe) pe.textContent = m.opts[prev] || "";
            var ce = document.getElementById("fc-cur"); if (ce) ce.textContent = m.opts[cur] || "";
            var ne = document.getElementById("fc-next"); if (ne) ne.textContent = m.opts[next] || "";
        }
    }
    function applyHulkHud(m) {
        const el = document.getElementById("hulk-hud");
        const prompt = document.getElementById("hk-prompt");
        if (!el || !prompt) return;
        if (m.on === false) { el.classList.remove("show"); return; }
        el.classList.add("show");
        const carrying = m.carrying === true;
        const inRange = carrying || !!(m.targetName && m.targetName !== "nothing in range") || !!m.targetType;
        const iconEl = document.getElementById("hk-p-icon");
        const actEl  = document.getElementById("hk-p-action");
        const tgtEl  = document.getElementById("hk-p-target");
        if (carrying) {
            if (actEl) actEl.textContent = "Throw";
            if (tgtEl) tgtEl.textContent = m.targetName || m.targetType || "target";
            if (iconEl) iconEl.innerHTML = "&#9992;";   // plane/throw
        } else if (inRange) {
            if (actEl) actEl.textContent = "Grab";
            // dynamic: shows "Player Jack", "Vehicle Adder", "Prop" etc.
            var label = m.targetName || "";
            if (m.targetType && m.targetType !== "Player" && !label) label = m.targetType;
            if (tgtEl) tgtEl.textContent = label || m.targetType || "target";
            if (iconEl) iconEl.innerHTML = "&#9995;";   // hand
        } else {
            if (actEl) actEl.textContent = "Grab";
            if (tgtEl) tgtEl.textContent = "nothing in range";
            if (iconEl) iconEl.innerHTML = "&#9995;";
        }
    }
    function flashHulkPulse() {
        const p = document.getElementById("hk-prompt");
        if (!p) return;
        p.classList.remove("throw-flash"); void p.offsetWidth; p.classList.add("throw-flash");
        setTimeout(function(){ p.classList.remove("throw-flash"); }, 400);
    }
    function renderCustomWeapons() {
        const box = document.getElementById("cw-list");
        const cnt = document.getElementById("cw-count");
        if (!box || !cnt) return;
        cnt.textContent = CustomWeapons.length + " saved";
        box.innerHTML = "";
        if (!CustomWeapons.length) { box.innerHTML = `<div class="el-empty">no custom weapons</div>`; return; }
        CustomWeapons.forEach((w, i) => {
            const idx = i + 1;
            const row = document.createElement("div");
            row.className = "cfg-item";
            row.innerHTML =
                `<div class="prail"></div>` +
                `<div class="cfg-body">` +
                    `<div class="cfg-name">${escapeHtml(w.name || w.hash)}</div>` +
                    `<div class="cfg-meta">${escapeHtml(w.hash)}</div>` +
                `</div>` +
                `<div class="cfg-actions">` +
                    `<button class="cfg-btn">GIVE</button>` +
                    `<button class="cfg-btn del">DEL</button>` +
                `</div>`;
            const [giveBtn, delBtn] = row.querySelectorAll(".cfg-btn");
            giveBtn.addEventListener("click", (e) => {
                e.stopPropagation();
                sendAction({ action: "cw_give", idx: idx });
                toast("success", "Omen", "Given: " + (w.name || w.hash), 1400);
            });
            delBtn.addEventListener("click", (e) => {
                e.stopPropagation();
                sendAction({ action: "cw_delete", idx: idx });
                CustomWeapons.splice(i, 1); renderCustomWeapons();
            });
            box.appendChild(row);
        });
    }
    function openCustomWeapons() {
        sendAction({ action: "requestCustomWeapons" });
        renderCustomWeapons();
        document.getElementById("cwoverlay").classList.add("show");
    }
    function closeCustomWeapons() { document.getElementById("cwoverlay").classList.remove("show"); }
    window.openCustomWeapons  = openCustomWeapons;
    window.closeCustomWeapons = closeCustomWeapons;
    let AdminList = [];
    function renderAdminList() {
        const wrap = document.getElementById("admin-list");
        const rows = document.getElementById("al-rows");
        const cnt  = document.getElementById("al-count");
        if (!wrap || !rows || !cnt) return;
        if (!State.toggles.adminList_on || !AdminList.length) { wrap.classList.remove("show"); return; }
        wrap.classList.add("show");
        cnt.textContent = AdminList.length;
        rows.innerHTML = "";
        for (const a of AdminList) {
            const distTxt = (typeof a.dist === "number")
                ? (a.dist >= 100 ? Math.round(a.dist) + "m" : a.dist.toFixed(1) + "m")
                : "-";
            const row = document.createElement("div");
            row.className = "al-row";
            row.innerHTML =
                `<span class="al-dot"></span>` +
                `<span class="al-name">${escapeHtml(a.name || "Admin")}</span>` +
                `<span class="al-dist">${distTxt}</span>`;
            rows.appendChild(row);
        }
    }
    function pushKillFeed(line, sub, holdSecs) {
        const host = document.getElementById("killfeed");
        if (!host) return;
        const chip = document.createElement("div");
        chip.className = "kf-chip";
        chip.innerHTML =
            `<div class="kf-icon">&times;</div>` +
            `<div class="kf-body">${escapeHtml(line)}${sub ? `<span class="kf-sub">${escapeHtml(sub)}</span>` : ""}</div>`;
        host.appendChild(chip);
        while (host.children.length > 6) host.removeChild(host.firstChild);
        const hold = Math.max(2, Math.min(20, Number(holdSecs) || (State.sliders.killfeed_hold || 6))) * 1000;
        setTimeout(() => {
            chip.classList.add("out");
            setTimeout(() => chip.remove(), 320);
        }, hold);
    }
    let EventLog = [];       
    let Blocked  = new Set();
    function renderEventLog() {
        const box = document.getElementById("el-list");
        const cnt = document.getElementById("el-count");
        if (!box || !cnt) return;
        cnt.textContent = EventLog.length + " events";
        box.innerHTML = "";
        if (!EventLog.length) {
            box.innerHTML = `<div class="el-empty">no events captured</div>`;
            return;
        }
        for (let i = EventLog.length - 1; i >= 0; i--) {
            const e = EventLog[i];
            const row = document.createElement("div");
            row.className = "el-row";
            const isBlocked = Blocked.has(e.event);
            row.innerHTML =
                `<div class="el-name" title="${escapeHtml(e.event)}">${escapeHtml(e.event)}</div>` +
                `<div class="el-src">${escapeHtml(e.resource || "?")}</div>` +
                `<button class="el-block ${isBlocked ? "on" : ""}">${isBlocked ? "BLOCKED" : "BLOCK"}</button>`;
            row.querySelector(".el-block").addEventListener("click", () => {
                sendAction({ action: "eventBlock", event: e.event, block: !isBlocked });
                if (isBlocked) Blocked.delete(e.event); else Blocked.add(e.event);
                renderEventLog();
            });
            box.appendChild(row);
        }
    }
    function openEventLog() {
        sendAction({ action: "requestEventLog" });
        renderEventLog();
        document.getElementById("eventlogoverlay").classList.add("show");
    }
    function closeEventLog() { document.getElementById("eventlogoverlay").classList.remove("show"); }
    function clearEventLog() { sendAction({ action: "eventLogClear" }); EventLog = []; renderEventLog(); }
    window.openEventLog  = openEventLog;
    window.closeEventLog = closeEventLog;
    window.clearEventLog = clearEventLog;
    let Waypoints = [];  
    function renderWaypoints() {
        const box = document.getElementById("wp-list");
        const cnt = document.getElementById("wp-count");
        if (!box || !cnt) return;
        cnt.textContent = Waypoints.length + " saved";
        box.innerHTML = "";
        if (!Waypoints.length) {
            box.innerHTML = `<div class="el-empty">no markers saved</div>`;
            return;
        }
        Waypoints.forEach((wp, i) => {
            const idx = i + 1;
            const row = document.createElement("div");
            row.className = "wp-row";
            const cx = Math.round(wp.x||0), cy = Math.round(wp.y||0), cz = Math.round(wp.z||0);
            row.innerHTML =
                `<input class="wp-name-inp" value="${escapeHtml(wp.name||('Waypoint '+idx))}" />` +
                `<span class="wp-coords">${cx}, ${cy}, ${cz}</span>` +
                `<div class="wp-actions">` +
                    `<button class="wp-btn tp">TP</button>` +
                    `<button class="wp-btn del">DEL</button>` +
                `</div>`;
            const nameInp = row.querySelector(".wp-name-inp");
            const [tpBtn, delBtn] = row.querySelectorAll(".wp-btn");
            nameInp.addEventListener("change", () => {
                sendAction({ action: "wp_rename", idx: idx, name: nameInp.value });
            });
            tpBtn.addEventListener("click", () => sendAction({ action: "wp_tp", idx: idx }));
            delBtn.addEventListener("click", () => {
                sendAction({ action: "wp_delete", idx: idx });
                Waypoints.splice(i, 1);
                renderWaypoints();
            });
            box.appendChild(row);
        });
    }
    function openWaypoints() {
        sendAction({ action: "requestWaypoints" });
        renderWaypoints();
        document.getElementById("wpoverlay").classList.add("show");
    }
    function closeWaypoints() { document.getElementById("wpoverlay").classList.remove("show"); }
    window.openWaypoints  = openWaypoints;
    window.closeWaypoints = closeWaypoints;
    function applyWatermark() {
        const el = document.getElementById("watermark");
        if (!el) return;
        el.classList.remove("tl","tr","bl","br","hidden");
        const on  = State.toggles.watermark !== false;
        const pos = State.dropdowns.watermark_pos || "Bottom-Right";
        const streamer = State.toggles.streamer;
        if (!on || streamer) { el.classList.add("hidden"); return; }
        const map = { "Top-Left":"tl","Top-Right":"tr","Bottom-Left":"bl","Bottom-Right":"br" };
        el.classList.add(map[pos] || "br");
        const parts = ["omen"];
        if (Profile.server && Profile.server.name) parts.push(Profile.server.name.slice(0, 24));
        el.textContent = parts.join(" - ");
    }
    setInterval(applyWatermark, 1500);
    window.addEventListener("message", (e) => {
        if (e && e.data) window.handleFromLua(e.data);
    });
    function renderSidebar() {
        const nav = document.getElementById("nav");
        nav.innerHTML = "";
        for (const tab of MenuConfig.tabs) {
            const btn = document.createElement("div");
            btn.className = "nav-btn" + (tab.id === State.activeTabId ? " active" : "");
            const activeCount = countActive(tab.id);
            btn.innerHTML =
                `<span class="nav-ico">${SVG[tab.icon] || SVG.cog}</span>` +
                `<span class="nav-lbl">${tab.label}</span>` +
                (activeCount > 0 ? `<span class="nav-badge">${activeCount}</span>` : "");
            btn.addEventListener("click", () => {
                State.activeTabId = tab.id;
                renderSidebar();
                renderHead();
                renderPanel(tab.id);
            });
            nav.appendChild(btn);
        }
    }
    function countActive(tabId) {
        const cards = MenuConfig.panels[tabId] || [];
        let n = 0;
        for (const c of cards) {
            for (const item of (c.items || [])) {
                if (item.type === "toggle" && State.toggles[item.id]) n++;
                if (item.type === "btn-grid" && item.items) {
                    for (const sub of item.items) {
                        if (sub.style === "primary" && State.toggles[sub.id]) n++;
                    }
                }
            }
        }
        return n;
    }
    function renderHead() {
        const tab = MenuConfig.tabs.find(t => t.id === State.activeTabId);
        if (!tab) return;
        document.getElementById("sec-title").textContent = tab.label;
        document.getElementById("sec-crumb").innerHTML = tab.crumb;
        document.getElementById("sec-on-count").textContent = countAllActive();
    }
    function countAllActive() {
        let n = 0;
        for (const [id, v] of Object.entries(State.toggles)) { if (v) n++; }
        return n;
    }
    var __renderTimer = null;
    function renderPanelDebounced(tabId) {
        // coalesce rapid re-render requests (boot messages) into ONE render = no twitch/snap
        if (__renderTimer) clearTimeout(__renderTimer);
        __renderTimer = setTimeout(function(){ __renderTimer = null; renderPanel(tabId || State.activeTabId); }, 60);
    }
    function renderPanel(tabId) {
        const host = document.getElementById("panels");
        host.innerHTML = "";
        const cards = MenuConfig.panels[tabId] || [];
        const panel = document.createElement("div");
        panel.className = "panel on";
        if (tabId === "players") {
            panel.classList.add("panel-players");
            const g2 = document.createElement("div");
            g2.className = "g2 players-layout";
            const colA = document.createElement("div"); colA.className = "col";
            const colB = document.createElement("div"); colB.className = "col action-rail";
            for (const c of cards) {
                const el = buildCard(c);
                const isList = (c.items || []).some(i => i.type === "playerlist");
                if (isList) { el.classList.add("player-list-card"); colA.appendChild(el); }
                else        { el.classList.add("rail-card");        colB.appendChild(el); }
            }
            g2.appendChild(colA); g2.appendChild(colB);
            panel.appendChild(g2);
            host.appendChild(panel);
            return;
        }
        const g2 = document.createElement("div"); g2.className = "g2";
        const colA = document.createElement("div"); colA.className = "col";
        const colB = document.createElement("div"); colB.className = "col";
        // If any card declares an explicit col ("a"/"b"), honor it. Cards with
        // no col fall back to the auto half-split across whatever's left.
        const hasExplicit = cards.some(c => c.col === "a" || c.col === "b");
        if (hasExplicit) {
            const auto = cards.filter(c => c.col !== "a" && c.col !== "b");
            const half = Math.ceil(auto.length / 2);
            let ai = 0;
            for (const c of cards) {
                const el = buildCard(c);
                if (c.col === "a") colA.appendChild(el);
                else if (c.col === "b") colB.appendChild(el);
                else { (ai < half ? colA : colB).appendChild(el); ai++; }
            }
        } else {
            const half = Math.ceil(cards.length / 2);
            cards.slice(0, half).forEach(c => colA.appendChild(buildCard(c)));
            cards.slice(half).forEach(c => colB.appendChild(buildCard(c)));
        }
        g2.appendChild(colA); g2.appendChild(colB);
        panel.appendChild(g2);
        host.appendChild(panel);
    }
    function buildCard(card) {
        const el = document.createElement("div");
        el.className = "card";
        const head = document.createElement("div");
        head.className = "card-head";
        const togCount = (card.items || []).filter(i => i.type === "toggle").length;
        const onCount  = (card.items || []).filter(i => i.type === "toggle" && State.toggles[i.id]).length;
        head.innerHTML =
            `<span class="card-title">${card.title}</span>` +
            (togCount > 0 ? `<span class="card-count">${onCount}/${togCount}</span>` : "");
        el.appendChild(head);
        for (const item of (card.items || [])) el.appendChild(buildItem(item));
        return el;
    }
    function buildItem(item) {
        let el;
        switch (item.type) {
            case "toggle":    el = buildToggle(item);    break;
            case "slider":    el = buildSlider(item);    break;
            case "dropdown":  el = buildDropdown(item);  break;
            case "input":     el = buildInput(item);     break;
            case "btn-grid":  el = buildBtnGrid(item);   break;
            case "button":    el = buildButton(item);    break;
            case "keybind":   el = buildKeybind(item);   break;
            case "bindlist":  el = buildBindList();      break;
            case "seg":       el = buildSeg(item);       break;
            case "hint":      el = buildHint(item);      break;
            case "playerlist":el = buildPlayerList();    break;
            case "playersearch": el = buildPlayerSearch(); break;
            case "cfglist":   el = buildCfgList();       break;
            default:          el = document.createElement("div");
        }
        if (item.id && el.setAttribute) el.setAttribute("data-feat-id", item.id);
        if (item.type === "btn-grid" && item.items) {
            const btns = el.querySelectorAll(".btn");
            item.items.forEach((b, i) => btns[i] && b.id && btns[i].setAttribute("data-feat-id", b.id));
        }
        return el;
    }
    function buildToggle(item) {
        const row = document.createElement("div");
        row.className = "feat" + (State.toggles[item.id] ? " on" : "");
        row.innerHTML =
            `<div class="feat-ico">${SVG[item.icon] || SVG.shield}</div>` +
            `<div class="feat-body">` +
                `<div class="feat-name">${item.name}</div>` +
                (item.desc ? `<div class="feat-desc">${item.desc}</div>` : "") +
            `</div>` +
            `<div class="feat-tail">` +
                `<div class="bind${State.binds[item.id] ? " set" : ""}">` +
                    (State.binds[item.id]
                        ? State.binds[item.id]
                        : `<svg viewBox="0 0 24 24"><rect x="3" y="6" width="18" height="12" rx="2"/><path d="M7 10h.5M11 10h.5M15 10h.5M8 14h8"/></svg>`) +
                `</div>` +
                `<div class="sw${State.toggles[item.id] ? " on" : ""}"></div>` +
            `</div>`;
        // Single toggle path on the row. The bind button stops propagation so it
        // doesn't also toggle. No separate .sw listener = no double-fire.
        row.addEventListener("click", (e) => {
            if (e.target.closest(".bind")) return;   // bind button handles itself
            const _sw = row.querySelector(".sw");
            if (_sw) { _sw.classList.remove("pop"); void _sw.offsetWidth; _sw.classList.add("pop"); setTimeout(function(){ _sw.classList.remove("pop"); }, 320); }
            toggleFeat(row, item);
        });
        row.querySelector(".bind").addEventListener("click", (e) => {
            e.stopPropagation();
            openBind(item.id, item.name);
        });
        return row;
    }
    function toggleFeat(row, item) {
        const now = !State.toggles[item.id];
        State.toggles[item.id] = now;
        row.classList.toggle("on", now);
        row.querySelector(".sw").classList.toggle("on", now);
        sendAction({ action:"tog", id:item.id, v:now });
        toast(now ? "success" : "info", "Omen", `${item.name} ${now ? "enabled" : "disabled"}`);
        renderSidebar(); renderHead();
        const card = row.closest(".card");
        if (card) {
            const head = card.querySelector(".card-head");
            const items = (MenuConfig.panels[State.activeTabId] ? MenuConfig.panels[State.activeTabId].flatMap(function(c){return c.items;}) : []).filter(function(x){return x && x.type==="toggle";});
            const cardItems = Array.from(card.querySelectorAll(".feat"));
            const on = cardItems.filter(f => f.classList.contains("on")).length;
            const total = cardItems.length;
            const count = head.querySelector(".card-count");
            if (count) count.textContent = `${on}/${total}`;
        }
    }
    function buildSlider(item) {
        const wrap = document.createElement("div"); wrap.className = "sl";
        const val = (State.sliders[item.id] != null ? State.sliders[item.id] : item.value);
        State.sliders[item.id] = val;
        const pct = clamp01((val - (item.min != null ? item.min : 0)) / ((item.max != null ? item.max : 100) - (item.min != null ? item.min : 0)));
        wrap.innerHTML =
            `<div class="sl-head">` +
                `<span class="sl-lbl">${item.label}</span>` +
                `<span class="sl-val">${val}</span>` +
            `</div>` +
            `<div class="sl-track">` +
                `<div class="sl-fill" style="width:${pct*100}%"><div class="sl-thumb"></div></div>` +
            `</div>`;
        const track = wrap.querySelector(".sl-track");
        const fill  = wrap.querySelector(".sl-fill");
        const readout = wrap.querySelector(".sl-val");
        function drag(ev) {
            const r = track.getBoundingClientRect();
            const p = clamp01((ev.clientX - r.left) / r.width);
            const v = Math.round((item.min != null ? item.min : 0) + p * ((item.max != null ? item.max : 100) - (item.min != null ? item.min : 0)));
            State.sliders[item.id] = v;
            fill.style.width = (p * 100) + "%";
            readout.textContent = v;
        }
        function endDrag() {
            sendAction({ action:"sld", id:item.id, v: State.sliders[item.id] });
            document.removeEventListener("mousemove", drag);
            document.removeEventListener("mouseup", endDrag);
        }
        track.addEventListener("mousedown", (ev) => {
            drag(ev);
            document.addEventListener("mousemove", drag);
            document.addEventListener("mouseup", endDrag);
        });
        return wrap;
    }
    function buildDropdown(item) {
        const wrap = document.createElement("div"); wrap.className = "dd"; wrap.__ddId = item.id;
        var _opts = (State.__ddOptions && State.__ddOptions[item.id]) || item.options || [];
        const current = State.dropdowns[item.id] || _opts[0] || "";
        State.dropdowns[item.id] = current;
        wrap.innerHTML =
            (item.label ? `<div class="lbl">${item.label}</div>` : "") +
            `<button class="dd-btn" type="button"><span>${current}</span><span class="dd-caret">&#9662;</span></button>` +
            `<div class="dd-list"></div>`;
        const btn = wrap.querySelector(".dd-btn");
        const list = wrap.querySelector(".dd-list");

        // Build options + (re)attach listeners. Called on open so dynamically-scanned
        // options (addon weapons) always get fresh, working click handlers.
        function buildOpts() {
            const opts = (State.__ddOptions && State.__ddOptions[item.id]) || item.options || [];
            const cur = State.dropdowns[item.id] || opts[0] || "";
            list.innerHTML = opts.map(o => `<div class="dd-opt${o === cur ? " selected" : ""}" data-v="${o}">${o}</div>`).join("");
            list.querySelectorAll(".dd-opt").forEach(opt => {
                opt.addEventListener("click", (e) => {
                    e.stopPropagation();
                    const v = opt.dataset.v;
                    State.dropdowns[item.id] = v;
                    btn.querySelector("span").textContent = v;
                    closeThis();
                    sendAction({ action:"dd", id:item.id, v });
                });
            });
        }

        wrap.__ddClose = closeThis;
        function closeThis() {
            wrap.classList.remove("open");
            if (list.parentElement === document.body) { document.body.removeChild(list); wrap.appendChild(list); }
            list.style.cssText = "";
        }
        function openList() {
            buildOpts();
            const r = btn.getBoundingClientRect();
            // Move to body (escapes the panel's transform containing-block + overflow).
            document.body.appendChild(list);
            const spaceBelow = window.innerHeight - r.bottom - 12;
            const spaceAbove = r.top - 12;
            const wantH = Math.min(240, list.scrollHeight || 200);
            const openUp = spaceBelow < wantH && spaceAbove > spaceBelow;
            const maxH = Math.max(80, Math.min(240, openUp ? spaceAbove : spaceBelow));
            list.style.cssText =
                "display:block;position:fixed;z-index:999999;" +
                "left:" + Math.round(r.left) + "px;" +
                "width:" + Math.round(r.width) + "px;" +
                "max-height:" + Math.round(maxH) + "px;overflow-y:auto;overflow-x:hidden;" +
                (openUp
                    ? "bottom:" + Math.round(window.innerHeight - r.top + 4) + "px;top:auto;"
                    : "top:" + Math.round(r.bottom + 4) + "px;bottom:auto;");
        }
        btn.addEventListener("click", (e) => {
            e.stopPropagation();
            document.querySelectorAll(".dd.open").forEach(d => { if (d !== wrap && d.__ddClose) d.__ddClose(); });
            if (wrap.classList.contains("open")) { closeThis(); }
            else { wrap.classList.add("open"); openList(); }
        });
        return wrap;
    }
    function buildInput(item) {
        const wrap = document.createElement("div");
        if (item.label) {
            const lbl = document.createElement("div"); lbl.className = "lbl"; lbl.textContent = item.label;
            wrap.appendChild(lbl);
        }
        const inp = document.createElement("input"); inp.className = "inp"; inp.setAttribute("data-inp-id", item.id);
        inp.placeholder = item.placeholder || "";
        inp.value = (State.inputs[item.id] != null ? State.inputs[item.id] : "");
        let lastSent = inp.value;
        const commit = () => {
            State.inputs[item.id] = inp.value;
            if (inp.value === lastSent) return;
            lastSent = inp.value;
            sendAction({ action:"inp", id:item.id, v:inp.value });
        };
        inp.addEventListener("input", () => { State.inputs[item.id] = inp.value; });
        inp.addEventListener("focus", () => { window.__omFocusedInput = inp; wrap.classList.add("inp-focused"); sendAction({ action:"inpFocus", v:true }); });
        inp.addEventListener("blur", () => { commit(); if (window.__omFocusedInput === inp) window.__omFocusedInput = null; wrap.classList.remove("inp-focused"); sendAction({ action:"inpFocus", v:false }); commit(); });
        inp.addEventListener("keydown", (e) => { if (e.key === "Enter") { commit(); inp.blur(); } });
        wrap.appendChild(inp);
        return wrap;
    }
    function buildKeybind(item) {
        const row = document.createElement("div");
        row.className = "kb-row";
        const cur = (State.binds && State.binds[item.id]) ? State.binds[item.id] : "None";
        row.innerHTML = `<span class="kb-lbl">${item.label}</span>` +
            `<button class="kb-box" type="button" data-bind="${item.id}"><span>${cur}</span></button>`;
        row.querySelector(".kb-box").addEventListener("click", (e) => {
            e.stopPropagation();
            const box = e.currentTarget;
            box.classList.add("listening");
            box.querySelector("span").textContent = "Press key...";
            openBind(item.id, item.label);
        });
        return row;
    }
    function buildBindList() {
        const wrap = document.createElement("div");
        wrap.className = "bindlist";
        wrap.id = "bindlist";
        renderBindList(wrap);
        return wrap;
    }
    function renderBindList(wrap) {
        wrap = wrap || document.getElementById("bindlist");
        if (!wrap) return;
        const b = State.binds || {};
        const keys = Object.keys(b).filter(k => b[k] && b[k] !== "None");
        if (keys.length === 0) {
            wrap.innerHTML = '<div class="bl-head">Active Binds<span class="bl-cnt">0</span></div><div class="bl-empty">No keys bound yet</div>';
            return;
        }
        const niceName = { open_key:"Open Menu", panic_key:"Panic Uninject", aimbot_toggle_bind:"Aimbot", freecam_toggle_bind:"Freecam", solosession_toggle_bind:"Solo Session" };
        let rows = keys.map(k => {
            const nm = niceName[k] || k.replace(/_toggle_bind$/,"").replace(/_/g," ");
            return '<div class="bl-row"><span class="bl-name">' + nm + '</span><span class="bl-key">' + b[k] + '</span></div>';
        }).join("");
        wrap.innerHTML = '<div class="bl-head">Active Binds<span class="bl-cnt">' + keys.length + '</span></div>' + rows;
    }
    function buildButton(item) {
        const b = document.createElement("button");
        b.className = "btn btn-full" + (item.style ? (" " + item.style) : "");
        b.type = "button";
        b.innerHTML = (item.icon && SVG[item.icon] ? SVG[item.icon] : "") + `<span>${item.label || ""}</span>`;
        b.addEventListener("click", (e) => {
            e.stopPropagation();
            // flush any focused input first so its typed value reaches Lua before this action
            if (window.__omFocusedInput && window.__omFocusedInput.blur) { window.__omFocusedInput.blur(); }
            // ALSO snapshot every input's current value and send it WITH the button action,
            // so the handler always has fresh values (no reliance on commit timing/dedupe).
            try {
                document.querySelectorAll('[data-inp-id]').forEach(function(el){
                    const iid = el.getAttribute('data-inp-id');
                    if (iid && el.value !== undefined && el.value !== "") {
                        // send each input value as its own flat inp action (parseable by Lua)
                        sendAction({ action:"inp", id: iid, v: el.value });
                    }
                });
            } catch (err) {}
            sendAction({ action:"btn", id:item.id });
            const severity = item.style === "risky" ? "failure" : "success";
            toast(severity, "Omen", item.label);
        });
        return b;
    }
    function buildBtnGrid(item) {
        const g = document.createElement("div"); g.className = "btn-grid";
        for (const b of (item.items || [])) {
            const el = document.createElement("button");
            el.className = "btn" + (b.style ? " " + b.style : "");
            el.innerHTML = (b.icon ? SVG[b.icon] : "") + `<span>${b.label}</span>`;
            el.addEventListener("click", () => {
                if (b.id === "eventlog_open") { openEventLog(); return; }
                if (b.id === "tp_history")    { openWaypoints(); sendAction({action:"btn", id:b.id}); return; }
                if (b.id === "cw_open")       { openCustomWeapons(); return; }
                if (b.id.startsWith("cfg_")) {
                    // Lua answers with its own toast (saved / not found / etc.)
                    sendAction({ action:"btn", id:b.id, v:(State.inputs.cfg_name || "").trim() });
                    return;
                }
                sendAction({ action:"btn", id:b.id });
                const severity = b.style === "risky" ? "failure" : "success";
                toast(severity, "Omen", b.label);
            });
            g.appendChild(el);
        }
        return g;
    }
    function buildSeg(item) {
        const wrap = document.createElement("div"); wrap.className = "seg";
        const current = State.segs[item.id] || item.options[0];
        State.segs[item.id] = current;
        for (const o of item.options) {
            const el = document.createElement("div");
            el.className = "seg-opt" + (o === current ? " on" : "");
            el.textContent = o;
            el.addEventListener("click", () => {
                State.segs[item.id] = o;
                wrap.querySelectorAll(".seg-opt").forEach(s => s.classList.toggle("on", s.textContent === o));
                sendAction({ action:"seg", id:item.id, v:o });
            });
            wrap.appendChild(el);
        }
        return wrap;
    }
    function buildHint(item) {
        const el = document.createElement("div"); el.className = "hint";
        el.textContent = item.text;
        return el;
    }
    function nameShade(name) {
        let h = 5381;
        for (let i = 0; i < name.length; i++) h = ((h << 5) + h) ^ name.charCodeAt(i);
        const t = ((h >>> 0) % 1000) / 1000;
        return 0.35 + t * 0.60;
    }
    function dotClass(alive) { return alive ? "dot" : "dot dead"; }
    let __plistSig = "";
    function updatePlayerListInPlace() {
        const host = document.querySelector(".plist");
        if (!host) { renderPanel(State.activeTabId); return; }
        const list = (PlayerList || []).slice().sort(function(a, b){
            if (a.isMe && !b.isMe) return -1;
            if (b.isMe && !a.isMe) return 1;
            return (a.dist || 0) - (b.dist || 0);
        });
        // Structural signature: only the set of players + alive/veh state.
        // Distance is NOT in it - distance updates patch existing rows in place,
        // so the list never rebuilds (no twitch, no scroll jump) just because
        // someone moved a few meters.
        const sig = list.map(function(p){ return p.id + ":" + (p.alive !== false ? 1 : 0) + ":" + (p.veh ? 1 : 0); }).join(",");
        if (sig !== __plistSig) {
            // Roster changed (someone joined/left/died/entered vehicle) - rebuild rows
            __plistSig = sig;
            const scroll = host.scrollTop;
            const fresh = buildPlayerList();
            host.innerHTML = fresh.innerHTML;
            host.scrollTop = scroll;
            attachPlistClick(host);
            reapplyPlayerSearch();
        } else {
            // Same roster - just patch distance text on existing rows, no reflow
            for (const p of list) {
                const row = host.querySelector('.pitem[data-pid="' + p.id + '"]');
                if (!row) continue;
                const distEl = row.querySelector(".p-dist");
                if (distEl) {
                    distEl.textContent = (typeof p.dist === "number")
                        ? (p.dist >= 100 ? Math.round(p.dist) + "m" : p.dist.toFixed(1) + "m") : "-";
                }
            }
        }
    }
    function attachPlistClick(host) {
        if (!host || host.__omenClick) return;
        host.__omenClick = true;
        host.addEventListener("click", function(e) {
            const row = e.target && e.target.closest ? e.target.closest(".pitem") : null;
            if (!row) return;
            const pid = parseInt(row.getAttribute("data-pid"), 10);
            if (isNaN(pid)) return;
            State.selectedPlayer = pid;
            host.querySelectorAll(".pitem.sel").forEach(function(el){ el.classList.remove("sel"); });
            row.classList.add("sel");
            sendAction({ action:"playerSelect", serverId: pid });
            toast("info", "Omen", "Selected " + (row.getAttribute("data-pname") || ("#"+pid)), 1400);
        });
    }
    function reapplyPlayerSearch() {
        const q = (State.__plsearch || "").trim().toLowerCase();
        if (!q) return;
        const host = document.querySelector(".plist");
        if (!host) return;
        host.querySelectorAll(".pitem").forEach(function(row){
            const pid = row.getAttribute("data-pid") || "";
            const pnm = (row.getAttribute("data-pname") || "").toLowerCase();
            const hit = pid.indexOf(q.replace("#","")) === 0 || pnm.indexOf(q) !== -1;
            row.style.display = hit ? "" : "none";
        });
    }
    function buildPlayerSearch() {
        const wrap = document.createElement("div");
        wrap.className = "psearch";
        wrap.innerHTML =
            '<span class="psearch-ico">' + (SVG.search || "") + '</span>' +
            '<input class="psearch-inp" type="text" placeholder="Search by name or #ID..." spellcheck="false">' +
            '<span class="psearch-count"></span>';
        const inp = wrap.querySelector(".psearch-inp");
        const applyFilter = function() {
            const q = (inp.value || "").trim().toLowerCase();
            State.__plsearch = q;
            const host = document.querySelector(".plist");
            if (!host) return;
            let shown = 0;
            const rows = host.querySelectorAll(".pitem");
            rows.forEach(function(row){
                const pid  = row.getAttribute("data-pid") || "";
                const pnm  = (row.getAttribute("data-pname") || "").toLowerCase();
                const hit  = q === "" || pid.indexOf(q.replace("#","")) === 0 || pnm.indexOf(q) !== -1;
                row.style.display = hit ? "" : "none";
                if (hit) shown++;
            });
            const cnt = wrap.querySelector(".psearch-count");
            if (cnt) cnt.textContent = q ? (shown + " match" + (shown === 1 ? "" : "es")) : "";
            // Exact #ID match &rarr; auto-select that player
            const exact = q.replace("#","");
            if (exact !== "" && /^\d+$/.test(exact)) {
                const target = host.querySelector('.pitem[data-pid="' + exact + '"]');
                if (target) {
                    State.selectedPlayer = parseInt(exact, 10);
                    host.querySelectorAll(".pitem.sel").forEach(function(el){ el.classList.remove("sel"); });
                    target.classList.add("sel");
                }
            }
        };
        // typing focus signal to Lua (block game input) + focus styling
        inp.addEventListener("focus", function(){ window.__omFocusedInput = inp; wrap.classList.add("focused"); sendAction({ action:"inpFocus", v:true }); });
        inp.addEventListener("blur",  function(){ if (window.__omFocusedInput === inp) window.__omFocusedInput = null; wrap.classList.remove("focused"); sendAction({ action:"inpFocus", v:false }); });
        inp.addEventListener("input", applyFilter);
        inp.addEventListener("keydown", function(e){ if (e.key === "Enter") { applyFilter(); inp.blur(); } });
        // restore prior query
        if (State.__plsearch) { inp.value = State.__plsearch; setTimeout(applyFilter, 0); }
        return wrap;
    }
    function buildPlayerList() {
        const wrap = document.createElement("div"); wrap.className = "plist";
        if (!PlayerList || PlayerList.length === 0) {
            const empty = document.createElement("div");
            empty.className = "plist-empty";
            empty.textContent = "waiting for players...";
            wrap.appendChild(empty);
            return wrap;
        }
        const sorted = PlayerList.slice().sort((a, b) => {
            if (a.isMe && !b.isMe) return -1;
            if (b.isMe && !a.isMe) return 1;
            return (a.dist || 0) - (b.dist || 0);
        });
        for (const p of sorted) {
            const row = document.createElement("div");
            const cls = ["pitem"];
            if (State.selectedPlayer === p.id) cls.push("sel");
            if (p.isMe) cls.push("me");
            row.className = cls.join(" ");
            const shade = nameShade(p.name || "");
            const distTxt = (typeof p.dist === "number") ? (p.dist >= 100 ? Math.round(p.dist) + "m" : p.dist.toFixed(1) + "m") : "-";
            row.innerHTML =
                `<div class="prail" style="background: rgba(255,255,255,${shade.toFixed(2)})"></div>` +
                `<div class="pav">${(p.name || "?").charAt(0).toUpperCase()}</div>` +
                `<div class="pinfo">` +
                    `<div class="pname">${escapeHtml(p.name || "Unknown")}</div>` +
                    `<div class="prow2">` +
                        `<span class="p-chip">#${p.id}</span>` +
                        `<span class="p-chip ${dotClass(p.alive !== false)}">${p.alive === false ? "DEAD" : "ALIVE"}</span>` +
                        `<span class="p-chip p-dist">${distTxt}</span>` +
                        (p.veh ? `<span class="p-chip veh">IN VEH</span>` : "") +
                    `</div>` +
                `</div>`;
            row.setAttribute("data-pid", String(p.id));
            row.setAttribute("data-pname", p.name || "Unknown");
            wrap.appendChild(row);
        }
        attachPlistClick(wrap);
        return wrap;
    }
    function buildCfgList() {
        const wrap = document.createElement("div"); wrap.className = "plist";
        if (!CfgList || CfgList.length === 0) {
            const empty = document.createElement("div");
            empty.className = "plist-empty";
            empty.textContent = "no configs saved";
            wrap.appendChild(empty);
            return wrap;
        }
        for (const c of CfgList) {
            const row = document.createElement("div");
            row.className = "cfg-item";
            row.innerHTML =
                `<div class="prail"></div>` +
                `<div class="cfg-body">` +
                    `<div class="cfg-name">${escapeHtml(c.name)}</div>` +
                    `<div class="cfg-meta">${c.modified || "saved"}</div>` +
                `</div>` +
                `<div class="cfg-actions">` +
                    `<button class="cfg-btn">LOAD</button>` +
                    `<button class="cfg-btn del">DEL</button>` +
                `</div>`;
            const [loadBtn, delBtn] = row.querySelectorAll(".cfg-btn");
            loadBtn.addEventListener("click", (e) => {
                e.stopPropagation();
                sendAction({ action:"btn", id:"cfg_load", v:c.name });
                toast("success", "Omen", `Loading ${c.name}`, 1400);
            });
            delBtn.addEventListener("click", (e) => {
                e.stopPropagation();
                sendAction({ action:"btn", id:"cfg_delete", v:c.name });
                CfgList = CfgList.filter(x => x.name !== c.name);
                renderPanel(State.activeTabId);
                toast("info", "Omen", `Deleted ${c.name}`, 1400);
            });
            wrap.appendChild(row);
        }
        return wrap;
    }
    let __itemTypes = null;
    function itemType(id) {
        if (!__itemTypes) {
            __itemTypes = Object.create(null);
            for (const cards of Object.values(MenuConfig.panels))
                for (const c of cards) for (const it of (c.items || [])) if (it && it.id) __itemTypes[it.id] = it.type;
        }
        return __itemTypes[id];
    }
    function escapeHtml(s) {
        return String(s == null ? "" : s)
            .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    }
    function clamp01(x) { return Math.max(0, Math.min(1, x)); }
    document.addEventListener("click", (e) => {
        // Clicked inside a dropdown trigger OR its (body-moved) list - don't close.
        if (e.target && e.target.closest && (e.target.closest(".dd") || e.target.closest(".dd-list"))) return;
        document.querySelectorAll(".dd.open").forEach(d => { if (d.__ddClose) d.__ddClose(); });
    });
    // ============================================================
    // TOAST
    // ============================================================
    function toast(severity, title, message, ttl = 2600) {
        const host = document.getElementById("toasts");
        const el = document.createElement("div");
        const sev = (severity === "failure" || severity === "error") ? "failure"
                  : (severity === "info") ? "info" : "success";
        el.className = "toast " + sev;
        const ico = sev === "failure" ? SVG.alert : (sev === "info" ? (SVG.info || SVG.check) : SVG.check);
        el.innerHTML =
            `<div class="stripe"></div>` +
            `<div class="ico">${ico}</div>` +
            `<div class="body">` +
                `<div class="title">${escapeHtml(title)}</div>` +
                `<div class="msg">${escapeHtml(message)}</div>` +
            `</div>` +
            `<div class="bar" style="animation-duration:${ttl}ms"></div>`;
        host.appendChild(el);
        setTimeout(() => {
            el.classList.add("leaving");
            setTimeout(() => el.remove(), 240);
        }, ttl);
    }
    window.toast = toast;
    // ============================================================
    // BIND MODAL
    // ============================================================
    function openBind(id, name) {
        bindingId = id;
        sendAction({ action:"bindMode", v:true });
        document.getElementById("bind-feature").textContent = name;
        document.getElementById("bind-key").textContent = State.binds[id] || "-";
        document.getElementById("bindoverlay").classList.add("on");
    }
    function closeBind() {
        document.querySelectorAll(".kb-box.listening").forEach(function(b){ b.classList.remove("listening"); var id=b.getAttribute("data-bind"); b.querySelector("span").textContent = (State.binds&&State.binds[id])?State.binds[id]:"None"; });
        bindingId = null;
        sendAction({ action:"bindMode", v:false });
        document.getElementById("bindoverlay").classList.remove("on");
    }
    window.closeBind = closeBind;
    // ============================================================
    // COMMAND PALETTE
    // ============================================================
    function openPalette() {
        document.getElementById("palette").classList.add("on");
        const inp = document.getElementById("pal-input");
        inp.value = "";
        renderPaletteResults("");
        setTimeout(() => inp.focus(), 30);
    }
    function closePalette() {
        document.getElementById("palette").classList.remove("on");
    }
    window.openPalette = openPalette;
    document.getElementById("palette").addEventListener("click", (e) => {
        if (e.target.id === "palette") closePalette();
    });
    let palActiveIdx = 0;
    document.getElementById("pal-input").addEventListener("input", (e) => {
        renderPaletteResults(e.target.value);
    });
    document.addEventListener("keydown", (e) => {
        // Bind mode capture (must run first)
        if (bindingId) {
            if (e.key === "Escape") { closeBind(); return; }
            const key = (e.key.length === 1 ? e.key.toUpperCase() : e.key);
            State.binds[bindingId] = key;
            document.getElementById("bind-key").textContent = key;
            sendAction({ action:"bind", id: bindingId, v: key });
            setTimeout(closeBind, 300);
            return;
        }
        // Palette shortcuts
        if ((e.ctrlKey || e.metaKey) && e.key === "k") { e.preventDefault(); openPalette(); return; }
        const paletteOpen = document.getElementById("palette").classList.contains("on");
        if (paletteOpen) {
            if (e.key === "Escape") { closePalette(); return; }
            const results = document.querySelectorAll(".pal-item");
            if (results.length === 0) return;
            if (e.key === "ArrowDown") { palActiveIdx = (palActiveIdx + 1) % results.length; updatePalActive(results); e.preventDefault(); }
            if (e.key === "ArrowUp")   { palActiveIdx = (palActiveIdx - 1 + results.length) % results.length; updatePalActive(results); e.preventDefault(); }
            if (e.key === "Enter")     { results[palActiveIdx].click(); e.preventDefault(); }
        }
    });
    function updatePalActive(results) {
        results.forEach((r, i) => r.classList.toggle("act", i === palActiveIdx));
        if(results[palActiveIdx]) results[palActiveIdx].scrollIntoView({ block: "nearest" });
    }
    function collectPaletteItems() {
        const items = [];
        for (const tab of MenuConfig.tabs) {
            const cards = MenuConfig.panels[tab.id] || [];
            for (const card of cards) {
                for (const item of (card.items || [])) {
                    if (!item.id || !item.name && !item.label) continue;
                    items.push({
                        name: item.name || item.label,
                        path: `${tab.label} / ${card.title}`,
                        tabId: tab.id,
                        icon: item.icon || tab.icon,
                        type: item.type,
                        id: item.id,
                    });
                }
            }
        }
        return items;
    }
    const PaletteItems = collectPaletteItems();
    function renderPaletteResults(query) {
        const host = document.getElementById("pal-results");
        host.innerHTML = "";
        const q = query.trim().toLowerCase();
        const filtered = q
            ? PaletteItems.filter(i => i.name.toLowerCase().includes(q) || i.path.toLowerCase().includes(q))
            : PaletteItems.slice(0, 20);
        palActiveIdx = 0;
        filtered.slice(0, 60).forEach((it, i) => {
            const row = document.createElement("div");
            row.className = "pal-item" + (i === 0 ? " act" : "");
            row.innerHTML =
                `<div class="pal-ico">${SVG[it.icon] || SVG.cog}</div>` +
                `<div class="pal-body">` +
                    `<div class="pal-name">${it.name}</div>` +
                    `<div class="pal-path">${it.path}</div>` +
                `</div>` +
                `<span class="pal-tag">${it.type}</span>`;
            row.addEventListener("click", () => {
                State.activeTabId = it.tabId;
                closePalette();
                renderSidebar(); renderHead(); renderPanel(it.tabId);
                // Scroll the target feature into view + pulse-highlight it.
                setTimeout(() => {
                    const panels = document.getElementById("panels");
                    const target = panels && panels.querySelector(`[data-feat-id="${CSS.escape(it.id)}"]`);
                    if (target) {
                        target.scrollIntoView({ behavior: "smooth", block: "center" });
                        target.classList.add("pulse-highlight");
                        setTimeout(() => target.classList.remove("pulse-highlight"), 1200);
                    }
                }, 50);
                toast("info", "Omen", `Jumped to ${it.name}`, 1400);
            });
            host.appendChild(row);
        });
    }
    // ============================================================
    // KEYBOARD (forwarded from Lua via VK codes)
    // ============================================================
    const VK_SHIFT = { "1":"!","2":"@","3":"#","4":"$","5":"%","6":"^","7":"&","8":"*","9":"(","0":")",
        "0xBA":":","0xBB":"+","0xBC":"<","0xBD":"_","0xBE":">","0xBF":"?","0xC0":"~","0xDB":"{","0xDC":"|","0xDD":"}","0xDE":'"' };
    const VK_BASE = { "0xBA":";","0xBB":"=","0xBC":",","0xBD":"-","0xBE":".","0xBF":"/","0xC0":"`","0xDB":"[","0xDC":"\\","0xDD":"]","0xDE":"'","0x20":" " };
    function vkToChar(vk, shift) {
        if (vk >= 0x41 && vk <= 0x5A) { const c = String.fromCharCode(vk); return shift ? c : c.toLowerCase(); }
        if (vk >= 0x30 && vk <= 0x39) return shift ? VK_SHIFT[String(vk - 0x30)] : String(vk - 0x30);
        if (vk >= 0x60 && vk <= 0x69) return String(vk - 0x60);           // numpad 0-9
        const k = "0x" + vk.toString(16).toUpperCase();
        if (shift && VK_SHIFT[k]) return VK_SHIFT[k];
        return VK_BASE[k] || null;
    }
    // Block NATIVE typing on menu inputs - keystrokes come only via Lua __omKey.
    // Prevents double characters (native browser input + our injection both firing).
    document.addEventListener("keydown", function(e){
        const el = e.target;
        if (el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA")) {
            // Let control combos through natively is unnecessary - Lua handles them.
            // Block the default so the browser never inserts a char itself.
            if (e.key && e.key.length === 1) e.preventDefault();
        }
    }, true);
    document.addEventListener("keypress", function(e){
        const el = e.target;
        if (el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA")) e.preventDefault();
    }, true);
    document.addEventListener("beforeinput", function(e){
        const el = e.target;
        if (el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA")) {
