    }
    // Clipboard text goes to Lua hex-encoded (the Lua bridge parser can't handle quotes/braces);
    // Lua writes it to the real OS clipboard. execCommand("copy") can't be used for this: the
    // "OMEN:" action bridge overwrites the clipboard on the very next action.
    function __omHex(str) {
