    function __omSetSel(el, s, e, dir) { try { el.setSelectionRange(s, e, dir || "none"); } catch (_) {} }
    // Ctrl combos + caret keys for the Lua-driven inputs. Returns true when handled.
    function __omEditKey(el, vk, shift, ctrl) {
        const v = el.value, len = v.length;
