            if (vk === 0x41) { try { el.focus(); } catch (_) {} __omSetSel(el, 0, len); return true; }   // Ctrl+A
            if (vk === 0x43 || vk === 0x58) {                                                       // Ctrl+C / Ctrl+X
                if (s === e) return true;
