            if (vk === 0x08) {                                                                      // Ctrl+Backspace: delete word
                if (s !== e) { el.value = v.slice(0, s) + v.slice(e); __omSetSel(el, s, s); changed(); return true; }
                let i = s; while (i > 0 && v[i - 1] === " ") i--; while (i > 0 && v[i - 1] !== " ") i--;
                el.value = v.slice(0, i) + v.slice(s); __omSetSel(el, i, i); changed(); return true;
