        window.__omTypingStart = (el) => { if (isText(el)) start(el); };
        window.__omTypingStop = stop;
    })();
    window.__omKey = function(vk, shift, ctrl) {
        if (typeof bindingId !== "undefined" && bindingId) {
            if (vk === 0x1B) { closeBind(); return; }
            const bkey = vkToBindName(vk, shift);
            if (bkey) {
                State.binds[bindingId] = bkey;
                const bk = document.getElementById("bind-key");
                if (bk) bk.textContent = bkey;
                // update the keybind box in settings + refresh the bind list
                const kbBox = document.querySelector('.kb-box[data-bind="' + bindingId + '"]');
                if (kbBox) { kbBox.classList.remove("listening"); kbBox.querySelector("span").textContent = bkey; }
                if (typeof renderBindList === "function") renderBindList();
                sendAction({ action:"bind", id: bindingId, v: bkey });
                setTimeout(closeBind, 300);
            }
            return;
        }
        const el = (document.activeElement && (document.activeElement.tagName === "INPUT" || document.activeElement.tagName === "TEXTAREA"))
                 ? document.activeElement : window.__omFocusedInput;
        const editable = el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA");
        if (vk === 0x1B) { el && el.blur(); return; }              // Esc
        if (!editable) return;
        if (vk === 0x08 && !ctrl) {                                 // Backspace
            const s = el.selectionStart, e = el.selectionEnd;
            if (s === e && s > 0) { el.value = el.value.slice(0, s - 1) + el.value.slice(e); el.setSelectionRange(s - 1, s - 1); }
            else { el.value = el.value.slice(0, s) + el.value.slice(e); el.setSelectionRange(s, s); }
            el.dispatchEvent(new Event("input", { bubbles: true })); return;
        }
        if (vk === 0x0D) { el.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true })); return; }
        if (__omEditKey(el, vk, shift, ctrl)) return;
        if (ctrl) return;   // swallow unhandled Ctrl combos instead of typing the letter
        const ch = vkToChar(vk, shift);
        if (ch) window.__omInsert(ch);
    };
    // ============================================================
    // CURSOR
    // ============================================================
    // == SHADOW 1:1 CURSOR SYSTEM ==
    var cur = document.getElementById('cursor');
    var __menuEl = document.getElementById('menu');
    var cx = window.innerWidth / 2;
    var cy = window.innerHeight / 2;
    var lastHovered = null;
    var isDraggingMenu = false;
    var menuDragOX = 0, menuDragOY = 0;
    var isMouseDown = false;
    var draggingSlider = null;
    var pendingClickEl = null;
    var activeInput = null;
    window._duiMode = false;
    // Browser preview: if not driven by Lua (browser test), show demo overlay data
    setTimeout(function(){
        if (window._duiMode) return; // in-game, Lua drives these
        try {
            var bs = document.getElementById("bubbleseeroverlay");
            if (bs) {
                bs.classList.add("show");
                bs.innerHTML = '<div class="spec-head"><span class="dot"></span>Bubble Seer<span class="cnt">2</span></div>' +
                    '<div class="spec-row"><span class="sav">A</span><span class="snm">Amari</span><span class="sid">#123</span></div>' +
                    '<div class="spec-row"><span class="sav">K</span><span class="snm">Kobe</span><span class="sid">#88</span></div>';
            }
            var so = document.getElementById("spectatoroverlay");
            if (so) {
                so.classList.add("show");
                so.innerHTML = '<div class="spec-head"><span class="dot"></span>Spectating You<span class="cnt">1</span></div>' +
                    '<div class="spec-row"><span class="sav">M</span><span class="snm">mod_watcher</span><span class="sid">#5</span></div>';
            }
        } catch(e){}
    }, 800);

    // Omen slider drag: sets fill + value text live from cursor x
    function updateSlider(track, curX) {
        var r = track.getBoundingClientRect();
        var p = Math.max(0, Math.min(1, (curX - r.left) / r.width));
        var fill = track.querySelector('.sl-fill');
        var row = track.closest('.sl');
        var readout = row ? row.querySelector('.sl-val') : null;
        var min = parseFloat(track.dataset.min || '0');
        var max = parseFloat(track.dataset.max || '100');
        var v = Math.round(min + p * (max - min));
        if (fill) fill.style.width = (p * 100) + '%';
        if (readout) readout.textContent = v;
        if (row) row.dataset.liveval = v;
    }

    // Cursor + menu drag move with transform (GPU-composited) instead of left/top, which
    // re-laid-out and re-painted the whole menu every frame = the drag stutter.
    cur.style.left = '0px'; cur.style.top = '0px';
    function updateCursorPos() { cur.style.transform = 'translate3d(' + cx + 'px,' + cy + 'px,0)'; }
    updateCursorPos();
    function getElUnder() { return document.elementFromPoint(cx, cy); }
    var CLICKABLE = '.feat,.nav-btn,.tab,.btn,.bind,.pitem,.ocard,.sw,.dd-btn,.dd-opt,.inp,.sel,.seg-opt,.kb-btn,.p-btn,.sl-track,.hdr-btn';

    var hoverTick = 0;
    function cursorLoop() {
        if (isDraggingMenu && isMouseDown && __menuEl) {
            window.__omPlaceMenu(__menuEl, cx - menuDragOX, cy - menuDragOY);
        }
        var scrollFrozen = window._scrollFreezeUntil && performance.now() < window._scrollFreezeUntil;
        if (!scrollFrozen && !isDraggingMenu && hoverTick++ % 2 === 0) {
            var el = getElUnder();
            var hoverable = el ? el.closest(CLICKABLE) : null;
            if (hoverable !== lastHovered) {
                if (lastHovered) lastHovered.classList.remove('cursor-hover');
                if (hoverable)   hoverable.classList.add('cursor-hover');
                cur.classList.toggle('hovering', !!hoverable);
                lastHovered = hoverable;
            }
        }
        requestAnimationFrame(cursorLoop);
    }
    requestAnimationFrame(cursorLoop);

    function doMouseDown() {
        isMouseDown = true;
        cur.classList.add('clicking');
        var el = getElUnder();
        if (!el) return;
        // Menu drag: press on header (but not on a button/search) starts dragging
        var hdr = el.closest('#header');
        if (hdr && !el.closest('.hdr-btn, .hdr-search, .btn, button')) {
            var menu = document.getElementById('menu');
            if (menu) {
                var r = menu.getBoundingClientRect();
                isDraggingMenu = true;
                menuDragOX = cx - r.left;
                menuDragOY = cy - r.top;
                // no transform transition while dragging (it made the menu trail the cursor)
                menu.style.transition = 'opacity .16s ease';
                menu.style.willChange = 'transform';
                window.__omPlaceMenu(menu, r.left, r.top);
                return;
            }
        }
        pendingClickEl = el.closest('.feat,.nav-btn,.tab,.btn,.pitem,.ocard,.dd-btn,.dd-opt,.inp,.sel,.seg-opt,.kb-btn,.p-btn,.hdr-btn,.bind') || el;
        // Sliders need a real mousedown to start their drag listener.
        var track = el.closest('.sl-track');
        if (track) {
            pendingClickEl = null;  // slider drag, not a click
            var opts = { bubbles: true, cancelable: true, view: window, clientX: cx, clientY: cy };
            track.dispatchEvent(new MouseEvent('mousedown', opts));
            return;
        }
        // Do NOT dispatch mousedown for clickables (mousedown+mouseup auto-generates a click,
        // which combined with our manual click = DOUBLE. We fire one click in doMouseUp.)
        // focus inputs on press so typing + focus ring work
        var inp = el.closest('input, textarea');
        // Start the focus animation directly too: the offscreen DUI often has no OS focus,
        // so the browser's own focus events don't reliably fire.
        if (inp) { inp.focus(); window.__omFocusedInput = inp; if (window.__omTypingStart) window.__omTypingStart(inp); }
        else {
            if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
            if (window.__omTypingStop) window.__omTypingStop();
        }
    }
    function doMouseUp() {
        isMouseDown = false;
        cur.classList.remove('clicking');
        if (isDraggingMenu) {
            isDraggingMenu = false; pendingClickEl = null;
            if (__menuEl) __menuEl.style.willChange = '';
            return;
        }
        var el = getElUnder();
        var opts = { bubbles: true, cancelable: true, view: window, clientX: cx, clientY: cy };
        var target = pendingClickEl || el;
        // Hard global click lock: no click of ANY kind within 250ms of the last one.
        // Kills duplicate curUp cascades from the bridge regardless of target.
        var _now = Date.now();
        if ((_now - (window.__globalClickLock || 0)) < 250) {
            pendingClickEl = null;
            return;
        }
        window.__globalClickLock = _now;
        // Fire mouseup on the element (for drag-release listeners), then ONE click.
        // We do NOT dispatch on the same element twice - single click only = no duplicates.
        if (el) el.dispatchEvent(new MouseEvent('mouseup', opts));
        if (target) target.dispatchEvent(new MouseEvent('click', opts));
        pendingClickEl = null;
    }
    function doScroll(delta) {
        var el = getElUnder();
        while (el && el !== document.body) {
            if (el.scrollHeight > el.clientHeight) {
                window._scrollFreezeUntil = performance.now() + 180;
                if (lastHovered) { lastHovered.classList.remove('cursor-hover'); lastHovered = null; }
                cur.classList.remove('hovering');
                if (typeof el.scrollBy === 'function') el.scrollBy({ top: delta, behavior: 'smooth' });
                else el.scrollTop += delta;
                return;
            }
            el = el.parentElement;
        }
    }
    function setCursor(x, y) {
        cx = x; cy = y;
        updateCursorPos();
        window._cx = cx; window._cy = cy;
        // Menu drag only needs the new position (applied in cursorLoop); skip the hit-test.
        if (isDraggingMenu) return;
        // dispatch mousemove so drag listeners (sliders) + hover track the cursor
        var el = document.elementFromPoint(cx, cy);
        if (el) el.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, view: window, clientX: cx, clientY: cy }));
    }
    window.setCursor = setCursor;
     window.doMouseDown = doMouseDown; window.doMouseUp = doMouseUp; window.doScroll = doScroll;
    function getDuiSize() { return window.innerWidth + ',' + window.innerHeight; }
    window.getDuiSize = getDuiSize;
    // browser preview fallback
    document.addEventListener('mousemove', function(e){ if (!window._duiMode) { cx = e.clientX; cy = e.clientY; } });

    // ============================================================
    // MENU DRAG (header is handle)
    // ============================================================
    (function enableDrag() {
        const menu = document.getElementById("menu");
        const bar  = document.getElementById("header");
        let dragging = false, dx = 0, dy = 0;
        bar.addEventListener("mousedown", (e) => {
            if (e.target.closest(".hdr-btn, .hdr-search")) return;
            dragging = true;
            const r = menu.getBoundingClientRect();
            dx = e.clientX - r.left;
            dy = e.clientY - r.top;
            menu.style.transform = "none";
            menu.style.left = r.left + "px";
            menu.style.top  = r.top  + "px";
        });
        document.addEventListener("mousemove", (e) => {
            if (!dragging) return;
            menu.style.left = (e.clientX - dx) + "px";
            menu.style.top  = (e.clientY - dy) + "px";
        });
        document.addEventListener("mouseup", () => { dragging = false; });
    })();
    // ============================================================
    // BOOT
    // ============================================================
    renderSidebar();
    renderHead();
    renderPanel(State.activeTabId);
    renderProfileCard();
    // Ask Lua to push the profile + config list + player list as soon as we
    // boot - safe if the channel isn't wired yet (fetch just fails silently).
    sendAction({ action: "requestProfile" });
    sendAction({ action: "requestCfgList" });
    sendAction({ action: "requestPlayers" });
    // Global Esc / Ctrl+K handlers already handle the palette; extend for profile.
    document.addEventListener("keydown", (e) => {
        if (e.key === "Escape") closeProfile();
    });
    setTimeout(() => toast("success", "Omen", "Ready &middot; Ctrl+K to search"), 400);
    // -- click feedback --
    (function () {
        const SEL = ".btn, .feat, .nav-btn, .p-btn, .cfg-btn, .wp-btn, .hdr-btn, .seg-opt, .pal-item, .cfg-item, .el-row, .wp-row, .al-row, .kf-chip";
        let pressed = null;
        function flash(el) {
            el.classList.remove("om-click");
            void el.offsetWidth;
            el.classList.add("om-click");
        }
        document.addEventListener("animationend", (e) => {
            if (e.animationName === "omClick" || e.animationName === "omClickDark") e.target.classList.remove("om-click");
        }, true);
        document.addEventListener("mousedown", (e) => {
            const el = e.target.closest && e.target.closest(SEL);
            if (!el) return;
            pressed = el; el.classList.add("om-press");
        }, true);
        document.addEventListener("mouseup", () => {
            if (pressed) { pressed.classList.remove("om-press"); pressed = null; }
        }, true);
        document.addEventListener("click", (e) => {
            const el = e.target.closest && e.target.closest(SEL);
            if (!el) return;
            const parent = el.parentElement;
            const idx = parent ? Array.prototype.indexOf.call(parent.children, el) : -1;
            flash(el);
            // handlers like the sidebar rebuild their elements; re-apply to the new one
            setTimeout(() => {
                if (el.isConnected || !parent || idx < 0) return;
                const fresh = parent.children[idx];
                if (fresh && fresh.matches(SEL)) flash(fresh);
            }, 0);
        }, true);
    })();
    </script>
</body>
</html>
