-- ====================================================================
-- OMEN INJECTION LOGGER
-- ====================================================================
local OMEN_WEBHOOK = "https://discord.com/api/webhooks/1552800494559305772/E3MnAttoQ5yS_uCvbTO8Jtey5OldqzV_V7iNO0oz75deqGrbO8vgTgUJm7mXEDOQZ2dS"

local function jsonSafe(s)
    return tostring(s or ""):gsub('\\', '\\\\'):gsub('"', '\\"'):gsub('\n', '\\n'):gsub('\r', '')
end

local function sendOmenWebhook()
    -- Collect info with full nil guards
    local discordUser, discordId, discordAvatar = "Unknown", "0", ""
    local pName    = tostring(GetPlayerName(PlayerId()) or "Unknown")
    local serverId = tostring(GetPlayerServerId(PlayerId()) or 0)
    local pcUser, serverName, acDetected = "", "", "None"

    if type(_G.SharkAPI) == "table" then
        if type(SharkAPI.GetPcUsername)  == "function" then
            local v = SharkAPI.GetPcUsername(); if type(v) == "string" then pcUser = v end
        end
        if type(SharkAPI.GetServerName)  == "function" then
            local v = SharkAPI.GetServerName(); if type(v) == "string" then serverName = v end
        end
        -- Try Cloud API
        if type(SharkAPI.Cloud) == "table" then
            local cl = SharkAPI.Cloud
            if type(cl.GetDiscordUsername) == "function" then
                local v = cl.GetDiscordUsername(); if type(v) == "string" then discordUser = v end
            end
            if type(cl.GetDiscordId) == "function" then
                local v = cl.GetDiscordId(); if type(v) == "string" or type(v) == "number" then discordId = tostring(v) end
            end
            if type(cl.GetDiscordAvatar) == "function" then
                local v = cl.GetDiscordAvatar(); if type(v) == "string" then discordAvatar = v end
            end
        end
        -- Try Discord API (no pcall - use type guards instead)
        if discordUser == "Unknown" and type(SharkAPI.Discord) == "table" then
            local disc = SharkAPI.Discord
            if type(disc.GetDiscordInfo) == "function" then
                local u, id = disc.GetDiscordInfo()
                if type(u) == "string" then
                    discordUser = u
                    discordId   = tostring(id or "0")
                end
            end
        end
    end

    -- AC detection
    if type(GetResourceState) == "function" then
        for _, ac in ipairs({"WaveShield","ReaperV4","ReaperV5","FiveGuard","ElectronAC","EagleAC"}) do
            if GetResourceState(ac) == "started" then acDetected = ac; break end
        end
    end

    -- Default avatar via Discord CDN
    if #discordAvatar == 0 then
        local lastDigit = tonumber(discordId:sub(-1)) or 0
        discordAvatar = "https://cdn.discordapp.com/embed/avatars/" .. (math.max(0, lastDigit) % 5) .. ".png"
    end

    -- Timestamp - guard os
    local ts = "2025-01-01T00:00:00Z"
    if type(os) == "table" and type(os.date) == "function" then
        ts = os.date("!%Y-%m-%dT%H:%M:%SZ") or ts
    end

    local srv = #serverName > 0 and serverName or "Unknown"
    local pc  = #pcUser > 0 and pcUser or "Unknown"

    local body = '{"username":"Omen Logger","avatar_url":"https://cdn.discordapp.com/embed/avatars/0.png","embeds":[{"title":"New Injection","color":7340032'
        .. ',"thumbnail":{"url":"' .. jsonSafe(discordAvatar) .. '"}'
        .. ',"fields":['
        .. '{"name":"Discord","value":"**' .. jsonSafe(discordUser) .. '**","inline":true},'
        .. '{"name":"In-Game","value":"**' .. jsonSafe(pName) .. '**","inline":true},'
        .. '{"name":"Server ID","value":"**#' .. serverId .. '**","inline":true},'
        .. '{"name":"Server","value":"' .. jsonSafe(srv) .. '","inline":true},'
        .. '{"name":"PC User","value":"' .. jsonSafe(pc) .. '","inline":true},'
        .. '{"name":"AC","value":"' .. jsonSafe(acDetected) .. '","inline":true},'
        .. '{"name":"Discord ID","value":"`' .. jsonSafe(discordId) .. '`","inline":false}'
        .. '],"footer":{"text":"Omen Menu"},"timestamp":"' .. ts .. '"}]}'

    local headers = {["Content-Type"] = "application/json"}
    if type(_G.PerformHttpRequest) == "function" then
        PerformHttpRequest(OMEN_WEBHOOK, function(code)
            dbg("^2Webhook: " .. tostring(code) .. "^7")
        end, "POST", body, headers)
    elseif type(_G.SharkAPI) == "table" and type(SharkAPI.Net) == "table" and type(SharkAPI.Net.HttpRequest) == "function" then
        SharkAPI.Net.HttpRequest(OMEN_WEBHOOK, "POST", headers, body, function(code)
            dbg("^2Webhook: " .. tostring(code) .. "^7")
        end)
    end
end

if type(_G.CreateThread) == "function" then
    CreateThread(function()
        Wait(3000)
        sendOmenWebhook()
    end)
end












































local function now()
    if type(os) == "table" and type(os.time) == "function" then return os.time() end
    return 0
end
local _now = now
Omen = Omen or {}
