local KEY_VK = {
    ["CAPS"]=0x14, ["CapsLock"]=0x14,
    ["F1"]=0x70,["F2"]=0x71,["F3"]=0x72,["F4"]=0x73,["F5"]=0x74,["F6"]=0x75,
    ["F7"]=0x76,["F8"]=0x77,["F9"]=0x78,["F10"]=0x79,["F11"]=0x7A,["F12"]=0x7B,
    ["INSERT"]=0x2D,["Insert"]=0x2D,["HOME"]=0x24,["Home"]=0x24,["END"]=0x23,["End"]=0x23,
    ["PAGEUP"]=0x21,["PageUp"]=0x21,["PAGEDOWN"]=0x22,["PageDown"]=0x22,
    ["DELETE"]=0x2E,["Delete"]=0x2E,["BACKSPACE"]=0x08,["Backspace"]=0x08,
    ["TAB"]=0x09,["Tab"]=0x09,[" "]=0x20,["ENTER"]=0x0D,["Enter"]=0x0D,
    ["ARROWUP"]=0x26,["ArrowUp"]=0x26,["ARROWDOWN"]=0x28,["ArrowDown"]=0x28,
    ["ARROWLEFT"]=0x25,["ArrowLeft"]=0x25,["ARROWRIGHT"]=0x27,["ArrowRight"]=0x27,
    ["ESCAPE"]=0x1B,["Escape"]=0x1B,
}
local function keyToVk(v)
    if type(v) == "number" then return v end
    if type(v) ~= "string" or v == "" then return 0 end
    if KEY_VK[v] then return KEY_VK[v] end
    if #v == 1 then
        local u = v:upper()
        local b = u:byte(1)
        if b >= 0x30 and b <= 0x39 then return b end
        if b >= 0x41 and b <= 0x5A then return b end
    end
    return tonumber(v) or 0
end
