Omen.feed = feed
local function has(name)
    return type(_G.SharkAPI) == "table" and _G.SharkAPI[name] ~= nil
end
local function call(fn, ...)
    if type(fn) ~= "function" then return nil end
    return fn(...)
end
local function daysBetween(dateIso)
    if type(dateIso) ~= "string" or dateIso == "" then return nil end
    if type(os) ~= "table" or type(os.time) ~= "function" then return nil end
    local y, mo, d = dateIso:match("(%d%d%d%d)%-(%d%d)%-(%d%d)")
    if not y then return nil end
    local expiry = os.time({ year=tonumber(y), month=tonumber(mo), day=tonumber(d), hour=0 })
    if type(expiry) ~= "number" then return nil end
    local n = os.time()
    if type(n) ~= "number" then return nil end
    return math.floor((expiry - n) / 86400)
end
local function tierLabel(sub)
    if sub == nil or sub == "" or sub == "unknown" then
        return "Lifetime", nil
    end
    local d = daysBetween(sub)
    if not d then return sub, nil end
    if d < 0 then return "Expired", d end
    if d >= 365 then return "Lifetime", d end
    return d .. " day" .. (d == 1 and "" or "s") .. " left", d
end
local function checkBlacklist()
    if not has("Net") or type(SharkAPI.Net.GetCurrentServerCode) ~= "function" then
        return true
    end
    local code = SharkAPI.Net.GetCurrentServerCode() or ""
    for _, entry in ipairs(SERVER_BLACKLIST) do
        if code:find(entry, 1, true) then
            if has("QuitGame") then
                SharkAPI.QuitGame("Server not supported")
            end
            return false
        end
    end
    return true
end
local function fetchDiscord()
    local d = { ok = false, username = "", id = "", avatarUrl = "", avatarType = "" }
    local SK = _G.SharkAPI
    if type(SK) ~= "table" then return d end

    -- Path 1: SharkAPI.Cloud (Macho/Shadow ecosystem)
    local cl = type(SK.Cloud) == "table" and SK.Cloud
    if cl then
        if type(cl.GetDiscordId)        == "function" then d.id        = tostring(cl.GetDiscordId()        or "") end
        if type(cl.GetDiscordUsername)  == "function" then d.username  = tostring(cl.GetDiscordUsername()  or "") end
        if type(cl.GetDiscordAvatar)    == "function" then d.avatarUrl = tostring(cl.GetDiscordAvatar()    or "") end
        if type(cl.GetAvatarUrl)        == "function" and d.id ~= "" then
            local ok, url = call(cl.GetAvatarUrl, d.id)
            if ok and url and d.avatarUrl == "" then d.avatarUrl = tostring(url) end
        end
        if d.id ~= "" then d.ok = true end
    end

    -- Path 2: SharkAPI.Discord (standalone, needs Discord open)
    if not d.ok then
        local disc = type(SK.Discord) == "table" and SK.Discord
        if disc then
            local ok, u, id
            for _, fn in ipairs({ disc.GetDiscordInfo, disc.GetDiscordCanaryInfo, disc.GetDiscordPTBInfo }) do
                if type(fn) == "function" then
                    ok, u, id = call(fn)
                    if ok and u then break end
                end
            end
            if ok and u then
                d.ok, d.username, d.id = true, tostring(u), tostring(id or "")
                -- Try to get avatar URL
                for _, fn in ipairs({ disc.GetAvatarUrl, disc.GetDiscordAvatarUrl }) do
                    if type(fn) == "function" then
                        local okA, url = call(fn, d.id)
                        if okA and url then d.avatarUrl = tostring(url); break end
                    end
                end
                -- Fallback: construct CDN URL if we have the ID
                if d.avatarUrl == "" and d.id ~= "" then
                    -- Avatar hash via Discord API isn't available client-side easily,
                    -- but build a default avatar URL (color-based, always works)
                    local disc_color = tonumber(d.id:sub(-1)) or 0
                    d.avatarUrl = "https://cdn.discordapp.com/embed/avatars/" .. (disc_color % 5) .. ".png"
                end
            end
        end
    end
    dbg("discord: ok=" .. tostring(d.ok) .. " user=" .. d.username .. " avatar=" .. (d.avatarUrl ~= "" and "yes" or "no"))
    return d
end
local function fetchServer()
    local s = { name = "", icon = "", players = 0, maxPlayers = 0, code = "", endpoint = "" }
    if type(_G.SharkAPI) ~= "table" then return s end
    -- Server name
    if type(SharkAPI.GetServerName) == "function" then
        s.name = tostring(SharkAPI.GetServerName() or "")
    end
    -- Server info + endpoint (try every known field)
    if type(SharkAPI.GetServerInfo) == "function" then
        local info = SharkAPI.GetServerInfo()
        if type(info) == "table" then
            s.players    = info.players    or 0
            s.maxPlayers = info.maxPlayers or 0
            local ep = info.endpoint or info.ip or info.address or info.connect
                    or info.host or info.server or info.url or ""
            s.endpoint = tostring(ep)
        end
    end
    -- Try Cloud API for endpoint
    if #s.endpoint == 0 and type(SharkAPI.Cloud) == "table" then
        local cl = SharkAPI.Cloud
        for _, fn in ipairs({"GetServerEndpoint","GetServerIP","GetServerAddress","GetCurrentServerEndpoint"}) do
            if type(cl[fn]) == "function" then
                local v = cl[fn]()
                if type(v) == "string" and #v > 0 then s.endpoint = v; break end
            end
        end
    end
    -- FiveM built-in fallback (deprecated but may still work on some servers)
    if #s.endpoint == 0 then
        if type(_G.GetCurrentServerEndpoint) == "function" then
            local v = GetCurrentServerEndpoint()
            if type(v) == "string" and #v > 0 then s.endpoint = v end
        end
    end
    -- Build connect string
    if #s.endpoint > 0 then
        s.code = "connect " .. s.endpoint
    end
    -- Icon
    if type(SharkAPI.Net) == "table" and type(SharkAPI.Net.GetCurrentServerIconUrl) == "function" then
        s.icon = tostring(SharkAPI.Net.GetCurrentServerIconUrl() or "")
    end
    return s
end
local function buildProfile()
    local user, sub, pc, lang = "", "", "", ""
    if has("GetUsername")            then user = tostring(SharkAPI.GetUsername() or "") end
    if has("GetSubscription")        then sub  = tostring(SharkAPI.GetSubscription() or "") end
    if has("GetPcUsername")          then pc   = tostring(SharkAPI.GetPcUsername() or "") end
    if has("GetUserDefaultLanguage") then lang = tostring(SharkAPI.GetUserDefaultLanguage() or "") end
    local tierText, daysLeft = tierLabel(sub)
    local discord = fetchDiscord()
    local server  = fetchServer()
    local sessionSecs = 0
    local n = now()
    if n > 0 and Omen.SessionStart and Omen.SessionStart > 0 then
        sessionSecs = n - Omen.SessionStart
    end
    local ac = "None"
    local acCandidates = {
        { "WaveShield",   "WaveShield" },
        { "ReaperV4",     "Reaper V4" },
        { "ReaperV5",     "Reaper V5" },
        { "ReaperV6",     "Reaper V6" },
        { "ElectronAC",   "Electron" },
        { "EagleAC",      "Eagle" },
        { "WardenAC",     "Warden" },
        { "FeloxAC",      "Felox" },
        { "FiveGuard",    "FiveGuard" },
    }
    if type(_G.GetResourceState) == "function" then
        for _, c in ipairs(acCandidates) do
            if GetResourceState and GetResourceState(c[1]) == "started" then ac = c[2]; break end
        end
    end
    Omen.Profile = {
        user         = user,
        sub          = sub,
        subTier      = tierText,
        subDays      = daysLeft,
        pcUser       = pc,
        lang         = lang,
        discord      = discord,
        server       = server,
        ac           = ac,
        version      = Omen.Version,
        sessionStart = Omen.SessionStart,
        sessionSecs  = sessionSecs,
    }
    return Omen.Profile
end
local MAX_DUI_BYTES = 6 * 1024
local function measureSize(v)
    local function walk(x, depth)
        depth = depth or 0
        if depth > 12 then return 0 end
        local t = type(x)
        if t == "string" then return #x + 3 end
        if t == "number" or t == "boolean" then return 14 end
        if t == "table" then
            local n = 6
            for k, vv in pairs(x) do
                n = n + walk(k, depth + 1) + walk(vv, depth + 1) + 6
                if n > MAX_DUI_BYTES * 8 then return n end
            end
            return math.floor(n * 1.6)
        end
        return 10
    end
    return walk(v)
end
local ARRAY_ACTIONS = {
    applyPlayers        = "players",
    applyEventLog       = "events",
    applyWaypoints      = "waypoints",
    applyCustomWeapons  = "weapons",
    applyAdmins         = "admins",
    applyCfgList        = "configs",
}
local function sendToUi(payload)
    if not Omen.Dui or not Omen.__duiReady then return end
    if not has("Nui") or type(SharkAPI.Nui.SendDuiMessage) ~= "function" then return end
    if type(payload) ~= "table" then return end
    local size = measureSize(payload)
    if size <= MAX_DUI_BYTES then
        SharkAPI.Nui.SendDuiMessage(Omen.Dui, payload)
        return
    end
    local action = payload.action
    local arrKey = ARRAY_ACTIONS[action]
    if arrKey and type(payload[arrKey]) == "table" and #payload[arrKey] > 1 then
        local arr   = payload[arrKey]
        local total = #arr
        -- Pack sequentially into as many chunks as needed. Each chunk is filled
        -- until it nears MAX_DUI_BYTES, then flushed. Chunks are numbered
        -- 1..N flat (NOT recursively) so the DUI can reassemble them in order.
        local chunks = {}
        local cur = {}
        local curBytes = 200  -- rough envelope overhead per message
        for i = 1, total do
            local item = arr[i]
            local ib = measureSize(item) + 4
            if #cur > 0 and (curBytes + ib) > MAX_DUI_BYTES then
                chunks[#chunks+1] = cur
                cur = {}
                curBytes = 200
            end
            cur[#cur+1] = item
            curBytes = curBytes + ib
        end
        if #cur > 0 then chunks[#chunks+1] = cur end
        local n = #chunks
        for idx = 1, n do
            local msg = { action = action, [arrKey] = chunks[idx], chunk = idx, chunks = n }
            if idx == n then msg.blocked = payload.blocked end
            SharkAPI.Nui.SendDuiMessage(Omen.Dui, msg)
        end
        return
    end
    if type(print) == "function" then
    end
end
Omen.send = sendToUi
local function pushProfile()
    -- re-assert menu visibility ONCE on first push (bridge link = page ready). Doing it
    -- on every 30s refresh re-applied the transform and caused a visible twitch.
    if not Omen.__visibilityAsserted and Omen.Dui and Omen.__duiReady and type(Omen.send) == "function" then
        Omen.__visibilityAsserted = true
        Omen.send({ action = "setVisible", v = Omen.__menuVisible ~= false })
    end
    if Omen.Profile then
        local disc = Omen.Profile.discord
        dbg(("pushProfile: user=%s avatar=%s"):format(
            tostring(Omen.Profile.user or ""),
            disc and disc.avatarUrl ~= "" and "YES" or "NO"))
    end
    sendToUi({ action = "applyProfile", profile = Omen.Profile })
end
local function toast(severity, title, message)
    if Omen.State.notify_on == false then return end
    sendToUi({ action = "toast", severity = severity or "info", title = title or "Omen", message = message or "" })
    if type(Omen.webhookLog) == "function" then
        Omen.webhookLog(severity, title, message)
    end
end
Omen.toast = toast
local function dispatch(data)
    if type(data) ~= "table" then return end
    local action = data.action or data.t
    local id     = data.id
    local v      = data.v
    if action == "tog" or action == "toggle" then
        local newState = (v == true)
        -- Time-based dup guard: same id firing within 100ms is a double-click, ignore
        -- the extra. Never gets stuck (purely time), so toggles stay responsive.
        Omen.__togTime = Omen.__togTime or {}
        local nowT = GetGameTimer()
        -- Hook-heavy features get a longer cooldown + a GLOBAL hook lock so rapid
        -- toggling across different hook features can't thrash adhesive.dll.
        local HOOKY = { godmode=1, bubblemode=1, bubbleV2=1, noclip=1, megaweapon=1, superpunch=1, antiStrip=1, fullbypass=1, antiscan=1, reaperv4_full=1, reaperv4_deep=1, reaperv5_apply=1 }
        local perGuard = HOOKY[id] and 450 or 200
        if Omen.__togTime[id] and (nowT - Omen.__togTime[id]) < perGuard then return end
        if HOOKY[id] then
            if Omen.__hookLock and (nowT - Omen.__hookLock) < 350 then return end
            Omen.__hookLock = nowT
        end
        Omen.__togTime[id] = nowT
        Omen.State[id] = newState
        local feat = Omen.Features[id]
        if feat then
            if v and feat.toggle_on   then call(feat.toggle_on)  end
            if not v and feat.toggle_off then call(feat.toggle_off) end
        end
    elseif action == "btn" or action == "click" then
        local feat = Omen.Features[id]
        if feat and feat.click then call(feat.click, v) end
    elseif action == "sld" or action == "slide" then
        Omen.State[id] = tonumber(v) or 0
        local feat = Omen.Features[id]
        if feat and feat.slide then call(feat.slide, Omen.State[id]) end
    elseif action == "dd" or action == "dropdown" then
        Omen.State[id] = v
        local feat = Omen.Features[id]
        if feat and feat.dropdown then call(feat.dropdown, v) end
    elseif action == "inp" or action == "input" then
        Omen.State[id] = v
        local feat = Omen.Features[id]
        if feat and feat.input then call(feat.input, v) end
    elseif action == "seg" then
        Omen.State[id] = v
        local feat = Omen.Features[id]
        if feat and feat.seg then call(feat.seg, v) end
    elseif action == "bind" then
        local vk = keyToVk(v)
        Omen.Bindings[id] = vk
        if id == "open_key" then Omen.Bindings.__openKey = vk
        elseif id == "panic_key" then Omen.Bindings.__panicKey = vk end
        Omen.__bindNames = Omen.__bindNames or {}
        Omen.__bindNames[id] = v
        if cloudSet and jsonEnc then cloudSet("omen_binds", jsonEnc(Omen.__bindNames)) end
    elseif action == "playerSelect" then
        Omen.State.__selectedSid = tonumber(data.serverId) or 0
    elseif action == "inpFocus" then
        Omen.__inputFocused = (v == true or v == "true")
    elseif action == "clipSet" then
        -- Ctrl+C / Ctrl+X from a menu input: text arrives hex-encoded
        local hex = tostring(data.h or "")
        local txt = hex:gsub("%x%x", function(c) return string.char(tonumber(c, 16)) end)
        if #txt > 0 then
            Omen.__userClip = txt
            if has("SetClipboardText") then SharkAPI.SetClipboardText(txt) end
        end
    elseif action == "bindMode" then
        Omen.__bindMode = (v == true or v == "true")
    elseif action == "duiDims" then
        local dw = tonumber(data.w) or 0
        local dh = tonumber(data.h) or 0
        if dw > 0 and dh > 0 then Omen.__duiW = dw; Omen.__duiH = dh end
    elseif action == "requestProfile" then
        buildProfile()
        pushProfile()
    elseif action == "requestServer" then
        Omen.Profile.server = fetchServer()
        pushProfile()
    elseif action == "openUrl" and type(data.url) == "string" and has("OpenURL") then
        SharkAPI.OpenURL(data.url)
    elseif action == "copyDiscord" and Omen.Profile.discord and Omen.Profile.discord.id ~= "" then
        if has("SetClipboardText") then
            SharkAPI.SetClipboardText(Omen.Profile.discord.id)
            toast("success", "Discord", "ID copied")
        end
    elseif action == "requestCfgList" then
        if type(Omen.pushCfgList) == "function" then Omen.pushCfgList() end
    elseif action == "requestPlayers" then
        if type(Omen.pushPlayers) == "function" then Omen.pushPlayers() end
    elseif action == "requestEventLog" then
        if type(Omen.pushEventLog) == "function" then Omen.pushEventLog() end
    elseif action == "eventBlock" then
        if type(Omen.eventBlock) == "function" then Omen.eventBlock(data.event, data.block == true) end
    elseif action == "eventLogClear" then
        if type(Omen.eventLogClear) == "function" then Omen.eventLogClear() end
    end
end
Omen.dispatch = dispatch
local function duiSend(payload)
    if not Omen.Dui or not Omen.__duiReady then return end
    if type(SharkAPI.Nui) ~= "table" or type(SharkAPI.Nui.SendDuiMessage) ~= "function" then return end
    SharkAPI.Nui.SendDuiMessage(Omen.Dui, payload)
end
-- Modifier state tracked from OnKeyDown/OnKeyUp (set in installKeybindLoop). More reliable
-- than polling IsKeyPressed at the moment the next key arrives.
Omen.__mods = Omen.__mods or {}
local function osKeyDown(vk)
    if Omen.__mods[vk] then return true end
    if type(SharkAPI.IsKeyPressed) ~= "function" then return false end
    local r = SharkAPI.IsKeyPressed(vk)
    return r == true or r == 1
end
-- Shadow 1:1 cursor: delta accumulation on controls 1 (LR) + 2 (UD)
local _curX, _curY   = 0.0, 0.0
local _curW, _curH   = 1920, 1080
local _curSens       = 2.0     -- Shadow default
local _curMult       = 80      -- tuned down from Shadow's 80 - less overshoot
local _curDead       = 0.0005  -- deadzone: ignore only pure noise, catch real movement
local _cursLastX, _cursLastY = -1, -1
-- Use ExecuteJS (like Shadow's MachoExecuteDuiScript) for zero-latency cursor
-- Falls back to SendDuiMessage if unavailable

-- Pick up actual screen resolution every 2s (1440p / 4K support)
CreateThread(function()
    while true do
        local w, h = GetActiveScreenResolution()
        if w and w > 0 then _curW = w end
        if h and h > 0 then _curH = h end
        Wait(2000)
    end
end)

local function setMenuVisible(v)
    Omen.__menuVisible = (v == true)
    if Omen.__menuVisible then
        -- Reset cursor to screen center on every open
        _curX = _curW / 2
        _curY = _curH / 2
        _cursLastX = -1
        _cursLastY = -1
    end
    duiSend({ action = "setVisible", v = Omen.__menuVisible })
    -- Force via ExecuteJS too - bypasses the message queue so show/hide is reliable
    if type(SharkAPI.ExecuteJS) == "function" and Omen.Dui then
        if Omen.__menuVisible then
            SharkAPI.ExecuteJS(Omen.Dui, "var m=document.getElementById('menu');if(m){m.style.display='grid';m.style.opacity='1';m.style.visibility='visible';m.style.pointerEvents='all';m.style.left='50%';m.style.top='50%';m.style.transformOrigin='';m.style.transform='translate(-50%,-50%)';}")
        else
            SharkAPI.ExecuteJS(Omen.Dui, "var m=document.getElementById('menu');if(m){m.style.display='none';}")
        end
    end
    if Omen.__menuVisible then
        -- Refresh screen res NOW so center uses the real resolution (not stale 1920)
        if type(GetActiveScreenResolution) == "function" then
            local w, h = GetActiveScreenResolution()
            if w and w > 0 then _curW = w end
            if h and h > 0 then _curH = h end
        end
        -- Shadow 1:1: center cursor on open, show #cursor, push position
        local cx, cy = math.floor(_curW / 2), math.floor(_curH / 2)
        _curX, _curY = cx, cy
        _cursLastX, _cursLastY = cx, cy
        duiSend({ action = "curShow", v = true, x = math.floor(_curW/2), y = math.floor(_curH/2) })
    else
        duiSend({ action = "curShow", v = false })
    end
    dbg("menu " .. (Omen.__menuVisible and "shown" or "hidden"))
end
Omen.setMenuVisible = setMenuVisible
local seenSeq, seenOrder = {}, {}
local QUIET = { requestPlayers = true, requestServer = true }
local function routeDispatch(payload)
    if type(payload) ~= "table" then return end
    local key = payload.__sid and payload.__seq and (tostring(payload.__sid) .. ":" .. tostring(payload.__seq))
    if key then
        if seenSeq[key] then return end
        seenSeq[key] = true
        seenOrder[#seenOrder+1] = key
        if #seenOrder > 256 then seenSeq[table.remove(seenOrder, 1)] = nil end
    end
    local action = payload.action or payload.t
    if action == "ping" then
        if not Omen.__jsLinkOk then
            Omen.__jsLinkOk = true
            dbg("JS -> Lua link OK via " .. tostring(payload.__via or "?"))
            -- Push profile immediately
            if type(Omen.pushProfile) == "function" then Omen.pushProfile() end
        end
        duiSend({ action = "pong", via = payload.__via })
        return
    end
    if action == "hideMenu" then setMenuVisible(false); return end
    if not QUIET[action] then
        dbg(("recv %s %s %s"):format(tostring(action), tostring(payload.id or ""), tostring(payload.v == nil and "" or payload.v)))
    end
    local fn = (type(Omen.dispatch) == "function") and Omen.dispatch or dispatch
    return fn(payload)
end
if type(RegisterNUICallback) == "function" then
    RegisterNUICallback("action", function(payload, cb)
        routeDispatch(payload)
        cb({ ok = true })
    end)
    RegisterNUICallback("omen_action", function(payload, cb)
        routeDispatch(payload)
        cb({ ok = true })
    end)
end
local function pickBridgeResource()
    if type(SharkAPI.GetLoadedResources) ~= "function" then return nil end
    local list = SharkAPI.GetLoadedResources() or {}
    if #list == 0 then return nil end
    local prefer = { "chat", "spawnmanager", "sessionmanager", "mapmanager", "basic-gamemode" }
    local avail = {}
    for _, r in ipairs(list) do avail[r] = true end
    for _, name in ipairs(prefer) do if avail[name] then return name end end
    return list[1]
end
local BRIDGE_SRC = [[if not _G.__omenBridgeInstalled then _G.__omenBridgeInstalled = true RegisterNUICallback("omen_action", function(payload, cb) TriggerEvent("__omen:action", payload) cb({ ok = true }) end) end]]
local function installBridge()
    -- Bridge is merged into keybindLoop's OnKeyDown - only one listener needed
    dbg("bridge: merged into keybind OnKeyDown")
end
function Omen.register(id, def)
    if type(id) ~= "string" or type(def) ~= "table" then return end
    Omen.Features[id] = def
end
local MODIFIERS = { [0x10]=true, [0x11]=true, [0x12]=true, [0xA0]=true, [0xA1]=true, [0xA2]=true, [0xA3]=true, [0xA4]=true, [0xA5]=true }
local _keyLast = {}
local function forwardKey(vk)
    if vk <= 0x06 or MODIFIERS[vk] then return end
    -- Light dedupe: ignore same vk within 40ms (double-fire/repeat), never drop a
    -- fresh press so bind capture always works.
    local t = (type(GetGameTimer) == "function") and GetGameTimer() or 0
    if _keyLast[vk] and (t - _keyLast[vk]) < 40 then return end
    _keyLast[vk] = t
    local shift = osKeyDown(0x10) or osKeyDown(0xA0) or osKeyDown(0xA1)
    local ctrl  = osKeyDown(0x11) or osKeyDown(0xA2) or osKeyDown(0xA3)
    -- Fallback when IsKeyPressed is missing/unreliable: game controls still report while
    -- disabled (21 = Sprint/LShift, 36 = Duck/LCtrl).
    if not shift and type(IsDisabledControlPressed) == "function" then shift = IsDisabledControlPressed(0, 21) == true end
    if not ctrl  and type(IsDisabledControlPressed) == "function" then ctrl  = IsDisabledControlPressed(0, 36) == true end
    if ctrl and vk == 0x56 and type(SharkAPI.GetClipboardText) == "function" then
        local tx = SharkAPI.GetClipboardText()
        -- The DUI action bridge may still be sitting in the clipboard; paste the user's text instead.
        if type(tx) == "string" and tx:sub(1, 5) == "OMEN:" then tx = Omen.__userClip end
        if type(tx) == "string" and #tx > 0 then duiSend({ action = "paste", text = tx:sub(1, 512) }) end
        return
    end
    duiSend({ action = "key", vk = vk, s = shift, c = ctrl })
end
-- JSON mini-parser for VK bridge dispatch
local function parseOmenAction(s)
    if type(s) ~= "string" or #s == 0 then return nil end
    s = s:match("^%s*(.-)%s*$")
    if s:sub(1,1) ~= "{" then return nil end
    local obj = {}
    -- Extract action/id/v/serverId fields
    for k, v in s:gmatch('"([^"]+)"%s*:%s*"([^"]+)"') do
        obj[k] = v
    end
    for k, v in s:gmatch('"([^"]+)"%s*:%s*(%-?%d+%.?%d*)') do
        if not obj[k] then obj[k] = tonumber(v) end
    end
    for k in s:gmatch('"([^"]+)"%s*:%s*true') do
        if obj[k] == nil then obj[k] = true end
    end
    for k in s:gmatch('"([^"]+)"%s*:%s*false') do
        if obj[k] == nil then obj[k] = false end
    end
    return next(obj) and obj or nil
end

-- Parse a queued bridge payload {"q":[{..},{..}]} into a list of action tables.
-- Falls back to a single action for legacy single-object payloads.
local function parseOmenQueue(json)
    local out = {}
    local arr = json:match("%[(.*)%]")
    if not arr then
        local t = parseOmenAction(json)
        if t then out[1] = t end
        return out
    end
    for obj in arr:gmatch("%b{}") do
        local t = parseOmenAction(obj)
        if t then out[#out+1] = t end
    end
    return out
end

local _omenLastId = 0
local function routeAction(t)
    if type(t) ~= "table" then return end
    local id = tonumber(t._id)
    if id then
        if id <= _omenLastId then return end   -- dedupe replayed queue / dual bridge
        _omenLastId = id
    end
    local fn = (type(Omen.dispatch) == "function") and Omen.dispatch or dispatch
    if fn then fn(t) end
end

function installKeybindLoop()
    -- Restore saved binds (open/panic keys + feature binds) from Cloud
    if cloudGet and jsonDec and keyToVk then
        local saved = cloudGet("omen_binds")
        if saved and saved ~= "" then
            local names = jsonDec(saved)
            if type(names) == "table" then
                Omen.__bindNames = names
                for id, v in pairs(names) do
                    local vk = keyToVk(v)
                    Omen.Bindings[id] = vk
                    if id == "open_key" then Omen.Bindings.__openKey = vk
                    elseif id == "panic_key" then Omen.Bindings.__panicKey = vk end
                end
            end
        end
    end
    local onKey = (type(SharkAPI.OnKeyDown) == "function" and SharkAPI.OnKeyDown)
                  or (type(SharkAPI.Input) == "table" and type(SharkAPI.Input.OnKeyDown) == "function" and SharkAPI.Input.OnKeyDown)
    if not onKey then dbg("^1OnKeyDown missing^7 - no keybinds / open key"); return end
    -- VK bridge state (merged here so only one OnKeyDown needed)
    local vkBuf, vkActive = {}, false
    local onKeyUp = (type(SharkAPI.OnKeyUp) == "function" and SharkAPI.OnKeyUp)
                    or (type(SharkAPI.Input) == "table" and type(SharkAPI.Input.OnKeyUp) == "function" and SharkAPI.Input.OnKeyUp)
    if onKeyUp then
        onKeyUp(function(vk)
            local c = tonumber(vk)
            if c and MODIFIERS[c] then
                Omen.__mods[c] = nil
                -- generic/left/right codes can arrive mixed; release the whole group
                if c == 0x10 or c == 0xA0 or c == 0xA1 then Omen.__mods[0x10], Omen.__mods[0xA0], Omen.__mods[0xA1] = nil, nil, nil end
                if c == 0x11 or c == 0xA2 or c == 0xA3 then Omen.__mods[0x11], Omen.__mods[0xA2], Omen.__mods[0xA3] = nil, nil, nil end
            end
        end)
    end
    onKey(function(vk)
        if onKeyUp and not vkActive then
            local c = tonumber(vk)
            if c and MODIFIERS[c] then Omen.__mods[c] = true end
        end
        if not Omen.Ready then return end
        -- VK bridge: decode JSON from DUI (0xE8=start, bytes, 0xE7=end)
        local code = tonumber(vk)
        if code == 0xE8 then
            vkBuf = {}; vkActive = true
            return
        end
        if code == 0xE7 and vkActive then
            vkActive = false
            local bufLen = #vkBuf
            if bufLen > 0 then
                local chars = {}
                for _, b in ipairs(vkBuf) do chars[#chars+1] = string.char(b) end
                vkBuf = {}
                local json = table.concat(chars)
                if not Omen.__jsLinkOk then
                    Omen.__jsLinkOk = true
                    duiSend({ action="pong", via="vk" })
                    if type(Omen.pushProfile) == "function" then Omen.pushProfile() end
                end
                local t = parseOmenAction(json)
                if t then
                    routeAction(t)
                end
            end
            return
        end
        if vkActive then vkBuf[#vkBuf+1] = code; return end
        -- Debug: log any key that reaches here (non-VK keys)
        -- dbg(("^5[KEY] vk=0x%X^7"):format(code))
        -- Normal keybind handling
        if Omen.__bindMode then
            if Omen.__duiReady then forwardKey(vk) end
            return
        end
        if vk == (Omen.Bindings.__openKey or 0x14) then
            setMenuVisible(not Omen.__menuVisible)
            return
        end
        if Omen.Bindings.__panicKey and vk == Omen.Bindings.__panicKey then
            dbg("panic key")
            Omen.shutdown()
            return
        end
        if Omen.__menuVisible then
            if Omen.__duiReady then forwardKey(vk) end
            return
        end
        for id, code in pairs(Omen.Bindings) do
            -- skip special entries (open/panic keys, the names table) and ensure code is
            -- a number before comparing - these were breaking feature keybinds.
            if type(code) == "number" and id ~= "open_key" and id ~= "panic_key"
               and id ~= "__openKey" and id ~= "__panicKey" and code == vk then
                local feat = Omen.Features[id]
                if feat then
                    if feat.toggle_on or feat.toggle_off then
                        local on = not (Omen.State[id] == true)
                        Omen.State[id] = on
                        if on and feat.toggle_on then call(feat.toggle_on) end
                        if not on and feat.toggle_off then call(feat.toggle_off) end
                        sendToUi({ action = "syncState", states = { [id] = on } })
                        dbg(("bind %s -> %s"):format(id, tostring(on)))
                    elseif feat.click then
                        call(feat.click)
                        dbg("bind " .. id)
                    end
                end
            end
        end
    end)
    dbg("keybinds armed (open key 0x" .. string.format("%X", Omen.Bindings.__openKey or 0x14) .. ")")
end


local function installInputPump()
    -- Generation guard: bump the token; only the newest pump thread survives.
    -- Prevents stacked pumps (from reinject / repeated calls) each sending their
    -- own curDown/curUp = the multi-click cascade.
    Omen.__pumpGen = (Omen.__pumpGen or 0) + 1
    local myGen = Omen.__pumpGen
    CreateThread(function()
        local wasDown = false
        while Omen.Ready and Omen.__pumpGen == myGen do
            if Omen.__menuVisible and Omen.__duiReady then
                if Omen.__inputFocused then
                    DisableAllControlActions(0)
                end
                -- Shadow 1:1 EXACT disable list - does NOT disable look (1/2) so
                -- GetDisabledControlNormal(0,1/2) still reports real mouse deltas.
                DisableControlAction(0, 24, true)   -- Attack
                DisableControlAction(0, 25, true)   -- Aim
                DisableControlAction(0, 47, true)   -- Weapon (G)
                DisableControlAction(0, 58, true)   -- Weapon (throw)
                DisableControlAction(0, 140, true)  -- Melee attack light
                DisableControlAction(0, 141, true)  -- Melee attack alt
                DisableControlAction(0, 142, true)  -- Melee attack 2
                DisableControlAction(0, 143, true)  -- Melee block
                DisableControlAction(0, 263, true)  -- Melee attack
                DisableControlAction(0, 264, true)  -- Melee attack 2
                DisableControlAction(0, 257, true)  -- Attack 2
                DisableControlAction(0, 73, true)   -- Weapon wheel
                DisableControlAction(0, 37, true)   -- Weapon select
                DisableControlAction(0, 44, true)   -- Cover
                DisableControlAction(0, 69, true)   -- Vehicle attack
                DisableControlAction(0, 92, true)   -- Vehicle attack 2
                DisableControlAction(0, 114, true)  -- Fly attack
                DisableControlAction(0, 331, true)  -- Phone
                DisableControlAction(0, 68, true)   -- Vehicle aim
                -- Shadow 1:1: delta accumulate, clamp to screen res (duiW/duiH)
                -- Shadow 1:1 delta read
                local dx = GetDisabledControlNormal(0, 1) * _curSens * _curMult
                local dy = GetDisabledControlNormal(0, 2) * _curSens * _curMult
                                if dx ~= 0 or dy ~= 0 then
                    _curX = math.max(0, math.min(_curW, _curX + dx))
                    _curY = math.max(0, math.min(_curH, _curY + dy))
                end
                local nx, ny = math.floor(_curX), math.floor(_curY)
                -- Throttle cursor sends: only when moved and at most ~every 8ms (~120/s cap).
                -- The old 2px/16ms gate dropped every other frame at high FPS, so the
                -- cursor and dragged menu moved in uneven steps.
                local nowCur = GetGameTimer()
                if ((not _cursLastX) or nx ~= _cursLastX or ny ~= (_cursLastY or 0))
                   and (nowCur - (_curLastSend or 0)) >= 8 then
                    _cursLastX, _cursLastY = nx, ny
                    _curLastSend = nowCur
                    duiSend({ action = "cur", x = nx, y = ny })
                end
                -- Dual click source (control OR raw LMB) for reliability. Edge-detect
                -- with a 180ms floor on curDown so a flickering control can't machine-gun
                -- presses. curUp still fires on real release (keeps slider drag working).
                local isDown = IsDisabledControlPressed(0, 24) or osKeyDown(0x01)
                if isDown and not wasDown then
                    local nowC = GetGameTimer()
                    if (nowC - (_lastClickMs or 0)) > 180 then
                        _lastClickMs = nowC
                        _clickArmed = true
                        duiSend({ action = "curDown" })
                    end
                elseif not isDown and wasDown then
                    if _clickArmed then
                        _clickArmed = false
                        duiSend({ action = "curUp" })
                    end
                end
                if type(IsDisabledControlJustPressed) == "function" then
                    if IsDisabledControlJustPressed(0, 15) then
                        duiSend({ action = "curScroll", d = -120 })
                    elseif IsDisabledControlJustPressed(0, 14) then
                        duiSend({ action = "curScroll", d = 120 })
                    end
                end
                wasDown = isDown
                Wait(0)
            else
                if wasDown then
                    duiSend({ action="mouse", x=_curX/_curW, y=_curY/_curH, b=0, w=0 })
                    wasDown = false
                end
                Wait(200)
            end
        end
    end)
    dbg("input pump running")
end
local function installRefreshLoop()
    CreateThread(function()
        Wait(4000)
        while Omen.Ready do
            buildProfile()
            pushProfile()
            Wait(30000)
        end
    end)
end
local function streamHtmlPayload()
    local payload = (Omen and Omen.__htmlPayload) or _G.__OMEN_HTML_PAYLOAD
    if type(payload) ~= "string" or #payload == 0 then return 0 end
    local CHUNK, total = 3072, #payload
    local i, n = 1, 0
    while i <= total do
        local j = math.min(i + CHUNK - 1, total)
        while j < total and j > i do
            local b = payload:byte(j + 1)
            if b >= 0x80 and b < 0xC0 then j = j - 1 else break end
        end
        SharkAPI.Nui.SendDuiMessage(Omen.Dui, { action = "htmlChunk", data = payload:sub(i, j) })
        i = j + 1
        n = n + 1
        Wait(0)
    end
    SharkAPI.Nui.SendDuiMessage(Omen.Dui, { action = "htmlDone" })
    return n
end
function Omen.shutdown()
    Omen.Ready = false
    Omen.__duiReady = false
    Omen.__menuVisible = false
    if type(SharkAPI.Drawing) == "table" and type(SharkAPI.Drawing.SetCursorActive) == "function" then
        SharkAPI.Drawing.SetCursorActive(false)
    end
    if Omen.Dui and type(SharkAPI.Nui) == "table" and type(SharkAPI.Nui.DestroyDui) == "function" then
        SharkAPI.Nui.DestroyDui(Omen.Dui)
    end
    Omen.Dui = nil
    Omen.Bindings = {}
    Omen.Features = {}
    if has("Scripting") and type(SharkAPI.Scripting.DisableAllHooks) == "function" then
        SharkAPI.Scripting.DisableAllHooks()
    end
    dbg("shutdown")
end
local function boot()
    -- Re-run guard: if a previous instance is already booted, tear it down first
    -- so we never stack input pumps / HUD threads / handlers on reinject.
    if Omen.__booted then
        Omen.Ready = false          -- signals all old threads (pump included) to exit
        Omen.__pumpGen = (Omen.__pumpGen or 0) + 1
    end
    Omen.__booted = true
    dbg("boot v" .. Omen.Version)
    if type(_G.SharkAPI) ~= "table" then dbg("^1SharkAPI missing^7 - abort"); return end
    if has("IsInjectionAvailable") and SharkAPI.IsInjectionAvailable() == false then
        dbg("^1injection unavailable^7 - abort"); return
    end
    if not checkBlacklist() then dbg("server blacklisted - abort"); return end
    local caps = {}
    for _, n in ipairs({ "Nui", "Drawing", "ExecuteJS", "Inject", "InjectSafe", "GetLoadedResources",
                         "OnKeyDown", "IsKeyPressed", "GetClipboardText", "Cloud", "SyncTree", "Scripting" }) do
        caps[#caps+1] = n .. (has(n) and "+" or "-")
    end
    dbg("api " .. table.concat(caps, " "))
    buildProfile()
    if has("Nui") and type(SharkAPI.Nui.CreateDui) == "function" then
        Omen.Dui = SharkAPI.Nui.CreateDui(DUI_URL)
    end
    Omen.Ready = true
    Omen.__menuVisible = true
    installKeybindLoop()
    installRefreshLoop()
    CreateThread(function()
        Wait(500)
        -- Only stream the embedded payload when loading the data-URI loader shell.
        -- When DUI_URL is an http host serving the full UI, the page is already complete.
        local n = 0
        if DUI_URL:sub(1, 5) == "data:" then
            n = streamHtmlPayload()
            dbg(("html streamed: %d chunks"):format(n))
            Wait(500)
        else
            -- Host load is slower (network): the page must download + parse + register
            -- its message handler before setVisible lands, so give it real time.
            dbg("html loaded from host: " .. DUI_URL)
            Wait(1200)
        end
        Omen.__duiReady = true
        -- Explicitly hide overlays at boot so they don't appear until toggled on
        sendToUi({ action = "spectatorList", show = false, players = {} })
        sendToUi({ action = "bubbleSeerList", show = false, players = {} })
        -- Send resource name to DUI via sync SendDuiMessage so NUI fetch works immediately
        local _res = GetCurrentResourceName and GetCurrentResourceName() or "monitor"
        duiSend({ action="bridgeInfo", res=_res, bridge=_res })
        Omen.__bindNames = Omen.__bindNames or {}
        if not Omen.__bindNames.open_key then Omen.__bindNames.open_key = "CAPS" end
        sendToUi({ action = "restoreBinds", binds = Omen.__bindNames })
        duiSend({ action = "duiMode", v = true })
        setMenuVisible(true)
        installInputPump()
        installBridge()
        -- POLLING BRIDGE: read window.__omenQ via ExecuteJS every frame
        -- This is the guaranteed path - doesn't depend on VK key propagation
        if has("ExecuteJS") and type(SharkAPI.ExecuteJS) == "function" then
            -- Test: does ExecuteJS return values synchronously?
            local testVal = SharkAPI.ExecuteJS(Omen.Dui, "JSON.stringify({test:42})")
            if type(_G.RegisterNuiCallback) == "function" then
                local res = GetCurrentResourceName and GetCurrentResourceName() or "monitor"
                _G.RegisterNuiCallback("omen_recv", function(data, cb)
                    if type(data) == "table" then
                        if not Omen.__jsLinkOk then
                            Omen.__jsLinkOk = true
                            duiSend({ action="pong", via="nui" })
                            if type(Omen.pushProfile) == "function" then Omen.pushProfile() end
                        end
                    end
                    if type(cb) == "function" then cb("ok") end
                end)
                -- Tell the DUI which resource to POST to
            end
            -- CLIPBOARD BRIDGE: poll GetClipboardText every 50ms
            -- Works because user click in DUI fires document.execCommand("copy") 
            if type(SharkAPI.GetClipboardText) == "function" then
                CreateThread(function()
                    local lastClip = ""
                    while Omen.Ready do
                        local clip = SharkAPI.GetClipboardText()
                        -- Remember what the user really has copied so it survives the bridge
                        if type(clip) == "string" and #clip > 0 and clip:sub(1,5) ~= "OMEN:" then
                            Omen.__userClip = clip
                        end
                        if type(clip) == "string" and #clip > 6 and clip ~= lastClip and clip:sub(1,5) == "OMEN:" then
                            lastClip = clip
                            local json = clip:sub(6)
                            local acts = parseOmenQueue(json)
                            if #acts > 0 and not Omen.__jsLinkOk then
                                Omen.__jsLinkOk = true
                                duiSend({ action="pong", via="clipboard" })
                                if type(Omen.pushProfile) == "function" then Omen.pushProfile() end
                            end
                            for _, t in ipairs(acts) do
                                routeAction(t)   -- dedupes by _id
                            end
                            -- Give the user's clipboard back (otherwise Ctrl+V outside the menu
                            -- pastes "OMEN:{...}"). Skip if JS already wrote a newer batch.
                            if type(Omen.__userClip) == "string" and #Omen.__userClip > 0
                               and type(SharkAPI.SetClipboardText) == "function"
                               and SharkAPI.GetClipboardText() == clip then
                                SharkAPI.SetClipboardText(Omen.__userClip)
                            end
                        end
                        Wait(50)
                    end
                end)
            else
            end
-- ExecuteJS is async: polling thread removed
        else
        end
        Wait(800)
        pushProfile()
        -- Push player list immediately (don't wait 1s for first refresh loop tick)
        if type(Omen.pushPlayers) == "function" then Omen.pushPlayers() end
        local user = (Omen.Profile and Omen.Profile.user ~= "" and Omen.Profile.user) or "user"
    toast("success", "Omen", "Loaded")
    end)
    if has("OnReset") then
        SharkAPI.OnReset(function() Omen.shutdown() end)
    end
    if not _G.__OMEN_BUNDLED then
        local featSrc = LoadResourceFile(GetCurrentResourceName(), "features.lua")
        if type(featSrc) == "string" and #featSrc > 0 then
            local chunk, err = load(featSrc, "@features.lua")
            if chunk then chunk() end
            if err then dbg("features.lua load error: " .. tostring(err)) end
        end
    end
end
boot()

-- -- FEATURE HANDLERS --------------------------------------------------------
local reg   = function(id, h) Omen.Features[id] = h end
local State = Omen.State
local send  = Omen.send  or function() end
local toast = Omen.toast or function() end
local SK    = _G.SharkAPI or {}
local _ft   = {}
local _ftGen = {}  -- tick table for startTick/stopTick
local function startTick(key, waitMs, fn)
    -- Generation guard: bump this key's token so any already-running thread for the
    -- same key exits, then start exactly one new thread. Prevents stacked ticks
    -- (e.g. toggle_on called more than once starting N noclip loops = the 3-on bug).
    _ftGen[key] = (_ftGen[key] or 0) + 1
    local myGen = _ftGen[key]
    _ft[key] = true
    CreateThread(function()
        while _ft[key] and _ftGen[key] == myGen do fn(); Wait(waitMs or 0) end
    end)
end
local function stopTick(key) _ft[key] = nil end

-- Ban-prevention: returns true (and toasts) if a known hard-detect AC is running.
local function acWouldBan()
    if GetResourceState("WaveShield") == "started" then
        toast("failure", "Omen", "WaveShield Found - Ban Prevented!")
        return true
    end
    return false
end
