    _ShadowBubbleMaskerInstalled = false
end

local UNARMED = GetHashKey("WEAPON_UNARMED")
-- Spoof Weapon - ported 1:1 from ShadowOld, adapted to SharkAPI.Scripting.HookNative.
-- Every callback gates on _G.spoofWeaponEnabled; install-once guard.
function EnableSpoofWeapon()
    _G.spoofWeaponEnabled = true
    if type(SharkAPI.Scripting) ~= "table" or type(SharkAPI.Scripting.HookNative) ~= "function" then return end
    if _G.__OmenSpoofHooksInstalled then return end
    _G.__OmenSpoofHooksInstalled = true
    local UNARMED = -1569615261
    local H = SharkAPI.Scripting.HookNative
    -- GetCurrentPedWeapon
    H(0x3A87E44BB9A01D54, function(ped, p2) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, UNARMED end end)
    -- GetSelectedPedWeapon
    H(0x0A6DB4965674D243, function(ped) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, UNARMED end return true end)
    -- GetBestPedWeapon
    H(0x8483E98E8B888AE2, function(ped, p1) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, UNARMED end return true end)
    -- IsPedArmed
    H(0x475768A975D5AD17, function(ped, typeFlags) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, false end return true end)
    -- HasPedGotWeapon
    H(0x8DECB02F88F428BC, function(ped, weaponHash, p2) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, false end return true end)
    -- GetAmmoInClip
    H(0x2E1202248937775C, function(ped, weaponHash) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, false, 0 end return true end)
    -- HudWeaponWheelGetSelectedHash
    H(0xA48931185F0536FE, function() return false, UNARMED end)
    -- GetLockonDistanceOfCurrentPedWeapon
    H(0x840F03E9041E2C9C, function(ped) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, 0.0 end return true end)
    -- GetPedConfigFlag (flag 331)
    H(0x7EE53118C892B513, function(ped, flag, p2) if ped == PlayerPedId() and flag == 331 then return false, false end return true end)
    -- RemoveWeaponFromPed - BLOCK
    H(0x4899CB088EDF59B8, function(ped) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false end return true end)
    -- GetCurrentPedWeaponEntityIndex
    H(0x3B390A939AF0B5FC, function(ped, p1) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, 0 end return true end)
    -- IsPedWeaponReadyToShoot
    H(0xB80CA294F2F26749, function(ped) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, false end return true end)
    -- IsPedShooting
    H(0x34616828CD07F1A1, function(ped) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, false end return true end)
    -- IsPedReloading
    H(0x24B100C68C645951, function(ped) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, false end return true end)
    -- HudWeaponWheelGetSlotHash
    H(0xA13E93403F26C812, function() return false, UNARMED end)
    -- IsHudComponentActive (weapon wheel 19, icon 2, stats 20)
    H(0xBC4C9EA5391ECC0D, function(id) if id == 2 or id == 19 or id == 20 then return false, false end return true end)
    -- GetEntityPlayerIsFreeAimingAt
    H(0x2975C866E6713290, function(player) if player == PlayerId() then return false, false, 0 end return true end)
    -- GetPedParachuteState
    H(0x79CFD9827CC979B6, function() return false, 1 end)
    -- GetWeaponDamageType
    H(0x3BE0BB12D25FB305, function(weaponHash) return false, 0 end)
    -- IsPedDoingDriveby
    H(0xB2C086CC1BF8F2BF, function(ped) if _G.spoofWeaponEnabled and ped == PlayerPedId() then return false, false end return true end)
end
local _spoofHashes = {
    0x3A87E44BB9A01D54, 0x0A6DB4965674D243, 0x8483E98E8B888AE2, 0x475768A975D5AD17, 0x8DECB02F88F428BC,
    0x3B390A939AF0B5FC, 0x2E1202248937775C, 0xA48931185F0536FE, 0x840F03E9041E2C9C, 0x7EE53118C892B513,
    0x4899CB088EDF59B8, 0xB80CA294F2F26749, 0x34616828CD07F1A1, 0x24B100C68C645951, 0xA13E93403F26C812,
    0xBC4C9EA5391ECC0D, 0x2975C866E6713290, 0x79CFD9827CC979B6, 0x3BE0BB12D25FB305, 0xB2C086CC1BF8F2BF
}
function DisableSpoofWeapon()
    -- Hooks self-gate on _G.spoofWeaponEnabled now, so just flip the flag. No hook
    -- removal/re-hook = no adhesive thrash when spoof-using features toggle rapidly.
    _G.spoofWeaponEnabled = false
    if true then return end  -- (legacy removal below kept but skipped)
    -- Prefer RestoreNative: removes each hook cleanly (1 op each, no re-hook churn).
    -- Falls back to no-op re-hook only if RestoreNative isn't available.
    if type(SharkAPI.Scripting) == "table" then
        if type(SharkAPI.Scripting.RestoreNative) == "function" then
            for _, h in ipairs(_spoofHashes) do SharkAPI.Scripting.RestoreNative(h) end
            _G.__OmenSpoofHooksInstalled = false   -- fully removed, can reinstall later
        elseif type(SharkAPI.Scripting.HookNative) == "function" then
            for _, h in ipairs(_spoofHashes) do SharkAPI.Scripting.HookNative(h, function() return true end) end
        end
    end
end

-- Aimbot native hooks - ported 1:1 from ShadowOld, adapted to SharkAPI.Scripting.HookNative.
-- Gated on _G.ShadowAimbotHooks; install-once guard.
function EnableAimbotHooks()
    _G.ShadowAimbotHooks = true
    if type(SharkAPI.Scripting) ~= "table" or type(SharkAPI.Scripting.HookNative) ~= "function" then return end
    if _G.__OmenAimbotHooksInstalled then return end
    _G.__OmenAimbotHooksInstalled = true
    local H = SharkAPI.Scripting.HookNative
    H(0x68EDDA28A5976D07, function() if not _G.ShadowAimbotHooks then return true end return false, false end)
    H(0xA571D46727E2B718, function(padIndex) if not _G.ShadowAimbotHooks then return true end if padIndex == 0 then return false, false end return true end)
    H(0x1CEA6BFDF248E5D9, function(padIndex, control) if not _G.ShadowAimbotHooks then return true end if control == 1 or control == 2 then return false, true end return true end)
end
function DisableAimbotHooks()
    _G.ShadowAimbotHooks = false
end

local noclipSafe = {
    0x01FEE67DB37F59B2,  -- IsPedOnFoot
    0x9DE327631295B4C2,  -- IsPedSwimming
    0xC024869A53992F34,  -- IsPedSwimmingUnderWater
    0x53E8CB4F48BFE623,  -- IsPedClimbing
    0xCEDABC5900A0BF97,  -- IsPedJumping
}
local ReaperV4Detected = GetResourceState and (
    GetResourceState("ReaperV4") == "started" or
    GetResourceState("ReaperV5") == "started"
) or false
local WaveShieldDetected = GetResourceState and GetResourceState("WaveShield") == "started" or false

-- GLOBALS (must not be local - referenced from action dispatch)
function EnableNoclipHooks()
    -- install once ever (hooks self-gate on Omen.State.noclip), never reinstall
    if _G.__OmenNoclipInstalled then return end
    _G.__OmenNoclipInstalled = true
    if type(SharkAPI.Scripting) ~= "table" or type(SharkAPI.Scripting.HookNative) ~= "function" then return end
    -- Shadow 1:1: hook movement/state natives to return false for our ped
    -- so AC sees us as a normal pedestrian (not flying)
    for _, hash in ipairs(noclipSafe) do
        local h = hash
        SharkAPI.Scripting.HookNative(h, function(ped)
            -- gate on state so the hook can stay installed permanently (no install/
            -- remove race = no adhesive crash on fast toggle)
            if (Omen.State.noclip or Omen.State.desyncNoclip) and ped == PlayerPedId() then return false, false end
            return true
        end)
    end
    -- GetPedParachuteState -> -1 (not parachuting)
    SharkAPI.Scripting.HookNative(0xF4E73E1E0AE1B445, function(ped)
        if ped == PlayerPedId() then return false, -1 end
        return true
    end)
    -- IsPedOnVehicle -> true (we're "on vehicle", not flying)
    SharkAPI.Scripting.HookNative(0x67722AEB798E5FAB, function(ped)
        if ped == PlayerPedId() then return false, true end
        return true
    end)
    -- IsPedRagdoll -> false (WaveShield only, per Shadow)
    if GetResourceState and GetResourceState("WaveShield") == "started" then
        SharkAPI.Scripting.HookNative(0x47E4E977581C5B55, function(ped)
            if ped == PlayerPedId() then return false, false end
            return true
        end)
    end
    -- Reaper anti-teleport: spoof height-above-ground to 0 (we're "on ground")
    if ReaperV4Detected then
        SharkAPI.Scripting.HookNative(0x1DD55701034110E5, function(ent)  -- GetEntityHeightAboveGround
            if (Omen.State.noclip or Omen.State.desyncNoclip) and ent == PlayerPedId() then return false, 0.0 end
            return true
        end)
        SharkAPI.Scripting.HookNative(0x95DDE6FC8B964019, function(ent, x, y, z, atTop, inWorldCoords)  -- GetEntityHeight
            if (Omen.State.noclip or Omen.State.desyncNoclip) and ent == PlayerPedId() then
                local _, gz = GetGroundZFor_3dCoord(x, y, z, false)
                return false, gz or 0.0
            end
            return true
        end)
    end
    _G.ShadowNoclipHooks = true
end



function DisableNoclipHooks()
    -- Hooks stay installed and self-gate on Omen.State.noclip (already set false by the
    -- caller), so there is nothing to remove here. NOT calling DisableAllHooks avoids
    -- the install/remove race that crashed adhesive.dll on fast toggling.
    _G.ShadowNoclipHooks = false
end


-- Bubble Mode Masker (1:1 Shadow)
_G.__ShadowSelfConfigWrite = _G.__ShadowSelfConfigWrite or false
local _ShadowBubbleMaskerInstalled = false
local _nativeSetPedConfigFlag = SetPedConfigFlag
local function _safeSetConfigFlag(ped, flag, value)
    _G.__ShadowSelfConfigWrite = true
    _nativeSetPedConfigFlag(ped, flag, value)
    _G.__ShadowSelfConfigWrite = false
end
function EnsureBubbleModeMasker()
    if type(SharkAPI.Scripting) ~= "table" or type(SharkAPI.Scripting.HookNative) ~= "function" then return end
    if _ShadowBubbleMaskerInstalled then return end
    SharkAPI.Scripting.HookNative(0x7EE53118C892B513, function(ped, flag)  -- GetPedConfigFlag
        if ped == PlayerPedId() and flag == 423 and
           (Omen.State.bubblemode or Omen.State.bubblemodeV2) then
            return false, false
        end
        return true
    end)
    SharkAPI.Scripting.HookNative(0x1913FE4CBF41C463, function(ped, flag)  -- SetPedConfigFlag
        if ped == PlayerPedId() and flag == 423 then
            if not _G.__ShadowSelfConfigWrite then return false end
        end
        return true
    end)
    _ShadowBubbleMaskerInstalled = true
end

-- Godmode hooks (1:1 Shadow)
function EnableGodmodeHooks()
    if type(SharkAPI.Scripting) ~= "table" or type(SharkAPI.Scripting.HookNative) ~= "function" then return end
    _G.ShadowGodmodeHooks = true
    if _G.__OmenGodmodeHooksInstalled then return end
    local function IsOurPed(ped) return ped == PlayerPedId() end
    local installedAny = false
    -- WaveShield: spoof GetPedType -> 28 (civilian) + disable camera controls check
    if GetResourceState and GetResourceState("WaveShield") == "started" then
        SharkAPI.Scripting.HookNative(0xFF059E1E4C01E63C, function(ped)  -- GetPedType
            if not _G.ShadowGodmodeHooks then return true end
            if IsOurPed(ped) then return false, 28 end
            return true
        end)
        SharkAPI.Scripting.HookNative(0x7C814D2FB49F40C0, function()  -- GetAreCameraControlsDisabled
            if not _G.ShadowGodmodeHooks then return true end
            return false, true
        end)
        installedAny = true
    end
    -- Reaper: spoof entity proof checks and invincibility
    if ReaperV4Detected then
        -- Reaper-safe godmode: hook the detection getters ONLY inside the Reaper
        -- resource (HookNativeForResource) so Reaper polls see "not invincible / no
        -- proofs / can be damaged" while the game + every other resource get the REAL
        -- values. This avoids the global-hook integrity trip that was causing bans on
        -- some servers. Falls back to global HookNative if the API lacks the per-resource one.
        local rName = (GetResourceState("ReaperV5") == "started") and "ReaperV5" or "ReaperV4"
        if type(SharkAPI.Scripting.HookNativeForResource) == "function" then
            SharkAPI.Scripting.HookNativeForResource(0xB721981B2B939E07, false, rName)   -- GetPlayerInvincible -> false
            SharkAPI.Scripting.HookNativeForResource(0xD95CC5D2AB15A09F, true,  rName)   -- GetEntityCanBeDamaged -> true
            -- GetEntityProofs can't be a single value (multi-return), keep it global-gated
            SharkAPI.Scripting.HookNative(0xBE8CD9BE829BBEBF, function()  -- GetEntityProofs
                if not _G.ShadowGodmodeHooks then return true end
                return false, 1, 0, 0, 0, 0, 0, 0, 0
            end)
        else
            SharkAPI.Scripting.HookNative(0xBE8CD9BE829BBEBF, function()  -- GetEntityProofs
                if not _G.ShadowGodmodeHooks then return true end
                return false, 1, 0, 0, 0, 0, 0, 0, 0
            end)
            SharkAPI.Scripting.HookNative(0xD95CC5D2AB15A09F, function()  -- GetEntityCanBeDamaged
                if not _G.ShadowGodmodeHooks then return true end
                return false, true
            end)
            SharkAPI.Scripting.HookNative(0xB721981B2B939E07, function(pid)  -- GetPlayerInvincible
                if not _G.ShadowGodmodeHooks then return true end
                if pid == PlayerId() then return false, false end
                return true
            end)
        end
        installedAny = true
    end
    if installedAny then _G.__OmenGodmodeHooksInstalled = true end
end


function DisableGodmodeHooks()
    _G.ShadowGodmodeHooks = false
end


function EnableSpoofPed()
    _G.spoofPedEnabled = true
    if type(SharkAPI.Scripting) ~= "table" or type(SharkAPI.Scripting.HookNative) ~= "function" then return end
    -- install once; hooks self-gate on _G.spoofPedEnabled so they can stay resident
    if _G.__OmenSpoofPedInstalled then return end
    _G.__OmenSpoofPedInstalled = true
    local MP_M = GetHashKey("mp_m_freemode_01")
    local H = SharkAPI.Scripting.HookNative
    -- GetEntityModel: return a generic freemode model for our ped
    H(0x9F47B058362C84B5, function(ent)
        if _G.spoofPedEnabled and ent == PlayerPedId() then return false, MP_M end
        return true
    end)
    -- GetPedType: return 4 (PED_TYPE_CIVMALE) for our ped
    H(0xFF059E1E4C01E63C, function(ped)
        if _G.spoofPedEnabled and ped == PlayerPedId() then return false, 4 end
        return true
    end)
end
function DisableSpoofPed()
    _G.spoofPedEnabled = false
end
