                                local c = LoadResourceFile(res, file)
                                if c then
                                    for w in c:gmatch('"([WEAPON_][%w_]+)"') do if w:find("WEAPON_") and not GTA[w] then found[w]=true end end
                                    for w in c:gmatch("'([WEAPON_][%w_]+)'") do if w:find("WEAPON_") and not GTA[w] then found[w]=true end end
                                end
