reg("remove_crutch", { click = function()
    -- Shadow 1:1 (removerestraints): combined wheelchair + crutch removal. Injects into
    -- wasabi_crutch and kills both loops, resets movement, deletes the wheelchair vehicle
    -- and any crutch CObjects from the pool.
    if GetResourceState("wasabi_crutch") ~= "started" then
        toast("warning", "Omen", "wasabi_crutch not running")
        return
    end
    SharkAPI.InjectSafe("wasabi_crutch", [[
        -- Wheelchair
        if _G.StartChairLoop then _G.StartChairLoop = function() end end
        _G.isWheelchairActive = false
        _G.StopChairLoop = true
        _G.BreakLoop = true
        -- Crutch
        if _G.StartCrutchLoop then _G.StartCrutchLoop = function() end end
        _G.isCrutchActive = false
        _G.StopCrutchLoop = true
        -- Reset movement
        ResetPedMovementClipset(PlayerPedId())
        -- Delete wheelchair vehicle if mounted
        local ped = PlayerPedId()
        if IsPedInAnyVehicle(ped, false) then
            local veh = GetVehiclePedIsIn(ped, false)
            DeleteVehicle(veh)
        end
        -- Delete crutch CObjects
        local crutchHash = GetHashKey("crutch")
        for _, obj in ipairs(GetGamePool("CObject")) do
            if DoesEntityExist(obj) and GetEntityModel(obj) == crutchHash then
                DeleteEntity(obj)
            end
        end
    ]])
    toast("success", "Omen", "Wheelchair/Crutch removed")
end })
reg("revive", { click = function()
    -- Try ALL known revive frameworks (not elseif) so it works regardless of which
    -- ambulance/hospital script the server runs. Each only fires if that resource exists.
    local gs = GetResourceState
    local fired = false
    local function try(res, code)
        if gs and gs(res) == "started" then SharkAPI.InjectSafe(res, code); fired = true end
    end
    local function tryAny(res, code)
        if gs and gs(res) == "started" then SharkAPI.InjectSafe("any", code); fired = true end
    end
    tryAny("fearx_redzone", [[ TriggerEvent('hospital:client:Revive') ]])
    try("wasabi_ambulance", [[ TriggerEvent('wasabi_ambulance:revive') ]])
    tryAny("qb-ambulancejob", [[ TriggerEvent('hospital:client:Revive') ]])
    tryAny("ambulancejob", [[ TriggerEvent('esx_ambulancejob:revive') ]])
    tryAny("ox_ambulance", [[ TriggerEvent('ox_ambulance:revive') ]])
    try("core", string.format([[
        local ped = PlayerPedId()
        local c = GetEntityCoords(ped)
        local h = GetEntityHeading(ped)
        if IsEntityDead(ped) then ResurrectPed(ped, c, h, true, false) end
        NetworkResurrectLocalPlayer(c.x, c.y, c.z, h, true, true)
        ClearPedTasksImmediately(ped)
        TriggerEvent('admin:revive')
        TriggerEvent('deathscreen:forceClose')
        if core and core.client then core.client:set('dead', false) end
    ]]))
    -- generic events that many frameworks listen for (safe, no native resurrect)
    tryAny("hospital", [[ TriggerEvent('hospital:client:Revive') ]])
    if not fired then
        toast("info", "Omen", "No revive resource found")
        return
    end
    toast("success", "Omen", "Revive sent")
end })
