reg("bubbleSeer", {
    toggle_on = function()
        Omen.State.bubbleSeer = true
        sendToUi({ action = "bubbleSeerList", show = true, players = {} })  -- appear immediately
        Omen.__bubbleSeerSig = nil
        startTick("bubbleSeer", 500, function()
            if not Omen.State.bubbleSeer then stopTick("bubbleSeer"); return end
            local list = {}
            local names = {}
            for _, pid in ipairs(GetActivePlayers() or {}) do
                if pid ~= PlayerId() then
                    local p = GetPlayerPed(pid)
                    if p ~= 0 and DoesEntityExist(p) and GetPedConfigFlag(p, 423, true) then
                        local nm = GetPlayerName(pid) or ("ID " .. GetPlayerServerId(pid))
                        list[#list+1] = { name = nm }
                        names[#names+1] = nm
                    end
                end
            end
            -- Only push to the DUI when the list actually CHANGED. Re-sending every 500ms
            -- made the overlay re-render and twitch; now it stays put until someone enters/leaves.
            table.sort(names)
            local sig = table.concat(names, "|")
            if sig ~= Omen.__bubbleSeerSig then
                Omen.__bubbleSeerSig = sig
                sendToUi({ action = "bubbleSeerList", show = true, players = list })
            end
        end)
        toast("success", "Omen", "Bubble Seer ON")
    end,
    toggle_off = function()
        Omen.State.bubbleSeer = false
        stopTick("bubbleSeer")
        sendToUi({ action = "bubbleSeerList", show = false, players = {} })
        toast("info", "Omen", "Bubble Seer OFF")
    end,
})
local noclipSpeed = 1.0
local noclipSpeed = 1.0  -- declared here so tick can read/write it
reg("noclip", {
    toggle_on = function()
        Omen.State.noclip = true
        EnableNoclipHooks()
        if type(SharkAPI.SyncTree) == "table" and type(SharkAPI.SyncTree.AddSpoofedTaskType) == "function" then
            SharkAPI.SyncTree.AddSpoofedTaskType(56)
            SharkAPI.SyncTree.AddSpoofedTaskType(199)
        end
        local ped = PlayerPedId()
        SetEntityCollision(ped, false, false)
        SetEntityVisible(ped, true, false)
        startTick("noclip", 0, function()
            if not Omen.State.noclip then stopTick("noclip"); return end
            local ped  = PlayerPedId()
            if not DoesEntityExist(ped) then return end
            local veh  = GetVehiclePedIsIn(ped, false)
            local ent  = (veh ~= 0 and veh) or ped

            -- Disable controls but keep look + boost + jump accessible
            DisableAllControlActions(0)
            EnableControlAction(0, 1,  true)  -- look left/right
            EnableControlAction(0, 2,  true)  -- look up/down
            EnableControlAction(0, 21, true)  -- sprint (shift) = boost
            EnableControlAction(0, 22, true)  -- jump = fly up
            EnableControlAction(0, 36, true)  -- duck/ctrl = fly down

            -- Speed: default, boost (shift), slow (walk)
            local base, boost, slow = 1.0, 2.0, 0.08
            if ReaperV4Detected then base, boost, slow = 0.5, 0.25, 0.05 end
            local speed = base
            if IsDisabledControlPressed(0, 21) then speed = speed + boost end

            -- Direction from camera (Shadow's exact heading/pitch formula)
            local coords  = GetEntityCoords(ent, true)
            local heading = GetGameplayCamRelativeHeading() + GetEntityHeading(ent)
            local pitch   = GetGameplayCamRelativePitch()
            local rad     = math.pi / 180
            local h, p   = heading * rad, pitch * rad
            local cosP    = math.cos(p)
            local dx = -math.sin(h) * cosP
            local dy =  math.cos(h) * cosP
            local dz =  math.sin(p)
            -- Normalize
            local len = math.sqrt(dx*dx + dy*dy + dz*dz)
            if len > 0 then dx,dy,dz = dx/len, dy/len, dz/len end

            -- Read axes via GetDisabledControlNormal - works after DisableAllControlActions
            -- 31 = move forward/back (-1=forward, 1=back), 30 = move left/right
            local fb = -GetDisabledControlNormal(0, 31)  -- negate: GTA Y-axis is inverted
            local lr =  GetDisabledControlNormal(0, 30)
            -- Vertical
            local up = IsDisabledControlPressed(0, 22) and 1 or 0   -- Space
            local dn = IsDisabledControlPressed(0, 36) and 1 or 0   -- Ctrl

            -- Apply movement
            local spd = speed
            if math.abs(fb) > 0.05 then
                coords = coords + vector3(dx*fb*spd, dy*fb*spd, dz*fb*spd)
            end
            if math.abs(lr) > 0.05 then
                -- Strafe: perpendicular to forward direction
                coords = coords + vector3(dy*lr*spd, -dx*lr*spd, 0)
            end
            if up > 0 then coords = vector3(coords.x, coords.y, coords.z + spd) end
            if dn > 0 then coords = vector3(coords.x, coords.y, coords.z - spd) end

            SetEntityCoordsNoOffset(ent, coords.x, coords.y, coords.z, true, true, true)
            SetEntityHeading(ent, heading)
        end)
        toast("success", "Omen", "Noclip ON")
    end,
    toggle_off = function()
        Omen.State.noclip = false
        stopTick("noclip")
        DisableNoclipHooks()
        if type(SharkAPI.SyncTree) == "table" and type(SharkAPI.SyncTree.RemoveSpoofedTaskType) == "function" then
            SharkAPI.SyncTree.RemoveSpoofedTaskType(56)
            SharkAPI.SyncTree.RemoveSpoofedTaskType(199)
        end
        local ped = PlayerPedId()
        SetEntityCollision(ped, true, true)
        SetEntityVisible(ped, true, false)
        FreezeEntityPosition(ped, false)
        SetEntityInvincible(ped, Omen.State.godmode or false)
        toast("info", "Omen", "Noclip OFF")
    end,
})

