reg("megaweapon", {
    toggle_on = function()
        Omen.State.megaweapon = true
        if not _G.spoofWeaponEnabled and EnableSpoofWeapon then _G.__MegaWepSpoofedByUs = true; EnableSpoofWeapon() end
        if has("EditWeaponSize") then
            -- Re-apply tick: EditWeaponSize is one-shot, so re-apply whenever the current
            -- weapon changes or when it reverts (weapon swap, respawn, death, server reset).
            local lastWep = 0
            startTick("megaweapon", 400, function()
                if not Omen.State.megaweapon then stopTick("megaweapon"); if has("EditWeaponSize") then SK.EditWeaponSize(1.0) end; return end
                local ped = PlayerPedId()
                local _, wh = GetCurrentPedWeapon(ped, true)
                -- re-apply on weapon change OR just keep re-asserting so it never breaks
                if wh ~= lastWep then lastWep = wh end
                if wh and wh ~= 0 and wh ~= GetHashKey("WEAPON_UNARMED") then
                    SK.EditWeaponSize(8.0)
                end
            end)
            toast("success", "Weapons", "Mega Weapon on")
        else
            -- fallback: tracked oversized weapon-object clone that follows the held weapon
            SharkAPI.InjectSafe("any", [[
                _G.__OmenMegaWep = true
                if not _G.__OmenMegaWepThread then
                    _G.__OmenMegaWepThread = true
                    CreateThread(function()
                        local obj = 0
                        local curHash = 0
                        while _G.__OmenMegaWep do
                            Wait(0)
                            local p = PlayerPedId()
                            local held = GetCurrentPedWeaponEntityIndex(p)
                            local _, wh = GetCurrentPedWeapon(p, true)
                            if held ~= 0 and DoesEntityExist(held) and wh ~= 0 and wh ~= GetHashKey("WEAPON_UNARMED") then
                                if obj == 0 or not DoesEntityExist(obj) or wh ~= curHash then
                                    if obj ~= 0 and DoesEntityExist(obj) then DeleteEntity(obj) end
                                    local ip = GetEntityCoords(p)
                                    obj = CreateWeaponObject(wh, 1, ip.x, ip.y, ip.z, false, 3.0, 0)
                                    curHash = wh
                                    if DoesEntityExist(obj) then
                                        SetEntityAsMissionEntity(obj, true, true)
                                        SetEntityCollision(obj, false, false)
                                        SetEntityHasGravity(obj, false)
                                    end
                                end
                                if obj ~= 0 and DoesEntityExist(obj) then
                                    local pos = GetEntityCoords(held)
                                    local rot = GetEntityRotation(held, 2)
                                    SetEntityCoords(obj, pos.x, pos.y, pos.z, false, false, false, true)
                                    SetEntityRotation(obj, rot.x, rot.y, rot.z, 2, true)
                                end
                            elseif obj ~= 0 and DoesEntityExist(obj) then
                                DeleteEntity(obj); obj = 0; curHash = 0
                            end
                        end
                        if obj ~= 0 and DoesEntityExist(obj) then DeleteEntity(obj) end
                        _G.__OmenMegaWepThread = nil
                    end)
                end
            ]])
            toast("success", "Weapons", "Mega Weapon on")
        end
    end,
    toggle_off = function()
        Omen.State.megaweapon = false
        stopTick("megaweapon")
        if has("EditWeaponSize") then SK.EditWeaponSize(1.0) end
        SharkAPI.InjectSafe("any", [[ _G.__OmenMegaWep = false ]])
        if _G.__MegaWepSpoofedByUs and DisableSpoofWeapon then _G.__MegaWepSpoofedByUs = false; DisableSpoofWeapon() end
        toast("info", "Weapons", "Mega Weapon off")
    end,
})
reg("freecam", {
    toggle_on = function()
        -- Re-entry guard: if freecam is already active, don't start a second cam/tick
        if freecam.cam or _G.__OmenFreecamActive then return end
        _G.__OmenFreecamActive = true
        ApplyFreecamHooks()
        -- Scan addon vehicles for Shoot Vehicle (Shadow addonVehicles cache)
        SharkAPI.InjectSafe("any", [[
            if not _G.__OmenAddonVehCache then
                local vanilla = {}
                for _, m in ipairs(GetAllVehicleModels() or {}) do vanilla[tostring(m):lower()] = true end
                -- GetAllVehicleModels returns all loaded (incl addons); keep them as the pool
                local list = {}
                for _, m in ipairs(GetAllVehicleModels() or {}) do if type(m)=="string" and #m>0 then list[#list+1] = m end end
                _G.__OmenAddonVehCache = list
            end
        ]])
        if type(CreateCam) ~= "function" then toast("info", "Omen", "Not available"); return end
        local ped = PlayerPedId()
        local p   = GetGameplayCamCoord()
        local r   = GetGameplayCamRot(2)
        freecam.cam   = CreateCam("DEFAULT_SCRIPTED_CAMERA", true)
        freecam.yaw   = r.z
        freecam.pitch = r.x
        freecam.speed = 1.0
        SetCamCoord(freecam.cam, p.x, p.y, p.z)
        SetCamRot(freecam.cam, r.x, r.y, r.z, 2)
        SetCamActive(freecam.cam, true)
        if type(RenderScriptCams) == "function" then RenderScriptCams(true, false, 0, true, false) end
        FreezeEntityPosition(ped, true)
        SetEntityVisible(ped, false, false)
        SetEntityCollision(ped, false, false)
        Omen.send({ action = "applyFreecamHud", on = true, x = p.x, y = p.y, z = p.z, heading = r.z, speed = 1.0 })
        local hudLast = 0
        startTick("freecam", 0, function()
            local cam = freecam.cam
            if not cam then return end
            for _, ctrl in ipairs({30,31,32,33,34,35,21,36,22,24,25,44,71,72,241,242,14,15}) do
                DisableControlAction(0, ctrl, true)
            end
            freecam.speed = IsDisabledControlPressed(0, 21) and 3.5 or 1.0
            local mouseX = GetDisabledControlNormal(0, 1) * 6.0
            local mouseY = GetDisabledControlNormal(0, 2) * 6.0
            freecam.yaw   = freecam.yaw   - mouseX
            freecam.pitch = freecam.pitch - mouseY
            if freecam.pitch >  89 then freecam.pitch =  89 end
            if freecam.pitch < -89 then freecam.pitch = -89 end
            SetCamRot(cam, freecam.pitch, 0.0, freecam.yaw, 2)
            local pos = GetCamCoord(cam)
            local yaw, pitch = math.rad(freecam.yaw), math.rad(freecam.pitch)
            local fx = -math.sin(yaw) * math.cos(pitch)
            local fy =  math.cos(yaw) * math.cos(pitch)
            local fz =  math.sin(pitch)
            local rx = math.cos(yaw)
            local ry = math.sin(yaw)
            local dx, dy, dz = 0.0, 0.0, 0.0
            if IsDisabledControlPressed(0, 32) then dx = dx + fx * freecam.speed; dy = dy + fy * freecam.speed end
            if IsDisabledControlPressed(0, 33) then dx = dx - fx * freecam.speed; dy = dy - fy * freecam.speed end
            if IsDisabledControlPressed(0, 34) then dx = dx - rx * freecam.speed; dy = dy - ry * freecam.speed end
            if IsDisabledControlPressed(0, 35) then dx = dx + rx * freecam.speed; dy = dy + ry * freecam.speed end
            if IsDisabledControlPressed(0, 22) then dz = dz + freecam.speed end
            if IsDisabledControlPressed(0, 36) then dz = dz - freecam.speed end
            local nx, ny, nz = pos.x + dx, pos.y + dy, pos.z + dz
            SetCamCoord(cam, nx, ny, nz)
            if SK.SyncCameraPosition then SK.SyncCameraPosition(true, vector3(nx, ny, nz)) end
            -- Shadow 1:1 freecam scroll-menu (DrawText overlay, scroll cycles, LClick executes)
            local menuOptions = { "Shoot Weapon", "Shoot Vehicle", "Copy Outfit", "Teleport", "Copy License Plate", "Delete Vehicle", "Spawn Prop" }
            freecam.opt = freecam.opt or 1
            local n = #menuOptions
            if IsDisabledControlJustPressed(0, 241) or IsDisabledControlJustPressed(0, 15) then freecam.opt = (freecam.opt - 2) % n + 1 end   -- scroll up
            if IsDisabledControlJustPressed(0, 242) or IsDisabledControlJustPressed(0, 14) then freecam.opt = freecam.opt % n + 1 end          -- scroll down
            local function DrawStr(text, x, y, scale, r, g, b, a)
                SetTextFont(4); SetTextScale(scale, scale); SetTextColour(r, g, b, a)
                SetTextCentre(true); SetTextEntry("STRING"); AddTextComponentString(text); DrawText(x, y)
            end
            local prev = (freecam.opt - 2) % n + 1
            local nxt  = freecam.opt % n + 1
            DrawStr(menuOptions[prev], 0.5, 0.77, 0.30, 210, 210, 210, 100)
            DrawStr("~p~------ ~w~" .. menuOptions[freecam.opt] .. " ~p~------", 0.5, 0.81, 0.45, 255, 255, 255, 255)
            DrawStr(menuOptions[nxt], 0.5, 0.85, 0.30, 210, 210, 210, 100)
            -- Raycast each frame for target-based actions (Shadow selectedEntity)
            do
                local ce2 = GetCamCoord(cam)
                local rray = StartShapeTestRay(ce2.x, ce2.y, ce2.z, ce2.x + fx*1000.0, ce2.y + fy*1000.0, ce2.z + fz*1000.0, -1, PlayerPedId(), 0)
                local _, rhit, rendc, _, rent = GetShapeTestResult(rray)
                freecam.selEntity = (rhit == 1 and rent and rent ~= 0) and rent or nil
                freecam.selCoord = (rhit == 1) and rendc or nil
            end
            -- LClick (attack, control 24) executes the current option (Shadow 1:1)
            if IsDisabledControlJustPressed(0, 24) then
                local sel = menuOptions[freecam.opt]
                local ce = GetCamCoord(cam)
                local ent = freecam.selEntity
                local endc = freecam.selCoord
                if sel == "Shoot Weapon" then
                    if endc then
                        local wlist = _G.__OmenAddonCache or { "WEAPON_HEAVYSNIPER" }
                        local wp = wlist[math.random(#wlist)] or "WEAPON_HEAVYSNIPER"
                        ShootSingleBulletBetweenCoords(ce.x, ce.y, ce.z, endc.x, endc.y, endc.z, 199, true, GetHashKey(wp), PlayerPedId(), true, false, 1000.0)
                    end
                elseif sel == "Shoot Vehicle" then
                    -- Shadow: spawn an addon vehicle at aim point, 3-per-5s limit
                    if GetGameTimer() - (freecam.vehTimer or 0) > 5000 then freecam.vehCount = 0; freecam.vehTimer = GetGameTimer() end
                    if (freecam.vehCount or 0) >= 3 then toast("failure","Freecam","Limit reached - wait 5s")
                    elseif endc then
                        local vlist = _G.__OmenAddonVehCache
                        local pick = (vlist and #vlist > 0) and vlist[math.random(#vlist)] or "adder"
                        local h = GetHashKey(pick)
                        RequestModel(h)
                        local t0 = GetGameTimer(); while not HasModelLoaded(h) and GetGameTimer()-t0 < 3000 do Wait(0) end
                        if HasModelLoaded(h) then
                            local v = CreateVehicle(h, endc.x, endc.y, endc.z + 1.0, 0.0, true, true)
                            SetModelAsNoLongerNeeded(h)
                            freecam.vehCount = (freecam.vehCount or 0) + 1
                        end
                    end
                elseif sel == "Copy Outfit" then
                    if ent and IsEntityAPed(ent) and type(ClonePedToTarget) == "function" then ClonePedToTarget(ent, PlayerPedId())
                    else toast("failure","Freecam","No player targeted") end
                elseif sel == "Teleport" then
                    -- Shadow 1:1: teleport instantly to where you're looking (ped or vehicle),
                    -- stays in freecam so you can keep flying + teleporting whenever you want
                    local tgt
                    if endc then tgt = vector3(endc.x, endc.y, endc.z + 1.0)
                    else local cc = GetCamCoord(cam); tgt = vector3(cc.x + fx * 200.0, cc.y + fy * 200.0, cc.z + fz * 200.0) end
                    local myPed = PlayerPedId()
                    local ent = (IsPedInAnyVehicle(myPed, false) and GetVehiclePedIsIn(myPed, false)) or myPed
                    SetEntityCoordsNoOffset(ent, tgt.x, tgt.y, tgt.z, false, false, false)
                    toast("success", "Freecam", "Teleported")
                elseif sel == "Copy License Plate" then
                    if ent and IsEntityAVehicle(ent) then
                        local plate = GetVehicleNumberPlateText(ent)
                        if plate and type(SharkAPI.SetClipboardText) == "function" then SharkAPI.SetClipboardText(plate) end
                        toast("success","Freecam","Plate: " .. tostring(plate))
                    else toast("failure","Freecam","No vehicle targeted") end
                elseif sel == "Delete Vehicle" then
                    if ent and IsEntityAVehicle(ent) then NetworkRequestControlOfEntity(ent); SetEntityAsMissionEntity(ent, true, true); DeleteVehicle(ent)
                    else toast("failure","Freecam","Target is not a vehicle") end
                elseif sel == "Spawn Prop" then
                    toast("info","Freecam","Unavailable")
                end
            end
            local now = GetGameTimer()
            if now - hudLast > 160 then
                hudLast = now
                Omen.send({
                    action  = "applyFreecamHud",
                    on      = true,
                    opts    = { "Shoot Weapon", "Shoot Vehicle", "Copy Outfit", "Teleport", "Copy License Plate", "Delete Vehicle", "Spawn Prop" },
                    opt     = (freecam.opt or 1) - 1,
                    x = nx, y = ny, z = nz,
                    heading = freecam.yaw % 360,
                    speed   = freecam.speed,
                })
            end
        end)
        toast("success", "Omen", "Freecam on")
    end,
    toggle_off = function()
        _G.__OmenFreecamActive = false
        RemoveFreecamHooks()
        stopTick("freecam")
        freecamStop()
        -- Apply any pending Teleport picked in the freecam menu
        if freecam.pendingTP then
            local tp = freecam.pendingTP; freecam.pendingTP = nil
            local ped = PlayerPedId()
            SetEntityCoordsNoOffset(ped, tp.x, tp.y, tp.z + 1.0, false, false, false)
        end
        Omen.send({ action = "applyFreecamHud", on = false })
        toast("info", "Omen", "Freecam off")
    end,
})
