                if w and not seen[w] then
                    seen[w] = true; total = total + 1
                    print(label and ("  " .. w .. " -- " .. label) or ("  " .. w))
                end
            end
            print("^5[Omen] ===== WEAPON SPAWN CODES =====^0")
            -- framework weapon files first (with labels)
            local ox = LoadResourceFile("ox_inventory", "data/weapons.lua")
            if ox then
                print("^3[ox_inventory]^0")
                for line in ox:gmatch("[^\r\n]+") do
                    local w = line:match("%['(WEAPON_[%w_]+)'%]") or line:match('%["(WEAPON_[%w_]+)"%]')
                    local label = line:match("label%s*=%s*'([^']-)'") or line:match('label%s*=%s*"([^"]-)"')
                    if w then add(w, label) end
                end
            end
            local qb = LoadResourceFile("qb-core", "shared/items.lua") or LoadResourceFile("qbcore", "shared/items.lua")
            if qb then
                print("^3[qb-core]^0")
                for line in qb:gmatch("[^\r\n]+") do
                    local w = line:match("%['(WEAPON_[%w_]+)'%]") or line:match('%["(WEAPON_[%w_]+)"%]')
                    local label = line:match("label%s*=%s*'([^']-)'") or line:match('label%s*=%s*"([^"]-)"')
                    if w then add(w, label) end
                end
            end
            local esx = LoadResourceFile("es_extended", "common/data/weapons.lua")
            if esx then print("^3[es_extended]^0") for w in esx:gmatch("WEAPON_[%w_]+") do add(w) end end
            -- broad scan across every started resource's common weapon files
            print("^3[scan]^0")
            for i = 0, GetNumResources() - 1 do
                local r = GetResourceByFindIndex(i)
                if r and r ~= "" and GetResourceState(r) == "started" then
                    for _, f in ipairs({"config.lua","weapons.lua","items.lua","shared/weapons.lua","client/weapons.lua","data/weapons.lua","shared/items.lua","config/weapons.lua"}) do
                        local c = LoadResourceFile(r, f)
                        if c then for w in c:gmatch("WEAPON_[%w_]+") do add(w) end end
                    end
                end
            end
            print(("^2[Omen] Total unique weapons: %d^0"):format(total))
        end)
    ]==])
    toast("success", "Omen", "Dumping codes to F8")
end })
local CFG_INDEX_KEY = "omen_cfg_index"
function cloudGet(key)
    if not (SK.Cloud and type(SK.Cloud.GetVariable) == "function") then return nil end
    return SK.Cloud.GetVariable(key)
end
function cloudSet(key, value)
    if not (SK.Cloud and type(SK.Cloud.SaveVariable) == "function") then return false end
    SK.Cloud.SaveVariable(key, value); return true
end
-- json: FiveM provides json as a global; also accept exports pattern
local _json = _G.json or (type(exports) == "table" and exports["json"] and exports["json"]["json"]) or nil
function jsonEnc(v)
    if _json and type(_json.encode) == "function" then return _json.encode(v) end
    if type(v) == "table" then
        -- minimal inline encoder for configs (key=string, val=bool/num/string)
        local out, n = {}, 0
        for k, val in pairs(v) do
            n = n + 1
            local vs = type(val) == "string" and ('"' .. val:gsub('"', '\"') .. '"')
                    or type(val) == "number" and tostring(val)
                    or type(val) == "boolean" and tostring(val)
                    or "null"
            out[n] = '"' .. tostring(k) .. '":' .. vs
        end
        return "{" .. table.concat(out, ",") .. "}"
    end
    return tostring(v)
end
function jsonDec(s)
    if _json and type(_json.decode) == "function" then return _json.decode(s) end
    -- minimal flat-object decoder for configs: {"k":true,"k2":1.5,"k3":"str"}
    if type(s) ~= "string" or s:sub(1, 1) ~= "{" then return nil end
    local t = {}
    for k, raw in s:gmatch('"([^"]+)"%s*:%s*("[^"]*"[^,}]*)') do t[k] = raw:match('^"(.*)"') end
    for k, raw in s:gmatch('"([^"]+)"%s*:%s*([%w%.%-]+)') do
        if raw == "true" then t[k] = true
        elseif raw == "false" then t[k] = false
        elseif tonumber(raw) then t[k] = tonumber(raw) end
    end
    return t
end
-- keys never written to / applied from a config
-- Features that should NEVER be saved or restored by configs:
-- other session actions should not auto-enable on boot.
local CFG_NEVER = {
    freecam = true, spectate = true, p_spec = true, hulkman = true, spectatorOverlay = true,
    bubbleSeer = true, skin_menu = true, ped_apply = true, ped_reset = true, applyaddonped = true,
    scanaddonpeds = true, scanaddonweapons = true, noclip = true,
}
function cfgSkip(k, v)
    k = tostring(k)
    if CFG_NEVER[k] then return true end
    if k:find("^__") or k:find("^p_") or k:find("^cfg_") or k:find("^cw_") or k == "autoload_on" then return true end
    local tv = type(v)
    return tv ~= "boolean" and tv ~= "number" and tv ~= "string"
end
local function cfgSnapshot()
    local snap = {}
    for k, v in pairs(State) do
        if not cfgSkip(k, v) then snap[k] = v end
    end
    return snap
end
local function cfgSyncUi(states)
    local batch, size = {}, 0
    for id, val in pairs(states) do
        local kSize = #tostring(id) + (type(val) == "string" and #val or 8) + 12
        if size + kSize > 3000 and next(batch) then
            Omen.send({ action = "syncState", states = batch })
            batch, size = {}, 0
        end
        batch[id] = val
        size = size + kSize
    end
    if next(batch) then Omen.send({ action = "syncState", states = batch }) end
end
local function loadCfgIndex()
    local raw = cloudGet(CFG_INDEX_KEY)
    if type(raw) ~= "string" or raw == "" then return {} end
    local t = jsonDec(raw)
    return (type(t) == "table") and t or {}
end
local function saveCfgIndex(idx) return cloudSet(CFG_INDEX_KEY, jsonEnc(idx)) end
local function humanTime(epoch)
    if type(epoch) ~= "number" or type(os) ~= "table" or type(os.time) ~= "function" then return "saved" end
    local dt = _now() - epoch
    if dt < 60      then return "just now"      end
    if dt < 3600    then return math.floor(dt/60)   .. "m ago" end
    if dt < 86400   then return math.floor(dt/3600) .. "h ago" end
    return math.floor(dt/86400) .. "d ago"
end
function Omen.pushCfgList()
    local idx = loadCfgIndex()
    local out = {}
    for _, entry in ipairs(idx) do
        if type(entry) == "table" and type(entry.name) == "string" then
            out[#out+1] = { name = entry.name, modified = humanTime(entry.at) }
        elseif type(entry) == "string" then
            out[#out+1] = { name = entry, modified = "saved" }
        end
        if #out >= 60 then break end
    end
    Omen.send({ action = "applyCfgList", configs = out })
end
reg("cfg_name", { input = function(v) State.__cfgname = tostring(v or "") end })
reg("cfg_save", { click = function(v)
    local name = tostring((v ~= nil and v ~= "") and v or State.cfg_name or State.__cfgname or ""):gsub("[^%w_-]", "")
    if name == "" then toast("info", "Omen", "Enter a name"); return end
    State.__cfgname = name
    local snapshot = cfgSnapshot()
    if not cloudSet("omen_cfg_" .. name, jsonEnc(snapshot)) then
        toast("info", "Omen", "Cloud offline"); return
    end
    local idx, now, replaced = loadCfgIndex(), _now(), false
    for i, entry in ipairs(idx) do
        local ename = (type(entry) == "table") and entry.name or entry
        if ename == name then idx[i] = { name = name, at = now }; replaced = true; break end
    end
    if not replaced then idx[#idx+1] = { name = name, at = now } end
    while #idx > 60 do table.remove(idx, 1) end
    saveCfgIndex(idx)
    Omen.pushCfgList()
    toast("success", "Omen", "Saved " .. name)
end })
reg("cfg_load", { click = function(v)
    local name = tostring((v ~= nil and v ~= "") and v or State.cfg_name or State.__cfgname or ""):gsub("[^%w_-]", "")
    if name == "" then toast("info", "Omen", "Enter a name"); return end
    local raw = cloudGet("omen_cfg_" .. name)
    if type(raw) ~= "string" or raw == "" then
        toast("info", "Omen", "Not found: " .. name); return
    end
    local decoded = jsonDec(raw)
    if type(decoded) ~= "table" then
        toast("info", "Omen", "Corrupt config"); return
    end
    local changed = {}
    -- turn off toggles that are on now but not in the config
    for id, was in pairs(State) do
        if was == true and decoded[id] ~= true and not cfgSkip(id, was) then
            State[id] = false
            changed[id] = false
            local f = Omen.Features[id]
            if f and type(f.toggle_off) == "function" then f.toggle_off() end
        end
    end
    -- apply the config
    for id, val in pairs(decoded) do
        if not cfgSkip(id, val) then
            local was = State[id]
            State[id] = val
            changed[id] = val
            local f = Omen.Features[id]
            if f then
                if val == true and was ~= true and type(f.toggle_on) == "function" then f.toggle_on() end
                if val == false and was == true and type(f.toggle_off) == "function" then f.toggle_off() end
                if type(val) == "number" and type(f.slide) == "function" then f.slide(val) end
                if type(val) == "string" then
                    if type(f.dropdown) == "function" then f.dropdown(val)
                    elseif type(f.seg) == "function" then f.seg(val)
                    elseif type(f.input) == "function" then f.input(val) end
                end
            end
        end
    end
    cfgSyncUi(changed)
    State.__cfgname = name
    toast("success", "Omen", "Loaded " .. name)
end })
reg("cfg_delete", { click = function(v)
    local name = tostring(v or "")
    if name == "" then return end
    cloudSet("omen_cfg_" .. name, "")   
    local idx, out = loadCfgIndex(), {}
    for _, entry in ipairs(idx) do
        local ename = (type(entry) == "table") and entry.name or entry
        if ename ~= name then out[#out+1] = entry end
    end
    saveCfgIndex(out)
    Omen.pushCfgList()
end })
reg("cfg_removeall", { click = function()
    local idx = loadCfgIndex()
    local n = 0
    for _, entry in ipairs(idx) do
        local ename = (type(entry) == "table") and entry.name or entry
        if ename and ename ~= "" then
            cloudSet("omen_cfg_" .. ename, "")
            n = n + 1
        end
    end
    saveCfgIndex({})
    Omen.pushCfgList()
    toast("success", "Omen", ("Removed %d config%s"):format(n, n == 1 and "" or "s"))
end })
reg("cfg_reset", { click = function()
    local changed = {}
    for id in pairs(Omen.Features) do
        if State[id] == true and not cfgSkip(id, true) then
            State[id] = false
            changed[id] = false
            local f = Omen.Features[id]
            if f and type(f.toggle_off) == "function" then f.toggle_off() end
        end
    end
    cfgSyncUi(changed)
    toast("info", "Omen", "Reset")
end })
if Omen.Ready then Omen.pushCfgList() end
local BONES = {
    Head   = 31086,
    Neck   = 39317,
    Chest  = 24818,
    Pelvis = 11816,
}
State.__aim = State.__aim or {
    fov = 35.0, smooth = 20, distance = 250.0, delay = 0,
    bone = "Head", players = true, peds = false, ignoreFriends = true,
    friends = {},
}
local function screenSize()
    if type(GetActiveScreenResolution) == "function" then return GetActiveScreenResolution() end
    return 1920, 1080
end
local function worldToScreen(x, y, z)
    if type(GetScreenCoordFromWorldCoord) == "function" then
        return GetScreenCoordFromWorldCoord(x, y, z)
    end
    return false, 0.0, 0.0
end
local function angleBetween(camPos, camFwd, targetPos)
    local dx, dy, dz = targetPos.x - camPos.x, targetPos.y - camPos.y, targetPos.z - camPos.z
    local len = math.sqrt(dx*dx + dy*dy + dz*dz)
    if len == 0 then return 0.0 end
    local nx, ny, nz = dx/len, dy/len, dz/len
    local dot = nx*camFwd.x + ny*camFwd.y + nz*camFwd.z
    if dot >  1 then dot =  1 end
    if dot < -1 then dot = -1 end
    return math.deg(math.acos(dot))
end
local function findBestTarget()
    local aim = State.__aim
    local ped   = PlayerPedId()
    local camP  = GetGameplayCamCoord()
    local camR  = GetGameplayCamRot(2)
    local pitch = math.rad(camR.x); local yaw = math.rad(camR.z)
    local camFwd = vector3(-math.sin(yaw)*math.cos(pitch), math.cos(yaw)*math.cos(pitch), math.sin(pitch))
    local best, bestAng
    if aim.players then
        for _, pid in ipairs(GetActivePlayers() or {}) do
            if pid ~= PlayerId() then
                local other = GetPlayerPed(pid)
                if other ~= 0 and not IsEntityDead(other) then
                    if not (aim.ignoreFriends and aim.friends[pid]) then
                        local pos = GetEntityCoords(other)
                        local dist = #(pos - camP)
                        if dist <= aim.distance then
                            local ang = angleBetween(camP, camFwd, pos)
                            if ang <= aim.fov and (not bestAng or ang < bestAng) then
                                best, bestAng = other, ang
                            end
                        end
                    end
                end
            end
        end
    end
    if aim.peds and type(GetGamePool) == "function" then
        for _, npc in ipairs(GetGamePool("CPed") or {}) do
            if npc ~= ped and not IsPedAPlayer(npc) and not IsEntityDead(npc) then
                local pos = GetEntityCoords(npc)
                local dist = #(pos - camP)
                if dist <= aim.distance then
                    local ang = angleBetween(camP, camFwd, pos)
                    if ang <= aim.fov and (not bestAng or ang < bestAng) then
                        best, bestAng = npc, ang
                    end
                end
            end
        end
    end
    return best
end
local function boneCoord(target, boneName)
    if not target or target == 0 or not DoesEntityExist(target) then return vector3(0.0, 0.0, 0.0) end
    local hash = BONES[boneName] or BONES.Head
    if boneName == "Auto" then hash = BONES.Head end
    if type(GetPedBoneCoords) == "function" then
        return GetPedBoneCoords(target, hash, 0.0, 0.0, 0.0)
    end
    return GetEntityCoords(target)
end
