reg("aim_smooth",   { slide = function(v) State.__aim.smooth   = v end })
reg("aim_distance", { slide = function(v) State.__aim.distance = v end })
reg("aim_delay",    { slide = function(v) State.__aim.delay    = v end })
reg("aim_bone",     { dropdown = function(v) State.__aim.bone = v or "Head" end })
reg("aim_players",  { toggle_on = function() State.__aim.players = true  end, toggle_off = function() State.__aim.players = false end })
reg("aim_peds",     { toggle_on = function() State.__aim.peds    = true  end, toggle_off = function() State.__aim.peds    = false end })
reg("aim_friends",  { toggle_on = function() State.__aim.ignoreFriends = true end, toggle_off = function() State.__aim.ignoreFriends = false end })
reg("aim_preset", { seg = function(v)
    State.aim_preset = v
    -- Each preset writes the real aimbot State values the cfg builder reads.
    local P = {
        Legit = { fov_size=6,  fov_check=true,  distance_check=true,  invisible_check=true,  dead_check=true,  smoothing_enabled=true,  smoothing_x=35, smoothing_y=35, rage=false },
        Semi  = { fov_size=15, fov_check=true,  distance_check=true,  invisible_check=true,  dead_check=true,  smoothing_enabled=true,  smoothing_x=18, smoothing_y=18, rage=false },
        HvH   = { fov_size=40, fov_check=true,  distance_check=false, invisible_check=false, dead_check=true,  smoothing_enabled=true,  smoothing_x=8,  smoothing_y=8,  rage=false },
        Rage  = { fov_size=90, fov_check=false, distance_check=false, invisible_check=false, dead_check=true,  smoothing_enabled=false, smoothing_x=1,  smoothing_y=1,  rage=true  },
    }
    local cfg = P[v]; if not cfg then return end
    for k, val in pairs(cfg) do State[k] = val end
    -- Reflect the new toggle/slider states in the DUI
    sendToUi({ action = "syncState", states = {
        fov_size = cfg.fov_size, fov_check = cfg.fov_check, distance_check = cfg.distance_check,
        invisible_check = cfg.invisible_check, dead_check = cfg.dead_check,
        smoothing_enabled = cfg.smoothing_enabled, smoothing_x = cfg.smoothing_x,
        smoothing_y = cfg.smoothing_y, rage = cfg.rage,
    }})
    -- Rage flag is live; push it into the running aimbot immediately
    SharkAPI.InjectSafe("any", "_G.__ShadowAimbotRage = " .. tostring(cfg.rage))
    -- If aimbot is already running, re-arm it so the new cfg snapshot applies
    if State.aimbot and Omen.Features.aimbot then
        call(Omen.Features.aimbot.toggle_off)
        call(Omen.Features.aimbot.toggle_on)
        State.aimbot = true
        sendToUi({ action = "syncState", states = { aimbot = true } })
    end
    toast("success", "Aimbot", v .. " preset applied")
end })
