local Draw = SK.Drawing
local function drawTextAt(x, y, text, r, g, b)
    if not Draw or type(Draw.DrawText) ~= "function" then
        if type(SetTextFont) == "function" then
            SetTextFont(0); SetTextScale(0.3, 0.3); SetTextColour(r or 255, g or 255, b or 255, 255)
            SetTextCentre(true); SetTextOutline()
            BeginTextCommandDisplayText("STRING")
            AddTextComponentSubstringPlayerName(text)
            EndTextCommandDisplayText(x, y)
        end
        return
    end
    Draw.DrawText(text, x * 1920, y * 1080, 15.0, false, r or 255, g or 255, b or 255, 255)
end
State.__esp = State.__esp or { box=false, name=false, health=false, distance=false, skeleton=false, weapon=false }
local _espCacheFrame, _espCache = -1, {}
function espTargets()
    -- Per-frame cache: esp + chams + triggerbot all call this each frame; without
    -- the cache that's 2-3x full player-pool iteration per frame. Cache by frame count.
    local f = GetFrameCount()
    if f == _espCacheFrame then return _espCache end
    local out = {}
    for _, pid in ipairs(GetActivePlayers() or {}) do
        if pid ~= PlayerId() then
            local ped = GetPlayerPed(pid)
            if ped ~= 0 and DoesEntityExist(ped) and not IsEntityDead(ped) then out[#out+1] = { pid = pid, ped = ped } end
        end
    end
    _espCacheFrame, _espCache = f, out
    return out
end
local function anyEspOn()
    local e = State.__esp
    return e.box or e.name or e.health or e.distance or e.skeleton or e.weapon
end
local function startEspLoop()
    if threads["esp"] then return end
    startTick("esp", 0, function()
        if not anyEspOn() then stopTick("esp"); return end
        for _, t in ipairs(espTargets()) do
            if DoesEntityExist(t.ped) then
            local head = boneCoord(t.ped, "Head")
            local pelvis = boneCoord(t.ped, "Pelvis")
            local okH, hx, hy = worldToScreen(head.x, head.y, head.z + 0.25)
            local okP, px, py = worldToScreen(pelvis.x, pelvis.y, pelvis.z)
            if okH and okP then
                if State.__esp.box and Draw and type(Draw.DrawBorderRect) == "function" then
                    local h = math.abs(py - hy)
                    local w = h * 0.35
                    Draw.DrawBorderRect((hx - w/2)*1920, hy*1080, w*1920, h*1080, 255,255,255,220, 1.5)
                end
                if State.__esp.skeleton and Draw and type(Draw.DrawLine) == "function" then
                    Draw.DrawLine(hx*1920, hy*1080, px*1920, py*1080, 255,255,255,140, 1.0)
                end
                local yOffset = 0
                if State.__esp.name then
                    drawTextAt(hx, hy - 0.03, GetPlayerName(t.pid))
                    yOffset = yOffset + 0.018
                end
                if State.__esp.health then
                    local hp  = GetEntityHealth(t.ped)
                    local max = GetEntityMaxHealth(t.ped)
                    drawTextAt(hx, hy - 0.03 + yOffset, hp .. "/" .. max)
                    yOffset = yOffset + 0.018
                end
                if State.__esp.distance then
                    local d = #(GetEntityCoords(t.ped) - GetGameplayCamCoord())
                    drawTextAt(hx, hy - 0.03 + yOffset, string.format("%.1fm", d))
                    yOffset = yOffset + 0.018
                end
                if State.__esp.weapon then
                    local _, w = GetCurrentPedWeapon(t.ped, true)
                    if w and w ~= 0 then
                        drawTextAt(hx, hy - 0.03 + yOffset, tostring(w))
                    end
                end
            end
            end
        end
    end)
end
local function espFlag(id, key)
    reg(id, {
        toggle_on  = function() State.__esp[key] = true;  startEspLoop() end,
        toggle_off = function() State.__esp[key] = false end,
    })
end
