local CHAMS_BONES = {
    Head=31086, Neck=39317, RClav=10706, LClav=64729,
    RUArm=40269, LUArm=45509, RLArm=28252, LLArm=61163,
    RHand=57005, LHand=18905, Spine1=24817, Spine2=24818,
    Spine3=24819, Pelvis=11816, RThigh=51826, LThigh=58271,
    RCalf=36864, LCalf=63931, RFoot=14201, LFoot=52301,
}
local CHAMS_CHAIN = {
    {"Head","Neck"}, {"Neck","Spine3"}, {"Spine3","Spine2"}, {"Spine2","Spine1"}, {"Spine1","Pelvis"},
    {"Neck","RClav"}, {"RClav","RUArm"}, {"RUArm","RLArm"}, {"RLArm","RHand"},
    {"Neck","LClav"}, {"LClav","LUArm"}, {"LUArm","LLArm"}, {"LLArm","LHand"},
    {"Pelvis","RThigh"}, {"RThigh","RCalf"}, {"RCalf","RFoot"},
    {"Pelvis","LThigh"}, {"LThigh","LCalf"}, {"LCalf","LFoot"},
}
local function chamsProject(ped, boneName)
    local hash = CHAMS_BONES[boneName]; if not hash then return nil end
    if type(GetPedBoneCoords) ~= "function" then return nil end
    local w = GetPedBoneCoords(ped, hash, 0.0, 0.0, 0.0)
    if not w then return nil end
    local ok, sx, sy = worldToScreen(w.x, w.y, w.z)
    if not ok then return nil end
    return sx, sy
end
local function chamsRenderPed(ped, mode, sw, sh)
    if not Draw or type(Draw.DrawLine) ~= "function" then return end
    local pts, headSx, headSy, footSx, footSy = {}, nil, nil, nil, nil
    for name, _ in pairs(CHAMS_BONES) do
        local sx, sy = chamsProject(ped, name)
        if sx then pts[name] = { sx * sw, sy * sh } end
    end
    if pts.Head   then headSx, headSy = pts.Head[1],   pts.Head[2]   end
    if pts.LFoot  then footSx, footSy = pts.LFoot[1],  pts.LFoot[2]  end
    if not headSx or not footSx then return end
    local w  = math.max(6, math.abs(footSy - headSy) * 0.32)
    local h  = math.abs(footSy - headSy)
    local cx, cy = (headSx + footSx) * 0.5, (headSy + footSy) * 0.5
    local x0 = cx - w * 0.5
    local y0 = cy - h * 0.5
    if mode == "Glow" and type(Draw.DrawShadowRect) == "function" then
        Draw.DrawShadowRect(x0 - 6, y0 - 6, w + 12, h + 12, 12, 255, 255, 255, 120)
    end
    if mode == "Solid" and type(Draw.DrawRect) == "function" then
        Draw.DrawRect(x0, y0, w, h, 255, 255, 255, 55)
    end
    local thickness  = (mode == "Xray") and 2.2 or 1.4
    local shadowUnder = (mode == "Xray")
    for _, pair in ipairs(CHAMS_CHAIN) do
        local a, b = pts[pair[1]], pts[pair[2]]
        if a and b then
            if shadowUnder then Draw.DrawLine(a[1]+1, a[2]+1, b[1]+1, b[2]+1, 0, 0, 0, 200, thickness) end
            Draw.DrawLine(a[1], a[2], b[1], b[2], 255, 255, 255, 235, thickness)
        end
    end
    if headSx and type(Draw.DrawCircle) == "function" then
        Draw.DrawCircle(headSx, headSy - w * 0.35, w * 0.20, 255, 255, 255, 200, false)
    end
end
reg("chams_mode", {
    dropdown = function(v)
        State.chams_mode = v or "Off"
        if v == "Off" then stopTick("chams"); return end
        startTick("chams", 0, function()
            local mode = State.chams_mode
            if not mode or mode == "Off" then return end
            local sw, sh = screenSize()
            for _, t in ipairs(espTargets()) do chamsRenderPed(t.ped, mode, sw, sh) end
            if State.chams_veh and type(GetGamePool) == "function" then
                for _, veh in ipairs(GetGamePool("CVehicle") or {}) do
                    if veh ~= 0 and not IsEntityDead(veh) then
                        local c = GetEntityCoords(veh)
                        local ok, sx, sy = worldToScreen(c.x, c.y, c.z)
                        if ok and type(Draw.DrawBorderRect) == "function" then
                            Draw.DrawBorderRect(sx * sw - 22, sy * sh - 12, 44, 24, 255, 255, 255, 180, 1.2)
                        end
                    end
                end
            end
        end)
    end,
})
