reg("veh_fly", {
    toggle_on = function()
        startTick("veh_fly", 0, function()
            local v = myVeh(); if not v then return end
            SetVehicleGravityAmount(v, 0.0)
            if IsControlPressed(0, 71) then          -- W: fly forward + up
                local fwd = GetEntityForwardVector(v)
                SetEntityVelocity(v, fwd.x * 30.0, fwd.y * 30.0, fwd.z * 30.0 + 5.0)
            elseif IsControlPressed(0, 72) then      -- S: brake + down
                local vel = GetEntityVelocity(v)
                SetEntityVelocity(v, vel.x * 0.9, vel.y * 0.9, vel.z * 0.9 - 3.0)
            else                                     -- coast/damp
                local vel = GetEntityVelocity(v)
                SetEntityVelocity(v, vel.x * 0.95, vel.y * 0.95, vel.z * 0.95)
            end
        end)
    end,
    toggle_off = function()
        stopTick("veh_fly")
        local v = myVeh(); if v then SetVehicleGravityAmount(v, 9.8) end
    end,
})
