reg("veh_neverfall", {
    toggle_on  = function() SetPedCanBeKnockedOffVehicle(PlayerPedId(), 1) end,
    toggle_off = function() SetPedCanBeKnockedOffVehicle(PlayerPedId(), 0) end,
})
reg("veh_rainbow", {
    toggle_on = function()
        startTick("veh_rainbow", 100, function()
            local v = myVeh(); if not v then return end
            local t = GetGameTimer() / 30
            local r = math.floor((math.sin(t*0.03) + 1) * 127)
            local g = math.floor((math.sin(t*0.03 + 2) + 1) * 127)
            local b = math.floor((math.sin(t*0.03 + 4) + 1) * 127)
            SetVehicleCustomPrimaryColour(v, r, g, b)
            SetVehicleCustomSecondaryColour(v, r, g, b)
        end)
    end,
    toggle_off = function() stopTick("veh_rainbow") end,
})
reg("veh_neon", {
    dropdown = function(v)
        local veh = myVeh(); if not veh then return end
        if v == "Off" then
            for i=0,3 do SetVehicleNeonLightEnabled(veh, i, false) end
        else
            for i=0,3 do SetVehicleNeonLightEnabled(veh, i, true) end
            SetVehicleNeonLightsColour(veh, 255, 255, 255)
        end
    end,
})
reg("veh_clean", { click = function()
    local v = myVeh()
    if v then SetVehicleDirtLevel(v, 0.0); toast("info", "Omen", "Cleaned") end
end })
reg("veh_spawn_in", { input = function(v) State.__vehspawn = tostring(v or "") end })
reg("veh_spawn", { click = function()
    local model = State.vehmodel or State.__vehspawn or ""
    if model == "" then toast("info", "Omen", "Enter a model"); return end
    -- delprev: delete current vehicle first (if the toggle is on)
    if State.delprev then
        -- ban-safe delete of current vehicle (route through inject like deleteveh)
        SharkAPI.InjectSafe("any", [[
            local p = GetVehiclePedIsIn(PlayerPedId(), false)
            if p ~= 0 then
                NetworkRequestControlOfEntity(p)
                local t = GetGameTimer()
                while not NetworkHasControlOfEntity(p) and GetGameTimer()-t < 800 do NetworkRequestControlOfEntity(p); Wait(0) end
                SetEntityAsMissionEntity(p, true, true); DeleteVehicle(p)
                if DoesEntityExist(p) then DeleteEntity(p) end
            end
        ]])
        Wait(200)
    end
    local warpIn = State.teleportinto and "true" or "false"
    -- Shadow 1:1 ban-safe spawn: run CreateVehicle INSIDE a resource env via InjectSafe,
    -- not from the raw executor. ReaperV4 flags raw-executor entity creation but allows a
    -- resource to spawn vehicles, so this avoids the spawn ban.
    SharkAPI.InjectSafe("any", string.format([[
        CreateThread(function()
            local h = GetHashKey("%s")
            local warpIn = %s
            if not IsModelInCdimage(h) then return end
            RequestModel(h)
            local timeout = GetGameTimer() + 5000
            while not HasModelLoaded(h) and GetGameTimer() < timeout do
                Wait(50)
            end
            if not HasModelLoaded(h) then return end
            local ped = PlayerPedId()
            local coords = GetEntityCoords(ped)
            local v = CreateVehicle(h, coords.x, coords.y, coords.z, GetEntityHeading(ped), true, false)
            if v and v ~= 0 then
                SetEntityAsMissionEntity(v, true, true)
                SetVehicleOnGroundProperly(v)
                if warpIn == "true" then
                    SetPedIntoVehicle(ped, v, -1)
                end
            end
            SetModelAsNoLongerNeeded(h)
        end)
    ]], model, warpIn))
    toast("success", "Omen", "Spawned " .. model)
end })
reg("veh_delete", { click = function()
    local v = myVeh() or GetVehiclePedIsUsing(PlayerPedId())
    if not v or v == 0 then toast("info","Omen","Not in a vehicle"); return end
    -- Shadow 1:1: Reaper bans DeleteEntity from the executor against a networked vehicle.
    -- Route net-control-grab + delete through InjectSafe (inject env wrappers handle it).
    SharkAPI.InjectSafe("any", [[
        local myPed = PlayerPedId()
        local v = GetVehiclePedIsIn(myPed, false)
        if v == 0 then v = GetVehiclePedIsUsing(myPed) end
        if v ~= 0 then
            NetworkRequestControlOfEntity(v)
            local t = GetGameTimer()
            while not NetworkHasControlOfEntity(v) and GetGameTimer() - t < 1000 do
                NetworkRequestControlOfEntity(v); Wait(0)
            end
            SetEntityAsMissionEntity(v, true, true)
            DeleteVehicle(v)
            if DoesEntityExist(v) then DeleteEntity(v) end
        end
    ]])
    toast("success","Omen","Vehicle deleted")
end })
reg("veh_unlock", { click = function()
    local v = myVeh(); if not v then return end
    SetVehicleDoorsLocked(v, 1)
    for i=0,5 do SetVehicleDoorsLockedForPlayer(v, i, false) end
    toast("info", "Omen", "Unlocked")
end })
local function selectedPed()
    local sid = State.__selectedSid or 0
    if sid == 0 then toast("info", "Omen", "Pick a player"); return nil, nil end
    local pid = GetPlayerFromServerId(sid)
    if pid == -1 then toast("info", "Omen", "Out of range"); return nil, nil end
    local ped = GetPlayerPed(pid)
    if not ped or ped == 0 or not DoesEntityExist(ped) then toast("info", "Omen", "Player not in range"); return nil, nil end
    return ped, pid
end
reg("p_tp", { click = function()
    -- Shadow 1:1: 2m in front of target using their heading
    local ped, pid = selectedPed(); if not ped then return end
    local c = GetEntityCoords(ped)
    local rad = math.rad(GetEntityHeading(ped))
    SetEntityCoords(PlayerPedId(), c.x + math.sin(rad) * 2.0, c.y + math.cos(rad) * 2.0, c.z, false, false, false, true)
    toast("success", "Omen", "Teleported")
end })
-- Spectate - ported 1:1 from ShadowOld (HandleSpectateToggle), adapted to Shark's HookNative.
function InstallSpectateHooks()
    if _G.__OmenSpectateHooksInstalled then return end
    if type(SharkAPI.Scripting) ~= "table" or type(SharkAPI.Scripting.HookNative) ~= "function" then return end
    _G.__OmenSpectateHooksInstalled = true
    local H = SharkAPI.Scripting.HookNative
    -- detection hooks (gate on _G.SpectateHooksApplied)
    H(0x048746E388762E11, function() if not _G.SpectateHooksApplied then return true end return false, false end)
    H(0x12103B9E0C9F92FB, function() if not _G.SpectateHooksApplied then return true end return false, false end)
    H(0x2763BBAA72A7BCB9, function() if not _G.SpectateHooksApplied then return true end return false, false, 0 end)
    H(0xEE778F8C7E1142E2, function() if not _G.SpectateHooksApplied then return true end return false, 0 end)
    H(0x5234F9F10919EABA, function() if not _G.SpectateHooksApplied then return true end return false, -1 end)
    H(0x65019750A0324133, function() if not _G.SpectateHooksApplied then return true end return false, 50.0 end)
    H(0xB15162CB5826E9E8, function() if not _G.SpectateHooksApplied then return true end return false, false end)
    H(0xCA9D2AA3E326D720, function() if not _G.SpectateHooksApplied then return true end return false, false end)
    H(0xC6D3D26810C8E0F9, function() if not _G.SpectateHooksApplied then return true end return false, true end)
    H(0x8D4D46230B2C353A, function() if not _G.SpectateHooksApplied then return true end return false, 4 end)
    -- cam-coord spoof: GetGameplayCamCoord / GetFinalRenderedCamCoord / GetRenderingCam origin
    -- return our real coords while spectating so AC sees us where we actually are.
    H(0x14D6F5678D8F1B37, function()
        if _G.__SpectateRunning and _G.__SpectateOriginalCoords then return false, _G.__SpectateOriginalCoords end
        if _G.SpectateHooksApplied then local c = GetEntityCoords(PlayerPedId()); return false, c.x, c.y, c.z end
        return true
    end)
    H(0xBAC038F7459AE5AE, function() if _G.__SpectateRunning and _G.__SpectateOriginalCoords then return false, _G.__SpectateOriginalCoords end return true end)
    H(0x7C581F3D71C7F93A, function() if _G.__SpectateRunning and _G.__SpectateOriginalCoords then return false, _G.__SpectateOriginalCoords end return true end)
end
local function stopSpectate()
    _G.__SpectateRunning = false
    -- native spectate cleanup (Reaper path)
    if _G.__SpectateNative then
        _G.__SpectateNative = false
        if type(NetworkSetInSpectatorMode) == "function" then NetworkSetInSpectatorMode(false, PlayerPedId()) end
    end
    _G.SpectateHooksApplied = false
    ClearFocus(); RenderScriptCams(false, false, 0, true, true)
    if _G.__SpectateCam then SetCamActive(_G.__SpectateCam, false); DestroyCam(_G.__SpectateCam, true); _G.__SpectateCam = nil end
    FreezeEntityPosition(PlayerPedId(), false)
    _G.__SpectateOriginalCoords = nil
end
reg("p_spec", { toggle_off = function()
    stopSpectate()
    toast("info", "Omen", "Spectate stopped")
end, toggle_on = function()
    local sid = State.__selectedSid or 0
    if sid == 0 then toast("info", "Omen", "Pick a player"); Omen.State.p_spec = false; sendToUi({action="syncState",states={p_spec=false}}); return end
    if sid == GetPlayerServerId(PlayerId()) then toast("info", "Omen", "Cannot spectate yourself"); Omen.State.p_spec = false; sendToUi({action="syncState",states={p_spec=false}}); return end
    local pid = GetPlayerFromServerId(sid)
    if pid == -1 then toast("info", "Omen", "Player not found"); Omen.State.p_spec = false; sendToUi({action="syncState",states={p_spec=false}}); return end
    -- Re-entry guard: don't stack spectate cameras/threads
    if _G.__SpectateRunning or _G.__SpectateCam then return end
    -- Shadow 1:1 two-path spectate: on Reaper servers the cam-based path flags on
    -- Reaper's ESP heuristics (per-frame foreign-ped coord reads), so use the game's
    -- NATIVE spectator mode instead (a legit multiplayer native the engine uses for
    -- death cams - Reaper doesn't sniff it).
    if GetResourceState("ReaperV4") == "started" then
        local pid = GetPlayerFromServerId(sid)
        if pid ~= -1 then
            _G.__SpectateNative = true
            _G.__SpectateRunning = true
            local tped = GetPlayerPed(pid)
            NetworkSetInSpectatorMode(true, tped)
            CreateThread(function()
                while Omen.State.p_spec and _G.__SpectateNative do
                    Wait(300)
                    local tp = GetPlayerPed(GetPlayerFromServerId(sid))
                    if tp ~= 0 and DoesEntityExist(tp) then NetworkSetInSpectatorMode(true, tp) end
                end
                NetworkSetInSpectatorMode(false, PlayerPedId())
                _G.__SpectateNative = false
                _G.__SpectateRunning = false
            end)
            toast("success", "Omen", "Spectating (native)")
        end
        return
    end
    InstallSpectateHooks()
    _G.SpectateHooksApplied = true
    _G.__SpectateOriginalCoords = GetEntityCoords(PlayerPedId())
    _G.__SpectateRunning = true
    _G.__SpectateCam = nil
    CreateThread(function()
        local tgtPed = GetPlayerPed(pid)
        local myPed = PlayerPedId()
        FreezeEntityPosition(myPed, true)
        SetEntityHeading(myPed, GetEntityHeading(tgtPed))
        SetGameplayCamRelativeHeading(0.0); SetGameplayCamRelativePitch(0.0, 1.0)
        _G.__SpectateCam = CreateCam("DEFAULT_SCRIPTED_CAMERA", true)
        SetCamActive(_G.__SpectateCam, true)
        RenderScriptCams(true, false, 0, true, true)
        local distance, heightBoost = 3.0, 1.0
        while _G.__SpectateRunning do
            Wait(0)
            tgtPed = GetPlayerPed(GetPlayerFromServerId(sid))
            if not DoesEntityExist(tgtPed) then Wait(100)
            else
                local pos = GetEntityCoords(tgtPed); SetFocusEntity(tgtPed)
                local rot = GetGameplayCamRot(0)
                local pitch, yaw = math.rad(rot.x), math.rad(rot.z)
                local fwd = vector3(-math.sin(yaw)*math.cos(pitch), math.cos(yaw)*math.cos(pitch), math.sin(pitch))
                local fx, fy, fz = pos.x, pos.y, pos.z + heightBoost
                SetCamCoord(_G.__SpectateCam, fx - fwd.x*distance, fy - fwd.y*distance, fz - fwd.z*distance)
                PointCamAtCoord(_G.__SpectateCam, fx, fy, fz)
                if IsControlPressed(0, 241) then distance = math.max(2.0, distance - 0.5)
                elseif IsControlPressed(0, 242) then distance = math.min(20.0, distance + 0.5) end
            end
        end
        ClearFocus(); RenderScriptCams(false, false, 0, true, true)
        if _G.__SpectateCam then SetCamActive(_G.__SpectateCam, false); DestroyCam(_G.__SpectateCam, true); _G.__SpectateCam = nil end
        FreezeEntityPosition(myPed, false)
        _G.__SpectateOriginalCoords = nil
    end)
    toast("success", "Omen", "Spectating " .. sid)
end })
reg("p_bring", { click = function()
    local ped = selectedPed(); if not ped then return end
    NetworkRequestControlOfEntity(ped)
    local me = GetEntityCoords(PlayerPedId())
    SetEntityCoords(ped, me.x + 1.0, me.y, me.z, false, false, false, true)
    toast("success", "Omen", "Brought player")
end })
reg("p_copy", { click = function()
    -- Shadow 1:1 (CopyPlayerAppearance): ClonePedToTarget(targetPed, PlayerPedId())
    local tp = select(1, selectedPed())
    if not tp then toast("info", "Omen", "Player not found"); return end
    if DoesEntityExist(tp) and type(ClonePedToTarget) == "function" then
        ClonePedToTarget(tp, PlayerPedId())
        toast("success", "Omen", "Copied appearance")
    else
        toast("info", "Omen", "Target ped not found")
    end
end })
reg("copyappearance", { click = function()
    local sid = Omen.State.__selectedSid or 0
    if sid == 0 then toast("info","Omen","Select a player first"); return end
    local cid = GetPlayerFromServerId(sid)
    if cid == -1 then toast("info","Omen","Player out of range"); return end
    local tp = GetPlayerPed(cid)
