        ClonePedToTarget(tp, PlayerPedId())
        toast("success","Omen","Appearance copied from #"..tostring(sid))
    else
        toast("info","Omen","Target ped not visible")
    end
end })

reg("p_kill", { click = function()
    -- Shadow 1:1 Kill Player: enable weapon spoof, inject addon-firearm scan +
    -- two vertical volleys into the target, cleanup. Runs via InjectSafe.
    local sid = State.__selectedSid or 0
    if sid == 0 then toast("info", "Omen", "Pick a player"); return end
    if sid == GetPlayerServerId(PlayerId()) then toast("info", "Omen", "Can't kill yourself"); return end
    local wasSpoof = _G.spoofWeaponEnabled or false
    if not wasSpoof and EnableSpoofWeapon then EnableSpoofWeapon() end
    SharkAPI.InjectSafe("any", ([==[
        CreateThread(function()
            local targetId = %d
            local tp = GetPlayerFromServerId(targetId)
            if tp == -1 then return end
            local targetPed = GetPlayerPed(tp)
            local myPed = PlayerPedId()
            if not DoesEntityExist(targetPed) or not DoesEntityExist(myPed) then return end
            local DENY = {"KNIFE","KNUCKLE","NIGHTSTICK","HAMMER","_BAT","GOLFCLUB","CROWBAR","BOTTLE","DAGGER","HATCHET","MACHETE","SWITCHBLADE","POOLCUE","WRENCH","BATTLEAXE","AXE","KATANA","SWORD","_BLADE","CLUB","FIST","MELEE","GRENADE","STICKYBOMB","PROXMINE","PIPEBOMB","MOLOTOV","BZGAS","TEARGAS","SMOKEGRENADE","SNOWBALL","FLARE","_BALL","_BOMB","_MINE","EXPLOSIVE","FLASHLIGHT","METALDETECTOR","FIREEXTINGUISHER","PETROLCAN","STUNGUN","TASER","_STUN","CAMERA","BINOCULARS","MUSKET"}
            local function isFirearm(n) n=n:upper() for _,b in ipairs(DENY) do if n:find(b,1,true) then return false end end return true end
            if not _G.__OmenAddonFirearms then
                local found={}
                for i=0,GetNumResources()-1 do
                    local r=GetResourceByFindIndex(i)
                    if r and r~="" and GetResourceState(r)=="started" then
                        for _,f in ipairs({"config.lua","weapons.lua","items.lua","shared/weapons.lua","client/weapons.lua","data/weapons.lua","shared/items.lua","config/weapons.lua"}) do
                            local c=LoadResourceFile(r,f)
                            if c then for w in c:gmatch('"(WEAPON_[%%w_]+)"') do if isFirearm(w) then found[w]=true end end end
                        end
                    end
                end
                local list={} for w in pairs(found) do list[#list+1]=w end
                _G.__OmenAddonFirearms=list
            end
            local pool=_G.__OmenAddonFirearms or {}
            if #pool==0 then return end
            local hashes={GetHashKey(pool[math.random(#pool)]), GetHashKey(pool[math.random(#pool)])}
            for _,h in ipairs(hashes) do RequestWeaponAsset(h,31,0) end
            local to=GetGameTimer()+1500
            while GetGameTimer()<to do local ok=true for _,h in ipairs(hashes) do if not HasWeaponAssetLoaded(h) then ok=false break end end if ok then break end Wait(0) end
            for _,h in ipairs(hashes) do GiveWeaponToPed(myPed,h,50,false,false) end
            local function volley(wh,count)
                SetCurrentPedWeapon(myPed,wh,true); Wait(60)
                local zMin,zMax=-0.2,1.8; local span=zMax-zMin
                for i=1,count do
                    if not DoesEntityExist(targetPed) then return end
                    local tc=GetEntityCoords(targetPed); local fwd=GetEntityForwardVector(targetPed)
                    local t=(count>1) and ((i-1)/(count-1)) or 0.5
                    local z=zMin+t*span
                    ShootSingleBulletBetweenCoords(tc.x+fwd.x, tc.y+fwd.y, tc.z+z, tc.x, tc.y, tc.z+z, 199, true, wh, myPed, true, false, 100.0)
                    Wait(15)
                end
            end
            volley(hashes[1],6); volley(hashes[2],6)
            SetCurrentPedWeapon(myPed, GetHashKey("WEAPON_UNARMED"), true)
            for _,h in ipairs(hashes) do RemoveWeaponFromPed(myPed,h) end
        end)
    ]==]):format(sid))
    toast("warning", "Omen", "Killing " .. sid)
    if not wasSpoof then CreateThread(function() Wait(2000); if DisableSpoofWeapon then DisableSpoofWeapon() end end) end
end })
reg("p_ragdoll", { click = function()
    local ped = select(1, selectedPed()); if not ped then return end
    if has("RequestRagdoll") then
        SK.RequestRagdoll(ped)
    else
        -- fallback: request network control then SetPedToRagdoll (Shadow method)
        SharkAPI.InjectSafe("any", ([==[
            CreateThread(function()
                local tp = %d
                if not DoesEntityExist(tp) then return end
                local dead = 0
                while not NetworkHasControlOfEntity(tp) and dead < 10 do NetworkRequestControlOfEntity(tp); Wait(0); dead = dead + 1 end
                SetPedToRagdoll(tp, 5000, 5000, 0, true, true, false)
            end)
        ]==]):format(ped))
    end
    toast("success", "Omen", "Ragdolled")
end })
reg("p_taze", { click = function()
    local sid = State.__selectedSid or 0
    if sid == 0 then toast("info","Omen","Pick a player"); return end
    if sid == GetPlayerServerId(PlayerId()) then toast("failure","Omen","Can't taze yourself"); return end
    -- Shadow 1:1: enable spoof weapon FIRST (hides the bullets from AC - this is what
    -- stops the "spoofed bullets" ban), then fire stungun bullets via inject (dmg type 0).
    if not _G.spoofWeaponEnabled and EnableSpoofWeapon then _G.__TazeSpoofedByUs = true; EnableSpoofWeapon(); Wait(500) end
    SharkAPI.InjectSafe("any", ([==[
        CreateThread(function()
            local targetPlayer = GetPlayerFromServerId(%d)
            if targetPlayer == -1 then return end
            local targetPed = GetPlayerPed(targetPlayer)
            local myPed = PlayerPedId()
            if not DoesEntityExist(targetPed) or not DoesEntityExist(myPed) then return end
            local tazeHash = GetHashKey("WEAPON_STUNGUN")
            local unarmedHash = GetHashKey("WEAPON_UNARMED")
            GiveWeaponToPed(myPed, tazeHash, 999, false, false)
            for i = 1, 50 do
                local tc = GetEntityCoords(targetPed)
                local ox = (math.random() - 0.5) * 2.0
                local oy = (math.random() - 0.5) * 2.0
                local oz = (math.random() - 0.5) * 1.5
                ShootSingleBulletBetweenCoords(tc.x + ox, tc.y - 0.5 + oy, tc.z + 0.5 + oz, tc.x + ox, tc.y + oy, tc.z + 0.5 + oz, 0, true, tazeHash, myPed, true, false, 2000.0)
            end
            SetCurrentPedWeapon(myPed, unarmedHash, true)
            RemoveWeaponFromPed(myPed, tazeHash)
            GiveWeaponToPed(myPed, unarmedHash, 1, false, true)
            SetCurrentPedWeapon(myPed, unarmedHash, true)
        end)
    ]==]):format(sid))
    -- disable spoof after bullets finish (if we enabled it) so your weapon isn't left broken
    if _G.__TazeSpoofedByUs then
        CreateThread(function() Wait(1500); _G.__TazeSpoofedByUs = false; if DisableSpoofWeapon then DisableSpoofWeapon() end end)
    end
    toast("success", "Omen", "Tazed")
end })
reg("p_punch", { click = function()
    local ped = select(1, selectedPed()); if not ped then return end
    local wasSpoof = _G.spoofWeaponEnabled or false
    if not wasSpoof and EnableSpoofWeapon then EnableSpoofWeapon() end
    if has("SendDamageToEntity") then
        -- documented punch call (weapon_unarmed, melee flags 522/32768)
        SK.SendDamageToEntity(ped, GetEntityCoords(ped), 99, true,
            GetHashKey("weapon_unarmed"), 0.0, 0, 0, 522, 32768, 0, 0, 0, 0, 0, 0)
    end
    toast("success", "Omen", "Punched")
    if not wasSpoof then CreateThread(function() Wait(1500); if DisableSpoofWeapon then DisableSpoofWeapon() end end) end
end })
reg("p_launch", { click = function()
    -- Shadow 1:1 (Launch Vehicle) via InjectSafe: control target's vehicle (or ped) -> Z velocity
    local sid = State.__selectedSid or 0
    if sid == 0 then toast("info", "Omen", "Pick a player"); return end
    SharkAPI.InjectSafe("any", ([=[
        local targetId = %d
        local tPlayer = GetPlayerFromServerId(targetId)
        if tPlayer == -1 then return end
        local tPed = GetPlayerPed(tPlayer)
        if not tPed or tPed == 0 or not DoesEntityExist(tPed) then return end
        local ent = tPed
        if IsPedInAnyVehicle(tPed, false) then
            local veh = GetVehiclePedIsIn(tPed, false)
            if veh ~= 0 and DoesEntityExist(veh) then ent = veh end
        end
        NetworkRequestControlOfEntity(ent)
        local ct = GetGameTimer()
        while not NetworkHasControlOfEntity(ent) and GetGameTimer() - ct < 1000 do
            NetworkRequestControlOfEntity(ent); Wait(0)
        end
        SetEntityVelocity(ent, 0.0, 0.0, 100.0)
    ]=]):format(sid))
    toast("warning", "Omen", "Launched " .. sid)
end })
