})
reg("antiStealthKill", {
    toggle_on = function()
        startTick("antiSK", 500, function()
            SetPedConfigFlag(PlayerPedId(), 275, true)  
        end)
    end,
    toggle_off = function() stopTick("antiSK") end,
})
local function everyOther()
    local out = {}
    for _, pid in ipairs(GetActivePlayers() or {}) do
        if pid ~= PlayerId() then
            local ped = GetPlayerPed(pid)
            if ped ~= 0 then out[#out+1] = ped end
        end
    end
    return out
end
