local PLAYER_CAP  = 256
local PLAYER_RANGE = 1e9    -- include every in-scope player regardless of distance
local function snapshotPlayers()
    local me    = PlayerId()
    local mePed = PlayerPedId()
    local mePos = GetEntityCoords(mePed)
    local out   = {}
    local seen  = {}   -- serverId -> true, dedupe across both sources

    local function addPlayer(pid, ped)
        if not ped or ped == 0 or not DoesEntityExist(ped) then return end
        local sid = GetPlayerServerId(pid)
        if sid == nil or sid < 0 or seen[sid] then return end
        local pos  = GetEntityCoords(ped)
        local dist = #(pos - mePos)
        if pid ~= me and dist > PLAYER_RANGE then return end
        seen[sid] = true
        local rawName = GetPlayerName(pid) or ("Player " .. tostring(sid))
        local name    = (#rawName > 32) and rawName:sub(1, 32) or rawName
        out[#out+1] = {
            id    = sid,
            name  = name,
            dist  = math.floor(dist * 10) / 10,
            veh   = IsPedInAnyVehicle(ped, false),
            alive = not IsEntityDead(ped),
            isMe  = (pid == me),
        }
    end

    -- Source 1: active players (network-scoped)
    for _, pid in ipairs(GetActivePlayers() or {}) do
        addPlayer(pid, GetPlayerPed(pid))
    end
    -- Source 2: every player-ped in the game pool. Catches players whose peds
    -- exist locally but aren't returned by GetActivePlayers on OneSync.
    if type(GetGamePool) == "function" then
        for _, ped in ipairs(GetGamePool("CPed") or {}) do
            if DoesEntityExist(ped) and IsPedAPlayer(ped) then
                local pid = NetworkGetPlayerIndexFromPed(ped)
                if pid ~= nil and pid ~= -1 then
                    addPlayer(pid, ped)
                end
            end
        end
    end

    table.sort(out, function(a, b) return (a.dist or 0) < (b.dist or 0) end)
    for i = #out, PLAYER_CAP + 1, -1 do out[i] = nil end
    return out
end
function Omen.pushPlayers()
    local snap = snapshotPlayers()
    dbg(("players: sending %d rows"):format(#snap))
    Omen.send({ action = "applyPlayers", players = snap })
end
