reg("scanaddonpeds", { click = function()
    toast("info", "Misc", "Scanning addon peds...")
    local found, seen = {}, {}
    -- Method 1: SharkAPI.Streaming.GetLoadedModPeds
    if type(SharkAPI.Streaming) == "table" and type(SharkAPI.Streaming.GetLoadedModPeds) == "function" then
        local list = SharkAPI.Streaming.GetLoadedModPeds()
        if type(list) == "table" then
            for _, p in ipairs(list) do
                local nm = (type(p) == "table" and (p.name or p.model)) or (type(p) == "string" and p) or nil
                if nm and nm ~= "" and not seen[nm:lower()] then seen[nm:lower()]=true; found[#found+1] = nm end
            end
        end
    end
    -- Method 2 (fallback): scan resource files for addon ped models
    if #found == 0 and type(GetNumResources) == "function" then
        for i = 0, GetNumResources() - 1 do
            local res = GetResourceByFindIndex(i)
            if res and GetResourceState(res) == "started" then
                local fdata = LoadResourceFile(res, "fxmanifest.lua") or LoadResourceFile(res, "__resource.lua")
                if fdata then
                    for m in fdata:gmatch("([%w_]+)%.ydd") do
                        if m and #m > 3 and not seen[m:lower()] then seen[m:lower()]=true; found[#found+1] = m end
                    end
                end
            end
        end
    end
    Omen.__AddonPeds = found
    if #found > 0 then Omen.State.addonped = found[1] end
    local opts = {}
    if #found > 0 then
        for i = 1, math.min(#found, 25) do opts[i] = found[i] end
    else
        opts = { "No addon peds found" }
    end
    sendToUi({ action = "setDropdownOptions", id = "addonped", options = opts })
    toast(#found > 0 and "success" or "failure", "Misc", (#found > 0) and (("Found %d addon peds"):format(#found)) or "No addon peds found - type a model manually")
end })
reg("applyaddonped", { click = function(v)
    local model = v or Omen.State.addonped or ""
    if model == "" or model == "Scan first to populate" or model == "No addon peds found" then
        toast("info", "Misc", "Scan + pick a ped first"); return
    end
    local hash = GetHashKey(model)
    if not IsModelInCdimage(hash) then toast("failure", "Misc", "Model not valid"); return end
    RequestModel(hash)
    local t0 = GetGameTimer(); while not HasModelLoaded(hash) and GetGameTimer() - t0 < 3000 do Wait(0) end
    if not HasModelLoaded(hash) then toast("failure", "Misc", "Failed to load"); return end
    SetPlayerModel(PlayerId(), hash)
    SetModelAsNoLongerNeeded(hash)
    SetPedDefaultComponentVariation(PlayerPedId())
    toast("success", "Misc", "Applied ped: " .. model)
end })
