    CreateThread(function()
        local last = 0
        while Omen.Ready do
            Wait(150)
            if State.aim_enable and State.aim_autoshoot then
                local now = GetGameTimer()
                if now - last > 300 then
                    if IsPlayerFreeAiming(PlayerId()) then
                        local ok, target = GetEntityPlayerIsFreeAimingAt(PlayerId())
                        if ok and target and target ~= 0 and IsEntityDead(target) then
                            Omen.playKillSound()
                            Omen.killFeed("Aim kill", "silent")
                            last = now
                        end
                    end
                end
            end
        end
    end)
end
