local EventLog       = {}
local EventLogMax    = 20
local BlockedEvents  = {}
local EventListener  = nil
State.eventlog_on = false
local function eventLogPush(evtName, resource, argsBlob)
    EventLog[#EventLog+1] = {
        event    = tostring(evtName):sub(1, 80),
        resource = tostring(resource or "?"):sub(1, 40),
        args     = tostring(argsBlob or ""):sub(1, 120),
        ts       = _now(),
    }
    if #EventLog > EventLogMax then table.remove(EventLog, 1) end
end
function Omen.pushEventLog()
    local blocked = {}
    for name, _ in pairs(BlockedEvents) do
        blocked[#blocked+1] = name
        if #blocked >= 50 then break end
    end
    Omen.send({ action = "applyEventLog", events = EventLog, blocked = blocked })
end
function Omen.eventLogClear() EventLog = {}; Omen.pushEventLog() end
function Omen.eventBlock(name, on)
    if type(name) ~= "string" or name == "" then return end
    if on then
        BlockedEvents[name] = true
        if SK.BlockServerEvent then SK.BlockServerEvent(true, name) end
        if SK.BlockClientEvent then SK.BlockClientEvent(true, name) end
    else
        BlockedEvents[name] = nil
        if SK.BlockServerEvent then SK.BlockServerEvent(false, name) end
        if SK.BlockClientEvent then SK.BlockClientEvent(false, name) end
    end
    Omen.pushEventLog()
end
reg("eventlog_on", {
    toggle_on = function()
        State.eventlog_on = true
        if EventListener == nil and SK.AddServerEventListener then
            EventListener = SK.AddServerEventListener(function(evtName, payload, res)
                if not State.eventlog_on then return true end
                eventLogPush(evtName, res, payload)
                return not BlockedEvents[evtName]
            end)
        end
        toast("success", "Omen", "Event log on")
    end,
    toggle_off = function() State.eventlog_on = false end,
})
reg("eventlog_clear", { click = function() Omen.eventLogClear() end })
local BL_KEY = "omen_blacklist"
local function loadBlacklist()
