    toggle_off = function() State.webhook_on = false end,
})
function Omen.webhookLog(severity, title, message)
    if not State.webhook_on then return end
    local url = State.__webhookUrl or ""
    if url == "" then return end
    if not (SK.Net and type(SK.Net.AsyncSendWebhook) == "function") then return end
    if type(SK.Net.AsyncRequestHTTP) == "function" then
        local body = jsonEnc({
            username = "Omen",
            content  = string.format("**[%s] %s** - %s", severity or "info", title or "Omen", message or ""),
        })
        SK.Net.AsyncRequestHTTP(url, { method = "POST", body = body, headers = { ["Content-Type"] = "application/json" } })
    end
end
