local WP_KEY = "omen_waypoints"
local function loadWaypoints()
    if not cloudGet then return {} end
    local raw = cloudGet(WP_KEY)
    if type(raw) ~= "string" or raw == "" then return {} end
    local t = jsonDec and jsonDec(raw) or nil
    return (type(t) == "table") and t or {}
end
local function saveWaypoints(list) if cloudSet then cloudSet(WP_KEY, jsonEnc(list)) end end
local function capList(list, n)
    if type(list) ~= "table" then return {} end
    if #list <= n then return list end
    local out = {}
    for i = 1, n do out[i] = list[i] end
    return out
end
function Omen.pushWaypoints()
    Omen.send({ action = "applyWaypoints", waypoints = capList(loadWaypoints(), 30) })
end
Omen.Features["tp_marker"] = {
    click = function()
        local c = GetEntityCoords(PlayerPedId())
        local list = loadWaypoints()
        local idx  = #list + 1
        list[idx] = {
            name = "Waypoint " .. idx,
            x = c.x, y = c.y, z = c.z, at = _now(),
        }
        saveWaypoints(list)
        Omen.pushWaypoints()
        toast("success", "Omen", "Marker saved")
    end,
}
Omen.Features["tp_history"] = {
    click = function()
        Omen.pushWaypoints()
        Omen.send({ action = "openWaypoints" })
    end,
}
if Omen.dispatch then
    local origDispatch = Omen.dispatch
    Omen.dispatch = function(data)
        if type(data) == "table" then
            if data.action == "wp_tp" then
                local list = loadWaypoints()
                local idx = tonumber(data.idx or 0) or 0
                local wp = list[idx]
                if wp then
                    SetEntityCoords(PlayerPedId(), wp.x, wp.y, wp.z, false, false, false, true)
                    toast("success", "Omen", "TP: " .. tostring(wp.name))
                end
                return
            elseif data.action == "wp_rename" then
                local list = loadWaypoints()
                local idx = tonumber(data.idx or 0) or 0
                if list[idx] then
                    list[idx].name = tostring(data.name or list[idx].name)
                    saveWaypoints(list); Omen.pushWaypoints()
                end
                return
            elseif data.action == "wp_delete" then
                local list = loadWaypoints()
                local idx = tonumber(data.idx or 0) or 0
                if list[idx] then
                    table.remove(list, idx); saveWaypoints(list); Omen.pushWaypoints()
                end
                return
            elseif data.action == "requestWaypoints" then
                Omen.pushWaypoints(); return
            end
        end
        return origDispatch(data)
    end
end
if type(_G.CreateThread) == "function" then
    CreateThread(function() Wait(5500); Omen.pushWaypoints() end)
end
local OUTFIT_KEY = "omen_outfit"
-- Outfits are stored as a plain string ("o1|model|d,t,p;...|d,t;...") instead of JSON:
-- jsonEnc/jsonDec can't round-trip the 0-indexed comp/props tables (keys come back as
-- strings, or the tables are dropped entirely when no json global exists).
local function snapshotOutfit()
    local ped = PlayerPedId()
    local comp, props = {}, {}
    for i = 0, 11 do
        comp[#comp+1] = ("%d,%d,%d"):format(GetPedDrawableVariation(ped, i), GetPedTextureVariation(ped, i), GetPedPaletteVariation(ped, i))
    end
    for i = 0, 7 do
        props[#props+1] = ("%d,%d"):format(GetPedPropIndex(ped, i), GetPedPropTextureIndex(ped, i))
    end
    return "o1|" .. tostring(GetEntityModel(ped)) .. "|" .. table.concat(comp, ";") .. "|" .. table.concat(props, ";")
end
local function parseOutfit(raw)
    if type(raw) ~= "string" then return nil end
    local model, comp, props = raw:match("^o1|(%-?%d+)|([^|]*)|([^|]*)$")
    if not model then return nil end
    local o = { model = tonumber(model), comp = {}, props = {} }
    local i = 0
    for d, t, p in comp:gmatch("(%-?%d+),(%-?%d+),(%-?%d+)") do
        o.comp[i] = { drawable = tonumber(d), texture = tonumber(t), palette = tonumber(p) }; i = i + 1
    end
    i = 0
    for d, t in props:gmatch("(%-?%d+),(%-?%d+)") do
        o.props[i] = { drawable = tonumber(d), texture = tonumber(t) }; i = i + 1
    end
    return o
end
local function applyOutfit(o)
    if type(o) ~= "table" then return end
    local ped = PlayerPedId()
    for i = 0, 11 do
        local c = o.comp[i]
        if c then SetPedComponentVariation(ped, i, c.drawable or 0, c.texture or 0, c.palette or 0) end
    end
    for i = 0, 7 do
        local p = o.props[i]
        if p and p.drawable and p.drawable ~= -1 then SetPedPropIndex(ped, i, p.drawable, p.texture or 0, true)
        else ClearPedProp(ped, i) end
    end
end
reg("save_outfit", { click = function()
    local raw = snapshotOutfit()
    Omen.__savedOutfit = raw   -- session copy, so Load still works if Cloud is unavailable
    if cloudSet and cloudSet(OUTFIT_KEY, raw) then
        toast("success","Omen","Outfit saved")
    else
        toast("info","Omen","Saved (session only)")
    end
end })
reg("load_outfit", { click = function()
    local raw = cloudGet and cloudGet(OUTFIT_KEY)
    local o = parseOutfit(type(raw) == "string" and raw or nil) or parseOutfit(Omen.__savedOutfit)
    if not o then toast("info","Omen","No saved outfit"); return end
    if o.model and o.model ~= GetEntityModel(PlayerPedId()) then
        toast("info","Omen","Different ped model")
    end
    applyOutfit(o)
    toast("success","Omen","Outfit loaded")
end })
local HULK_FORCE  = 65
local HULK_COOLDOWN_MS = 400   
local lastHulkThrow = 0
local function hulkTargetName(entity)
    if IsEntityAPed(entity) then
        if IsPedAPlayer(entity) then
            local pid = NetworkGetPlayerIndexFromPed(entity)
            if pid ~= -1 then return GetPlayerName(pid) or "Player" end
        end
        return "NPC"
    elseif IsEntityAVehicle(entity) then
        return "Vehicle"
    end
    return "Entity"
end
reg("hulkman", {
    toggle_on = function()
        Omen.State.hulkman = true
        _G.hulkManEnabled = true
        -- Shadow 1:1 (byte-for-byte): full grab/hold/throw, world-attached entity labels
        -- via native DrawText+SetDrawOrigin, car + ped grabbing. Look at an object and
        -- press Y to pick up, Y again to throw.
        SharkAPI.InjectSafe("any", [==[
                    _G.hulkManEnabled = true
                    local holdingEntity = false
                    local holdingCarEntity = false
                    local holdingPed = false
                    local heldEntity = nil
                    local entityType = nil

                    local function RotationToDirection(rotation)
                        local adjustedRotation = vec3((math.pi / 180) * rotation.x, (math.pi / 180) * rotation.y, (math.pi / 180) * rotation.z)
                        local direction = vec3(-math.sin(adjustedRotation.z) * math.abs(math.cos(adjustedRotation.x)), math.cos(adjustedRotation.z) * math.abs(math.cos(adjustedRotation.x)), math.sin(adjustedRotation.x))
                        return direction
                    end

                    local function GetEntityDisplayName(entity)
                        local entType = GetEntityType(entity)
                        if entType == 2 then
                            local vehicleName = GetDisplayNameFromVehicleModel(GetEntityModel(entity))
                            local name = GetLabelText(vehicleName)
                            if name and name ~= "NULL" then
                                return name .. " (Vehicle)"
                            else
                                return "Vehicle"
                            end
                        elseif entType == 3 then
                            local model = GetEntityModel(entity)
                            if model == GetHashKey("prop_boxpile_05a") then
                                return "Cardboard Box"
                            elseif model == GetHashKey("prop_skate_crate") then
                                return "Crate"
                            elseif model == GetHashKey("prop_bin_10a") then
                                return "Trash Can"
                            else
                                return "Object"
                            end
                        end
                        return "Unknown"
                    end

                    CreateThread(function()
                        while _G.hulkManEnabled do
                            Wait(0)
                            if holdingEntity and heldEntity then
                                local playerPed = PlayerPedId()
                                if holdingCarEntity and not IsEntityPlayingAnim(playerPed, 'anim@mp_rollarcoaster', 'hands_up_idle_a_player_one', 3) then
                                    RequestAnimDict('anim@mp_rollarcoaster')
                                    while not HasAnimDictLoaded('anim@mp_rollarcoaster') do
                                        Wait(100)
                                    end
                                    TaskPlayAnim(playerPed, 'anim@mp_rollarcoaster', 'hands_up_idle_a_player_one', 8.0, -8.0, -1, 50, 0, false, false, false)
                                elseif not holdingCarEntity and not IsEntityPlayingAnim(playerPed, 'anim@heists@box_carry@', 'idle', 3) then
                                    RequestAnimDict('anim@heists@box_carry@')
                                    while not HasAnimDictLoaded('anim@heists@box_carry@') do
                                        Wait(100)
                                    end
                                    TaskPlayAnim(playerPed, 'anim@heists@box_carry@', 'idle', 8.0, -8.0, -1, 50, 0, false, false, false)
                                end

                                if not IsEntityAttached(heldEntity) then
                                    holdingEntity = false
                                    holdingCarEntity = false
                                    heldEntity = nil
                                end
                            end
                        end
                    end)

                    CreateThread(function()
                        while _G.hulkManEnabled do
                            Wait(0)
                            local playerPed = PlayerPedId()
                            local camPos = GetFinalRenderedCamCoord()
                            local camRot = GetFinalRenderedCamRot(2)
                            local direction = RotationToDirection(camRot)
                            local range = 20.0
                            local dest = vec3(camPos.x + direction.x * range, camPos.y + direction.y * range, camPos.z + direction.z * range)

                            local rayHandle = StartShapeTestRay(camPos.x, camPos.y, camPos.z, dest.x, dest.y, dest.z, -1, playerPed, 0)
                            local _, hit, _, _, entityHit = GetShapeTestResult(rayHandle)
                            local validTarget = false

                            SetTextFont(4)
                            SetTextScale(0.40, 0.40)
                            SetTextColour(255, 255, 255, 255)
                            SetTextCentre(true)
                            SetTextEntry("STRING")
                            AddTextComponentString("~p~Shadow~w~Menu")
                            DrawText(0.5, 0.82)

                            if hit == 1 and entityHit and entityHit ~= 0 then
                                local targetType = GetEntityType(entityHit)
                                if targetType == 3 or targetType == 2 then
                                    validTarget = true
                                    entityType = targetType
                                    local entityName = GetEntityDisplayName(entityHit)

                                    SetTextFont(4)
                                    SetTextScale(0.35, 0.35)
                                    SetTextColour(255, 255, 255, 255)
                                    SetTextCentre(true)
                                    SetTextEntry("STRING")
                                    AddTextComponentString("~g~[Y] To Pickup~w~  ---  ~r~[Y] To Throw")
                                    DrawText(0.5, 0.85)

                                    local coords = GetEntityCoords(entityHit)
                                    SetTextScale(0.3, 0.3)
                                    SetTextColour(255, 255, 0, 255)
                                    SetTextEntry("STRING")
                                    AddTextComponentString(entityName)
                                    SetDrawOrigin(coords.x, coords.y, coords.z + 1.5, 0)
                                    DrawText(0, 0)
                                    ClearDrawOrigin()

                                    if targetType == 2 then
                                        NetworkRequestControlOfEntity(entityHit)
                                    end
                                end
                            end

                            if holdingEntity and not validTarget then
                                SetTextFont(4)
                                SetTextScale(0.35, 0.35)
                                SetTextColour(255, 255, 255, 255)
                                SetTextCentre(true)
                                SetTextEntry("STRING")
                                if holdingCarEntity then
                                    AddTextComponentString("~g~[Y] To Pickup~w~  ---  ~r~[Y] To Throw Vehicle")
                                else
                                    AddTextComponentString("~g~[Y] To Pickup~w~  ---  ~r~[Y] To Throw Object")
                                end
                                DrawText(0.5, 0.85)
                            end

                            if IsControlJustReleased(0, 246) then
                                if not holdingEntity and validTarget and entityHit and (entityType == 3 or entityType == 2) then
                                    if entityType == 3 then
                                        local objectModel = GetEntityModel(entityHit)
                                        local objectCoords = GetEntityCoords(entityHit)
                                        DeleteEntity(entityHit)
                                        RequestModel(objectModel)
                                        while not HasModelLoaded(objectModel) do
                                            Wait(100)
                                        end
                                        local newObject = CreateObject(objectModel, objectCoords.x, objectCoords.y, objectCoords.z, true, true, true)
                                        holdingEntity = true
                                        heldEntity = newObject
                                        RequestAnimDict("anim@heists@box_carry@")
                                        while not HasAnimDictLoaded("anim@heists@box_carry@") do
                                            Wait(100)
                                        end
                                        TaskPlayAnim(playerPed, "anim@heists@box_carry@", "idle", 8.0, -8.0, -1, 50, 0, false, false, false)
                                        AttachEntityToEntity(newObject, playerPed, GetPedBoneIndex(playerPed, 60309), 0.0, 0.2, 0.0, 0.0, 0.0, 0.0, true, true, false, true, 1, true)
                                    elseif entityType == 2 then
                                        holdingEntity = true
                                        holdingCarEntity = true
                                        heldEntity = entityHit
                                        RequestAnimDict('anim@mp_rollarcoaster')
                                        while not HasAnimDictLoaded('anim@mp_rollarcoaster') do
                                            Wait(100)
                                        end
                                        TaskPlayAnim(playerPed, 'anim@mp_rollarcoaster', 'hands_up_idle_a_player_one', 8.0, -8.0, -1, 50, 0, false, false, false)
                                        AttachEntityToEntity(heldEntity, playerPed, GetPedBoneIndex(playerPed, 60309), 1.0, 0.5, 0.0, 0.0, 0.0, 0.0, true, true, false, false, 1, true)
                                    end
                                elseif holdingEntity and heldEntity and DoesEntityExist(heldEntity) then
                                    if holdingCarEntity then
                                        holdingEntity = false
                                        holdingCarEntity = false
                                        ClearPedTasks(playerPed)
                                        DetachEntity(heldEntity, true, true)
                                        ApplyForceToEntity(heldEntity, 1, direction.x * 40, direction.y * 40, direction.z * 40, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
                                    else
                                        holdingEntity = false
                                        ClearPedTasks(playerPed)
                                        DetachEntity(heldEntity, true, true)
                                        local playerCoords = GetEntityCoords(playerPed)
                                        SetEntityCoords(heldEntity, playerCoords.x, playerCoords.y, playerCoords.z - 1, false, false, false, false)
                                        SetEntityHeading(heldEntity, GetEntityHeading(playerPed))
                                    end
                                end
                            end
                        end
                    end)
                ]==])
        toast("success", "Misc", "Hulk Man: ON - look at objects, press Y to grab")
    end,
    toggle_off = function()
        Omen.State.hulkman = false
        _G.hulkManEnabled = false
        SharkAPI.InjectSafe("any", "_G.hulkManEnabled = false")
        toast("info", "Misc", "Hulk Man: OFF")
    end,
})
reg("dop_model", { input = function(v) State.__dopModel = tostring(v or "") end })
reg("dop_spawn", { click = function()
    local ped   = PlayerPedId()
    local model = (State.__dopModel and State.__dopModel ~= "") and GetHashKey(State.__dopModel) or GetEntityModel(ped)
    RequestModel(model)
    local dead = 0
    while not HasModelLoaded(model) and dead < 100 do Wait(50); dead = dead + 1 end
    if not HasModelLoaded(model) then toast("info","Omen","Load failed"); return end
    local c = GetEntityCoords(ped)
    dopClone = CreatePed(4, model, c.x + 2, c.y, c.z, GetEntityHeading(ped), true, true)
    SetPedAsGroupMember(dopClone, GetPlayerGroup(PlayerId()))
    SetPedCanRagdoll(dopClone, false)
    SetBlockingOfNonTemporaryEvents(dopClone, true)
    TaskFollowToOffsetOfEntity(dopClone, ped, 1.5, 0.0, 0.0, 3.0, -1, 1.0, true)
    SetModelAsNoLongerNeeded(model)
    toast("success","Omen","Clone spawned")
end })
reg("dop_delete", { click = function()
    if dopClone and DoesEntityExist(dopClone) then
        SetEntityAsMissionEntity(dopClone, true, true); DeleteEntity(dopClone)
    end
    dopClone = nil
    toast("info","Omen","Clone removed")
end })
local rcVeh, rcOriginalPed, rcOriginalCoords
reg("rc_model", { input = function(v) State.__rcModel = tostring(v or "rcbandito") end })
reg("rc_spawn", { click = function()
    local modelName = (State.__rcModel and State.__rcModel ~= "") and State.__rcModel or "rcbandito"
    modelName = modelName:lower():gsub("%s+", "")
    -- Shadow 1:1: full RC car entirely inside the inject (ban-safe + control loop stays
    -- in one scope). Spawn + driver NPC + 3rd-person cam + WASD + space-jump + E-explode + BACK-exit.
    SharkAPI.InjectSafe("any", string.format([==[
        local rcVeh, rcDriver, rcActive, rcExplode = nil, nil, false, false
        local function spawnRC()
            local ped = PlayerPedId()
            local coords = GetEntityCoords(ped)
            local heading = GetEntityHeading(ped)
            local vehModel = GetHashKey("%s")
            local pedModel = GetHashKey("a_m_y_skater_01")
            RequestModel(vehModel); RequestModel(pedModel)
            local timeout = GetGameTimer() + 8000
            while (not HasModelLoaded(vehModel) or not HasModelLoaded(pedModel)) and GetGameTimer() < timeout do Wait(50) end
            if not HasModelLoaded(vehModel) then return false end
            rcVeh = CreateVehicle(vehModel, coords.x + 3.0, coords.y + 3.0, coords.z, heading, true, false)
            if not rcVeh or rcVeh == 0 then return false end
            SetEntityAsMissionEntity(rcVeh, true, true)
            SetVehicleOnGroundProperly(rcVeh)
            rcDriver = CreatePed(5, pedModel, coords.x, coords.y, coords.z, heading, false, false)
            if not rcDriver or rcDriver == 0 then DeleteEntity(rcVeh); return false end
            SetEntityAsMissionEntity(rcDriver, true, true)
            SetPedCanRagdoll(rcDriver, false)
            TaskWarpPedIntoVehicle(rcDriver, rcVeh, -1)
            Wait(300)
            SetModelAsNoLongerNeeded(vehModel)
            SetModelAsNoLongerNeeded(pedModel)
            return true
        end
        local function startRC()
            if not spawnRC() then return end
            rcActive = true; rcExplode = false
            local ped = PlayerPedId()
            FreezeEntityPosition(ped, true)
            local cam = CreateCam("DEFAULT_SCRIPTED_CAMERA", true)
            SetCamActive(cam, true)
            RenderScriptCams(true, true, 500, true, false)
            local camYaw = GetEntityHeading(rcVeh)
            local camPitch = -20.0
            local camDist = 5.5
            local sensitivity = 5.0
            CreateThread(function()
                while rcActive do
                    Wait(0)
                    if not DoesEntityExist(rcVeh) then break end
                    DisableAllControlActions(0)
                    EnableControlAction(0, 1, true)
                    EnableControlAction(0, 2, true)
                    local rcPos = GetEntityCoords(rcVeh)
                    local mx = GetDisabledControlNormal(0, 1) * sensitivity
                    local my = GetDisabledControlNormal(0, 2) * sensitivity
                    camYaw = camYaw - mx * 3.0
                    camPitch = math.max(-50.0, math.min(0.0, camPitch - my * 3.0))
                    local yawRad = math.rad(camYaw); local pitchRad = math.rad(camPitch)
                    local cx = rcPos.x + camDist * math.sin(yawRad) * math.cos(pitchRad)
                    local cy = rcPos.y - camDist * math.cos(yawRad) * math.cos(pitchRad)
                    local cz = rcPos.z + camDist * math.sin(-pitchRad) + 0.5
                    SetCamCoord(cam, cx, cy, cz)
                    PointCamAtCoord(cam, rcPos.x, rcPos.y, rcPos.z + 0.3)
                    local w = IsDisabledControlPressed(0, 32)
                    local s = IsDisabledControlPressed(0, 33)
                    local a = IsDisabledControlPressed(0, 34)
                    local d = IsDisabledControlPressed(0, 35)
                    if IsDisabledControlJustPressed(0, 22) then
                        local vel = GetEntityVelocity(rcVeh)
                        SetEntityVelocity(rcVeh, vel.x, vel.y, vel.z + 8.0)
                    end
                    SetVehicleEngineOn(rcVeh, true, true, false)
                    if     w and a then TaskVehicleTempAction(rcDriver, rcVeh, 7,    1)
                    elseif w and d then TaskVehicleTempAction(rcDriver, rcVeh, 8,    1)
                    elseif s and a then TaskVehicleTempAction(rcDriver, rcVeh, 13,   1)
                    elseif s and d then TaskVehicleTempAction(rcDriver, rcVeh, 14,   1)
                    elseif w        then TaskVehicleTempAction(rcDriver, rcVeh, 9,    1)
                    elseif s        then TaskVehicleTempAction(rcDriver, rcVeh, 22,   1)
                    elseif a        then TaskVehicleTempAction(rcDriver, rcVeh, 4,    1)
                    elseif d        then TaskVehicleTempAction(rcDriver, rcVeh, 5,    1)
                    else                 TaskVehicleTempAction(rcDriver, rcVeh, 6, 2500) end
                    SetTextFont(0); SetTextProportional(1); SetTextScale(0.0, 0.35)
                    SetTextColour(255, 60, 60, 255); SetTextDropShadow(2, 0, 0, 0, 180)
                    SetTextEntry("STRING")
                    AddTextComponentString("~r~[E]~s~ Explode  ~b~[BACK]~s~ Exit  ~g~[SPACE]~s~ Jump")
                    DrawText(0.35, 0.92)
                    if IsDisabledControlJustPressed(0, 38)  then rcExplode = true; break end
                    if IsDisabledControlJustPressed(0, 177) then break end
                end
                if rcExplode and rcVeh and DoesEntityExist(rcVeh) then
                    local p = GetEntityCoords(rcVeh)
                    AddExplosion(p.x, p.y, p.z, 7, 5.0, true, false, 0.0)
                end
                rcActive = false; rcExplode = false
                EnableAllControlActions(0)
                RenderScriptCams(false, true, 600, true, false)
                Wait(650)
                DestroyCam(cam, false)
                FreezeEntityPosition(ped, false)
                if rcDriver and DoesEntityExist(rcDriver) then DeleteEntity(rcDriver) end
                if rcVeh    and DoesEntityExist(rcVeh)    then DeleteEntity(rcVeh) end
            end)
        end
        startRC()
    ]==], modelName))
    toast("success","Omen","RC Car launched: " .. modelName)
end })
reg("rc_return", { click = function()
    if rcVeh and DoesEntityExist(rcVeh) then
        SetEntityAsMissionEntity(rcVeh, true, true); DeleteEntity(rcVeh)
    end
    if rcOriginalPed and rcOriginalCoords then
        SetEntityCoords(rcOriginalPed, rcOriginalCoords.x, rcOriginalCoords.y, rcOriginalCoords.z, false, false, false, true)
    end
    rcVeh, rcOriginalPed, rcOriginalCoords = nil, nil, nil
    toast("info","Omen","Returned")
end })
