Omen.Admins = Omen.Admins or {}
local ADMIN_HINTS = { "admin", "mod ", "moder", " staff", "helper", "owner", "developer", "gm ", " gm", "|staff", "[admin", "[mod", "[gm", "[owner" }
local function looksAdmin(name)
    if type(name) ~= "string" then return false end
    local ln = name:lower()
    for _, h in ipairs(ADMIN_HINTS) do
        if ln:find(h, 1, true) then return true end
    end
    return false
end
local function snapshotAdmins()
    local out = {}
    local mePed = PlayerPedId()
    local mePos = GetEntityCoords(mePed)
    for _, pid in ipairs(GetActivePlayers() or {}) do
        if pid ~= PlayerId() then
            local name = GetPlayerName(pid) or ""
            if looksAdmin(name) then
                local ped = GetPlayerPed(pid)
                if ped ~= 0 then
                    local dist = #(GetEntityCoords(ped) - mePos)
                    out[#out+1] = { name = name, dist = math.floor(dist * 10) / 10, ped = ped, sid = GetPlayerServerId(pid) }
                end
            end
        end
    end
    return out
end
function Omen.pushAdmins()
    Omen.Admins = snapshotAdmins()
    local dui = {}
    for _, a in ipairs(Omen.Admins) do dui[#dui+1] = { name = a.name, dist = a.dist, sid = a.sid } end
    Omen.send({ action = "applyAdmins", admins = dui })
end
if type(_G.CreateThread) == "function" then
    CreateThread(function()
        Wait(1000)
        while Omen.Ready do Omen.pushAdmins(); Wait(2000) end
    end)
end
local CW_KEY = "omen_custom_weapons"
local function loadCustomWeapons()
    if not cloudGet then return {} end
    local raw = cloudGet(CW_KEY)
    if type(raw) ~= "string" or raw == "" then return {} end
    local t = jsonDec(raw)
    return (type(t) == "table") and t or {}
end
local function saveCustomWeapons(list) if cloudSet then cloudSet(CW_KEY, jsonEnc(list)) end end
function Omen.pushCustomWeapons()
    Omen.send({ action = "applyCustomWeapons", weapons = capList(loadCustomWeapons(), 30) })
end
reg("cw_name",  { input = function(v) State.__cwName = tostring(v or "") end })
reg("cw_hash",  { input = function(v) State.__cwHash = tostring(v or "") end })
reg("cw_add", { click = function()
    local name = State.__cwName or ""
    local hash = State.__cwHash or ""
    if hash == "" then toast("info","Omen","Enter weapon hash"); return end
    if not hash:find("^WEAPON_") then hash = "WEAPON_" .. hash:upper() end
    local list = loadCustomWeapons()
    list[#list+1] = { name = (name ~= "" and name or hash), hash = hash, at = _now() }
    saveCustomWeapons(list); Omen.pushCustomWeapons()
    toast("success","Omen","Added")
end })
if Omen.dispatch then
    local origD2 = Omen.dispatch
    Omen.dispatch = function(data)
        if type(data) == "table" then
            if data.action == "cw_give" then
                local idx  = tonumber(data.idx or 0) or 0
                local list = loadCustomWeapons()
                local w = list[idx]
                if w then
                    GiveWeaponToPed(PlayerPedId(), GetHashKey(w.hash), 250, false, true)
                    toast("success","Omen","Given: " .. w.name)
                end
                return
            elseif data.action == "cw_delete" then
                local idx  = tonumber(data.idx or 0) or 0
                local list = loadCustomWeapons()
                if list[idx] then table.remove(list, idx); saveCustomWeapons(list); Omen.pushCustomWeapons() end
                return
            elseif data.action == "requestCustomWeapons" then
                Omen.pushCustomWeapons(); return
            end
        end
        return origD2(data)
    end
end
