-- Chams: per-frame entity highlight using native drawing
local espIds = {
    "esp_box","esp_name","esp_health","esp_distance",
    "esp_skeleton","esp_vehicles","esp_peds","esp_weapon",
    "esp_pickups","esp_props"
}
for _, eid in ipairs(espIds) do
    local _eid = eid
    reg(_eid, {
        toggle_on  = function()
            Omen.State[_eid] = true
            sendToUi({ action="syncState", states={ [_eid]=true } })
            toast("success","Omen",_eid .. " ON")
        end,
        toggle_off = function()
            Omen.State[_eid] = false
            sendToUi({ action="syncState", states={ [_eid]=false } })
        end,
    })
end

reg("chams_wall", {
    toggle_on = function()
        Omen.State.chams_wall = true
        sendToUi({ action="syncState", states={ chams_wall=true } })
        startTick("chams_wall", 0, function()
            if not Omen.State.chams_wall then stopTick("chams_wall"); return end
            local players = GetActivePlayers()
            local me = PlayerId()
            for _, pid in ipairs(players) do
                if pid ~= me then
                    local ped = GetPlayerPed(pid)
                    if DoesEntityExist(ped) then
                        SetEntityDrawOutlineColor(255, 255, 255, 200)
                        SetEntityDrawOutlineShader(1)
                        DrawEntityOnMap(ped)
                    end
                end
            end
        end)
        toast("success","Omen","Wallhack ON")
    end,
    toggle_off = function()
        Omen.State.chams_wall = false
        stopTick("chams_wall")
        sendToUi({ action="syncState", states={ chams_wall=false } })
    end,
})

reg("chams_veh", {
    toggle_on = function()
        Omen.State.chams_veh = true
        sendToUi({ action="syncState", states={ chams_veh=true } })
        startTick("chams_veh", 0, function()
            if not Omen.State.chams_veh then stopTick("chams_veh"); return end
            local players = GetActivePlayers()
            local me = PlayerId()
            for _, pid in ipairs(players) do
                if pid ~= me then
                    local veh = GetVehiclePedIsIn(GetPlayerPed(pid), false)
                    if veh ~= 0 and DoesEntityExist(veh) then
                        SetEntityDrawOutlineColor(255, 255, 255, 180)
                        SetEntityDrawOutlineShader(1)
                        DrawEntityOnMap(veh)
                    end
                end
            end
        end)
        toast("success","Omen","Vehicle Chams ON")
    end,
    toggle_off = function()
        Omen.State.chams_veh = false
        stopTick("chams_veh")
        sendToUi({ action="syncState", states={ chams_veh=false } })
    end,
})

