reg("printweaponcodes", { click = function()
    -- Shadow 1:1: LoadResourceFile ox_inventory/qb-core/es_extended weapon files via inject
    SharkAPI.InjectSafe("any", [==[
        print("^5[Omen] ===== WEAPON SPAWN CODES =====^0")
        local totalFound = 0
        local oxContent = LoadResourceFile("ox_inventory", "data/weapons.lua")
        if oxContent then
            print("^3[ox_inventory]^7")
            for line in oxContent:gmatch("[^\r\n]+") do
                if line:find("WEAPON_") then
                    local weapon = line:match("%['([WEAPON_%w]+)'%]") or line:match('%["([WEAPON_%w]+)"%]')
                    local label = line:match("label%s*=%s*'([^']-)'") or line:match('label%s*=%s*"([^"]-)"')
                    if weapon then totalFound = totalFound + 1; if label then print(string.format("  %s -- %s", weapon, label)) else print(string.format("  %s", weapon)) end end
                end
            end
        end
        local qbContent = LoadResourceFile("qb-core", "shared/items.lua") or LoadResourceFile("qbcore", "shared/items.lua")
        if qbContent then
            print("\n^3[qb-core]^7")
            for line in qbContent:gmatch("[^\r\n]+") do
                if line:find("WEAPON_") then
                    local weapon = line:match("%['([WEAPON_%w]+)'%]") or line:match('%["([WEAPON_%w]+)"%]')
                    local label = line:match("label%s*=%s*'([^']-)'") or line:match('label%s*=%s*"([^"]-)"')
                    if weapon then totalFound = totalFound + 1; if label then print(string.format("  %s -- %s", weapon, label)) else print(string.format("  %s", weapon)) end end
                end
            end
        end
        local esxContent = LoadResourceFile("es_extended", "common/data/weapons.lua")
        if esxContent then
            print("\n^3[es_extended]^7")
            for weapon in esxContent:gmatch("WEAPON_[%w_]+") do
                if weapon:find("WEAPON_") then totalFound = totalFound + 1; print(string.format("  %s", weapon)) end
            end
        end
        print(string.format("\n^5Total weapons found: %d^0", totalFound))
        print("^5[Omen] =============================^0")
    ]==])
    toast("success", "Weapons", "Weapon codes printed to F8")
end })
