reg("scanaddonweapons", { click = function()
    toast("info", "Weapons", "Scanning server weapons...")
    local found, seen = {}, {}
    Omen.__AddonWeaponHashes = {}
    -- Method 1: SharkAPI.Streaming.GetLoadedModWeapons (if executor has it)
    if type(SharkAPI.Streaming) == "table" and type(SharkAPI.Streaming.GetLoadedModWeapons) == "function" then
        local list = SharkAPI.Streaming.GetLoadedModWeapons()
        if type(list) == "table" then
            for _, w in ipairs(list) do
                local nm = (type(w) == "table" and (w.name or w.model)) or (type(w) == "string" and w) or nil
                local hs = (type(w) == "table" and w.hash) or (nm and GetHashKey(nm)) or nil
                if nm and nm ~= "" and not seen[nm:upper()] then seen[nm:upper()]=true; found[#found+1] = nm; if hs then Omen.__AddonWeaponHashes[nm] = hs end end
            end
        end
    end
