                if res and GetResourceState(res) == "started" then
                    for _, path in ipairs({ "weapons.meta", "meta/weapons.meta", "data/weapons.lua", "shared/weapons.lua" }) do
                        local fdata = LoadResourceFile(res, path)
                        if fdata then
                            for w in fdata:gmatch("WEAPON_[%w_]+") do
                                local up = w:upper()
                                if not GTA[up] and not seen[up] then seen[up] = true; found[#found+1] = up; Omen.__AddonWeaponHashes[up] = GetHashKey(up) end
                            end
                        end
                    end
                end
            end
        end
    end
    Omen.__AddonWeapons = found
    if #found > 0 then Omen.State.addonweapon = found[1] end
    -- Cap dropdown options so the message stays under the DUI size limit (full list
    -- kept in Omen.__AddonWeapons for give-random; dropdown shows the first 60).
    local opts = {}
    if #found > 0 then
        for i = 1, math.min(#found, 25) do opts[i] = found[i] end
    else
        opts = { "No addon weapons found" }
    end
    sendToUi({ action = "setDropdownOptions", id = "addonweapon", options = opts })
    toast(#found > 0 and "success" or "failure", "Weapons", (#found > 0) and (("Found %d addon weapons"):format(#found)) or "No addon weapons found")
end })
reg("giveweapon", { click = function(v)
    local wval = v or State.weaponname or ""
    if wval == "" then toast("info","Weapons","Enter weapon name or hash"); return end
    -- auto-enable spoof so giving a weapon doesn't flag/ban
    if not _G.spoofWeaponEnabled and EnableSpoofWeapon then EnableSpoofWeapon(); _G.spoofWeaponEnabled = true end
    local hash
    -- accept a raw numeric hash OR a weapon name
    local num = tonumber(wval)
    if num and tostring(num) == tostring(wval):gsub("%s","") then
        hash = num
        GiveWeaponToPed(PlayerPedId(), hash, 9999, false, true)
        toast("success","Weapons","Gave hash " .. tostring(hash))
    else
        local name = wval:upper()
        if not name:find("WEAPON_") then name = "WEAPON_" .. name end
        GiveWeaponToPed(PlayerPedId(), GetHashKey(name), 9999, false, true)
        toast("success","Weapons","Gave " .. name)
    end
end })
