reg("giveaddonweapon", { click = function(v)
    local sel = v or Omen.State.addonweapon or ""
    if sel == "" or sel == "Scan first to populate" or sel == "No addon weapons found" then
        toast("info", "Weapons", "Scan + pick one first"); return
    end
    -- auto-enable spoof weapon so giving an addon weapon doesn't flag/ban
    if not _G.spoofWeaponEnabled and EnableSpoofWeapon then EnableSpoofWeapon() end
    v = sel
    -- prefer the exact hash from the scan (SharkAPI gives the real give-hash)
    local hash = (Omen.__AddonWeaponHashes and Omen.__AddonWeaponHashes[v]) or GetHashKey(v)
    GiveWeaponToPed(PlayerPedId(), hash, 9999, false, true)
    toast("success", "Weapons", "Gave " .. v)
end })
reg("attachallcomponents", { click = function()
    local ped = PlayerPedId()
    local cur = GetSelectedPedWeapon(ped)
    if not cur or cur == 0 or cur == GetHashKey("WEAPON_UNARMED") then toast("info", "Weapons", "Hold a weapon first"); return end
    -- SharkAPI.Streaming.GetLoadedModWeaponComponents - addon attachments grouped by weapon
    if type(SharkAPI.Streaming) ~= "table" or type(SharkAPI.Streaming.GetLoadedModWeaponComponents) ~= "function" then
        toast("failure", "Weapons", "Component scan not available"); return
    end
    local groups = SharkAPI.Streaming.GetLoadedModWeaponComponents()
    if type(groups) ~= "table" then toast("failure", "Weapons", "No addon components streamed"); return end
    local added = 0
    for _, g in ipairs(groups) do
        -- each group: { weapon=<name/hash>, components={ {name=,hash=}, ... } }
        local wHash = (type(g.weapon) == "number" and g.weapon) or (g.weapon and GetHashKey(tostring(g.weapon))) or nil
        if wHash == cur and type(g.components) == "table" then
            for _, comp in ipairs(g.components) do
                local cHash = (type(comp) == "table" and (comp.hash or (comp.name and GetHashKey(comp.name)))) or (type(comp) == "string" and GetHashKey(comp)) or nil
                if cHash then GiveWeaponComponentToPed(ped, cur, cHash); added = added + 1 end
            end
        end
    end
    toast(added > 0 and "success" or "info", "Weapons", (added > 0) and (("Attached %d components"):format(added)) or "No addon components for this weapon")
end })
reg("giverandomaddon", { click = function()
    -- Use scanned addon weapons (from scanaddonweapons - works with or without Streaming)
    local list = Omen.__AddonWeapons
    if not list or #list == 0 then toast("failure", "Weapons", "Scan server weapons first"); return end
    -- auto-enable spoof weapon so giving an addon weapon doesn't flag/ban
    if not _G.spoofWeaponEnabled and EnableSpoofWeapon then EnableSpoofWeapon() end
    local pick = list[math.random(1, #list)]
    local hash = (Omen.__AddonWeaponHashes and Omen.__AddonWeaponHashes[pick]) or GetHashKey(pick)
    GiveWeaponToPed(PlayerPedId(), hash, 250, false, true)
    toast("success", "Weapons", "Gave random addon: " .. pick)
end })
reg("tpcoords", { click = function()
