reg("vehDesync", {
    toggle_on = function()
        Omen.State.vehDesync = true
        startTick("vehDesync", 0, function()
            if not Omen.State.vehDesync then stopTick("vehDesync"); return end
            local veh = GetVehiclePedIsIn(PlayerPedId(), false)
            if veh ~= 0 then
                SetEntityCollision(veh, false, false)
                if type(SharkAPI.SyncTree) == "table" and type(SharkAPI.SyncTree.SpoofVehicleVelocity) == "function" then
                    SharkAPI.SyncTree.SpoofVehicleVelocity(true, veh, vector3(0, 0, 0))
                end
            end
        end)
        toast("success", "Omen", "Vehicle Desync ON")
    end,
    toggle_off = function()
        Omen.State.vehDesync = false
        stopTick("vehDesync")
        local veh = GetVehiclePedIsIn(PlayerPedId(), false)
        if veh ~= 0 then
            SetEntityCollision(veh, true, true)
            if type(SharkAPI.SyncTree) == "table" and type(SharkAPI.SyncTree.SpoofVehicleVelocity) == "function" then
                SharkAPI.SyncTree.SpoofVehicleVelocity(false, veh)
            end
        end
        toast("info", "Omen", "Vehicle Desync OFF")
    end,
})

