reg("silentkill", { click = function()
    local sid = State.__selectedSid or 0
    if sid == 0 then toast("info","Omen","Pick a player"); return end
    if sid == GetPlayerServerId(PlayerId()) then toast("failure","Omen","Can't kill yourself"); return end
    -- Shadow 1:1: enable spoof weapon, fire silent+invisible bullet volley via inject
    if not _G.spoofWeaponEnabled and EnableSpoofWeapon then _G.__SKSpoofedByUs = true; EnableSpoofWeapon(); Wait(500) end
    SharkAPI.InjectSafe("any", ([==[
        CreateThread(function()
            local targetPlayer = GetPlayerFromServerId(%d)
            if targetPlayer == -1 then return end
            local targetPed = GetPlayerPed(targetPlayer)
            local myPed = PlayerPedId()
            if not DoesEntityExist(targetPed) or not DoesEntityExist(myPed) then return end
            local wh = GetHashKey("WEAPON_HEAVYSNIPER")
            GiveWeaponToPed(myPed, wh, 999, false, false)
            local tc = GetEntityCoords(targetPed)
            local fwd = GetEntityForwardVector(targetPed)
            local zMin, zMax = -0.2, 1.8
            for i = 1, 6 do
                local t = (i - 1) / 5
                local zOff = zMin + t * (zMax - zMin)
                ShootSingleBulletBetweenCoords(tc.x + fwd.x*1.0, tc.y + fwd.y*1.0, tc.z + zOff, tc.x, tc.y, tc.z + zOff, 199, true, wh, myPed, false, true, 100.0)
                Wait(15)
            end
            SetCurrentPedWeapon(myPed, GetHashKey("WEAPON_UNARMED"), true)
            RemoveWeaponFromPed(myPed, wh)
        end)
    ]==]):format(sid))
    if _G.__SKSpoofedByUs then
        CreateThread(function() Wait(1500); _G.__SKSpoofedByUs = false; if DisableSpoofWeapon then DisableSpoofWeapon() end end)
    end
    toast("success","Omen","Silent killed")
end })
reg("explodeplayer", { click = function()
    local sid = State.__selectedSid or 0
    if sid == 0 then toast("info","Omen","Pick a player"); return end
    -- Shadow 1:1: mancher/manchez vehicle-drop with byte-decoded natives (stealth).
    -- WaveShield-blocked (ban trigger there).
    if GetResourceState("WaveShield") == "started" then toast("warning","Omen","WaveShield Found - Ban Prevented!"); return end
    local script = string.format([==[ local function decode(tbl) local s=""; for i=1,#tbl do s=s..string.char(tbl[i]) end; return s end; local function g(n) return _G[decode(n)] end; local function wait(n) local w=g({87,97,105,116}); if w then return w(n) end end; local vehicleName=decode({109,97,110,99,104,101,122}); local requestModel=g({82,101,113,117,101,115,116,77,111,100,101,108}); if not requestModel then return end; requestModel(vehicleName); local hasModelLoaded=g({72,97,115,77,111,100,101,108,76,111,97,100,101,100}); if hasModelLoaded then local attempts=0; while not hasModelLoaded(vehicleName) and attempts<20 do wait(500); attempts=attempts+1 end; if attempts>=20 then return end end; local getPlayerFromServerId=g({71,101,116,80,108,97,121,101,114,70,114,111,109,83,101,114,118,101,114,73,100}); if not getPlayerFromServerId then return end; local tp=getPlayerFromServerId(%d); if tp==-1 then return end; local getPlayerPed=g({71,101,116,80,108,97,121,101,114,80,101,100}); if not getPlayerPed then return end; local targetPed=getPlayerPed(tp); if not targetPed or targetPed==0 then return end; local localPed=getPlayerPed(-1); local getEntityCoords=g({71,101,116,69,110,116,105,116,121,67,111,111,114,100,115}); local getEntityHeading=g({71,101,116,69,110,116,105,116,121,72,101,97,100,105,110,103}); if not getEntityCoords or not getEntityHeading then return end; local targetPos=getEntityCoords(targetPed); local heading=getEntityHeading(targetPed); local giveWeapon=g({71,105,118,101,87,101,97,112,111,110,84,111,80,101,100}); local setCurrentWeapon=g({83,101,116,67,117,114,114,101,110,116,80,101,100,87,101,97,112,111,110}); local getHashKey=g({71,101,116,72,97,115,104,75,101,121}); local shootBullet=g({83,104,111,111,116,83,105,110,103,108,101,66,117,108,108,101,116,66,101,116,119,101,101,110,67,111,111,114,100,115}); local removeWeapon=g({82,101,109,111,118,101,87,101,97,112,111,110,70,114,111,109,80,101,100}); local setMission=g({83,101,116,69,110,116,105,116,121,65,115,77,105,115,115,105,111,110,69,110,116,105,116,121}); local pistolHash=getHashKey(decode({87,69,65,80,79,78,95,65,80,80,73,83,84,79,76})); giveWeapon(localPed,pistolHash,200,false,true); setCurrentWeapon(localPed,pistolHash,true); wait(1000); local createVehicle=g({67,114,101,97,116,101,86,101,104,105,99,108,101}); if not createVehicle then return end; local vehicleSpawnPos={x=targetPos.x+2.0,y=targetPos.y,z=targetPos.z+0.2}; local vehicle=createVehicle(vehicleName,vehicleSpawnPos.x,vehicleSpawnPos.y,vehicleSpawnPos.z,heading,true,true); if not vehicle or vehicle==0 then return end; if setMission then setMission(vehicle,true,true) end; local setHealth=g({83,101,116,69,110,116,105,116,121,72,101,97,108,116,104}); if setHealth then setHealth(vehicle,10) end; for i=1,60 do local vc=getEntityCoords(vehicle); shootBullet(targetPos.x,targetPos.y,targetPos.z+1.0,vc.x,vc.y,vc.z+0.3,2000.0,true,pistolHash,localPed,true,false,2000.0); wait(1) end; removeWeapon(localPed,pistolHash) ]==], sid)
    SharkAPI.InjectSafe("any", script)
    toast("success", "Omen", "Exploded player")
end })
reg("dropocean", { click = function()
    local sid = State.__selectedSid or 0
    if sid == 0 then toast("info","Omen","Pick a player"); return end
    -- Shadow 1:1 (DoDropOcean): invis (skipped on Reaper - ban), TP to player, carry via
    -- monitor's carry/piggyback command, TP to ocean, carry again to drop. We never touch
    -- the target ped directly (monitor's ExecuteCommand runs in its own VM = AC-safe).
    SharkAPI.InjectSafe("any", ([==[
        CreateThread(function()
            local targetSid = %d
            local cid = GetPlayerFromServerId(targetSid)
            if cid == -1 then return end
            local myPed = PlayerPedId()
            local reaperOn = GetResourceState("ReaperV4") == "started"
            if not reaperOn then SetEntityVisible(myPed, false, false) end
            Wait(300)
            -- TP to player
            for i = 1, 4 do
                local tped = GetPlayerPed(cid)
                if DoesEntityExist(tped) then
                    local tc = GetEntityCoords(tped)
                    SetEntityCoordsNoOffset(myPed, tc.x, tc.y, tc.z, false, false, false)
                end
                Wait(100)
            end
            -- carry (monitor carry/piggyback command exploit)
            local function carry()
                ExecuteCommand('carry ' .. targetSid)
                ExecuteCommand('piggyback ' .. targetSid)
                ExecuteCommand('pb ' .. targetSid)
            end
            carry()
            Wait(600)
            -- TP to ocean
            SetEntityCoordsNoOffset(myPed, -1751.0, -1170.0, -40.5, false, false, false)
            Wait(500)
            -- fire carry again to drop them in the ocean
            carry()
            Wait(200)
            if not reaperOn then SetEntityVisible(myPed, true, false) end
        end)
    ]==]):format(sid))
    toast("warning", "Omen", "Dropping player in ocean...")
end })
reg("forcefall", { click = function()
    local sid = State.__selectedSid or 0
    if sid == 0 then toast("info","Omen","Pick a player"); return end
    if sid == GetPlayerServerId(PlayerId()) then toast("failure","Omen","Cannot target yourself"); return end
    SharkAPI.InjectSafe("any", string.format([==[
                    CreateThread(function()
                        local targetId = %s
                        local targetPlayer = GetPlayerFromServerId(tonumber(targetId))
                        if targetPlayer == -1 then return end
                        local targetPed = GetPlayerPed(targetPlayer)
                        if not DoesEntityExist(targetPed) then return end
                        NetworkRequestControlOfEntity(targetPed)
                        local deadline = GetGameTimer() + 2000
                        while not NetworkHasControlOfEntity(targetPed) and GetGameTimer() < deadline do
                            NetworkRequestControlOfEntity(targetPed)
                            Wait(50)
                        end
                        if not NetworkHasControlOfEntity(targetPed) then return end
                        SetPedToRagdoll(targetPed, 5000, 5000, 0, true, true, false)
                    end)
                ]==], sid))
    toast("success","Omen","Force fall sent")
end })
reg("launchplayer_v2", { click = function()
    local ped, _ = selectedPed()
    if not ped then return end
    SetEntityVelocity(ped, 0, 0, 80)
    toast("success","Omen","Launched V2")
end })
reg("cageplayer", { click = function()
    local sid = State.__selectedSid or 0
    if sid == 0 then toast("info","Omen","Pick a player"); return end
    SharkAPI.InjectSafe("any", string.format([==[
                            local targetCid = GetPlayerFromServerId(%d)
                            if targetCid == -1 then return end
                            local targetPed = GetPlayerPed(targetCid)
                            if not DoesEntityExist(targetPed) then return end
                            local coords = GetEntityCoords(targetPed)
                            local cageModel = GetHashKey("prop_byard_concbarier")
                            RequestModel(cageModel)
                            local deadline = GetGameTimer() + 5000
                            while not HasModelLoaded(cageModel) and GetGameTimer() < deadline do Wait(50) end
                            if not HasModelLoaded(cageModel) then return end
                            local sides = { {2.0, 0.0, 90.0}, {-2.0, 0.0, 270.0}, {0.0, 2.0, 0.0}, {0.0, -2.0, 180.0} }
                            for i = 1, #sides do
                                local s = sides[i]
                                local prop = CreateObject(cageModel, coords.x + s[1], coords.y + s[2], coords.z - 1.0, true, false, false)
                                if DoesEntityExist(prop) then
                                    SetEntityHeading(prop, s[3])
                                    FreezeEntityPosition(prop, true)
                                    SetEntityAsMissionEntity(prop, true, true)
                                end
                            end
                            SetModelAsNoLongerNeeded(cageModel)
                        ]==], sid))
    toast("success","Omen","Caged player")
end })
reg("crashplayer", { click = function()
    local _, pid = selectedPed()
    if not pid then return end
    -- Crash via malformed network object
