})
reg("changeplate", { click = function()
    local plate = Omen.State.plateInput or "OMEN"
    local veh = GetVehiclePedIsIn(PlayerPedId(), false)
    if veh == 0 then toast("info","Omen","Not in a vehicle"); return end
    local realPlate = GetVehicleNumberPlateText(veh)
    SetVehicleNumberPlateText(veh, plate)
    -- Shadow 1:1: hook the getter for this vehicle so server-side polls still see the
    -- original plate (some servers monitor plate changes for "godplate" detection)
    if type(SharkAPI.Scripting) == "table" and type(SharkAPI.Scripting.HookNative) == "function" and not _G.__OmenPlateHook then
        _G.__OmenPlateHook = true
        _G.__OmenPlateMap = _G.__OmenPlateMap or {}
        _G.__OmenPlateMap[veh] = realPlate
        SharkAPI.Scripting.HookNative(0xE8522D58D7A1BB23, function(v)  -- GetVehicleNumberPlateText
            if _G.__OmenPlateMap and _G.__OmenPlateMap[v] then return false, _G.__OmenPlateMap[v] end
            return true
        end)
    elseif _G.__OmenPlateMap then
        _G.__OmenPlateMap[veh] = realPlate
    end
    toast("success","Omen","Plate changed: " .. plate)
end })
reg("teslaMode", {
    toggle_on  = function()
        Omen.State.teslaMode = true
        startTick("teslaMode", 0, function()
            if not Omen.State.teslaMode then stopTick("teslaMode"); return end
            local veh = GetVehiclePedIsIn(PlayerPedId(), false)
            if veh ~= 0 then
                local wp = GetFirstBlipInfoId(8)
                if DoesBlipExist(wp) then
                    local c = GetBlipInfoIdCoord(wp)
                    TaskVehicleDriveToCoord(PlayerPedId(), veh, c.x, c.y, c.z, 60.0, 0, GetEntityModel(veh), 786603, 5.0, -1)
                end
            end
        end)
    end,
    toggle_off = function()
        Omen.State.teslaMode = false
        stopTick("teslaMode")
