-- Triggers
reg("jobname",   { input=function(v) Omen.State.__jobname=v end })
reg("jobgrade",  { input=function(v) Omen.State.__jobgrade=v end })
reg("setjob", { click = function()
    if acWouldBan() then return end
    if acWouldBan() then return end
    local job = Omen.State.jobname or Omen.State.__jobname or ""
    local grade = tonumber(Omen.State.jobgrade or Omen.State.__jobgrade) or 0
    if job == "" then toast("failure","Omen","Enter a job name"); return end
    -- Shadow 1:1: avoid raw esx:setJob (ReaperV4 bans for it via ox_lib ESX bridge).
    -- Use multijob ClockIn + core_multijob which don't trip the bridge watch.
    SharkAPI.InjectSafe("any", ("TriggerServerEvent('wasabi_multijob:ClockIn', { job = '%s', grade = %d })"):format(job, grade))
    SharkAPI.InjectSafe("any", ("TriggerServerEvent('core_multijob:changeJob', '%s', %d)"):format(job, grade))
    SharkAPI.InjectSafe("any", ("TriggerServerEvent('esx_society:setJob', '%s', %d)"):format(job, grade))
    toast("success","Omen", ("Job set: %s (grade %d)"):format(job, grade))
end })
reg("itemname",  { input=function(v) Omen.State.__itemname=v end })
reg("itemcount", { input=function(v) Omen.State.__itemcount=v end })
reg("spawnitem2", { click = function()
