    -- Shadow 1:1: dedicated wasabi_ambulance path via inject
    SharkAPI.InjectSafe("any", ("TriggerServerEvent('wasabi_ambulance:server:GiveItem', '%s', %d)"):format(item, count))
    toast("success","Omen", ("Gave %dx %s"):format(count, item))
end })
