reg("givevehicle",  { click=function()
    local model = GetHashKey(Omen.State.givevehmodel or "adder")
    RequestModel(model)
    local _ml6 = GetGameTimer(); while not HasModelLoaded(model) and GetGameTimer() - _ml6 < 3000 do Wait(0) end
    local c = GetEntityCoords(PlayerPedId())
    local veh = CreateVehicle(model, c.x+3, c.y, c.z, 0, true, false)
    SetModelAsNoLongerNeeded(model)
    toast("success","Omen","Vehicle spawned nearby")
end })
reg("givevehowned", { click = function()
    local modelName = Omen.State.givevehmodel or "adder"
    if modelName == "" then modelName = "adder" end
    -- Shadow 1:1: SetVehicleOwned:Server flow with full props (makes it owned/persistent)
    SharkAPI.InjectSafe("any", ([==[
        local modelName = "%s"
        local hash = GetHashKey(modelName)
        RequestModel(hash)
        local t0 = GetGameTimer(); while not HasModelLoaded(hash) and GetGameTimer()-t0 < 3000 do Wait(0) end
        if not HasModelLoaded(hash) then return end
        local ped = PlayerPedId()
        local c = GetEntityCoords(ped)
        local fwd = GetEntityForwardVector(ped)
        local veh = CreateVehicle(hash, c.x + fwd.x*3.0, c.y + fwd.y*3.0, c.z, GetEntityHeading(ped), true, true)
        SetModelAsNoLongerNeeded(hash)
        SetVehicleNumberPlateText(veh, "VOID1337")
        SetVehicleOnGroundProperly(veh)
        SetPedIntoVehicle(ped, veh, -1)
        local props = {
            model = hash, plate = "VOID1337",
            bodyHealth = 1000.0, engineHealth = 1000.0, tankHealth = 1000.0, fuelLevel = 100.0,
            dirtLevel = 0.0, color1 = 0, color2 = 0,
        }
        TriggerServerEvent("SetVehicleOwned:Server", GetVehicleNumberPlateText(veh))
        TriggerServerEvent("qb-vehicletuning:server:SaveVehicleProps", props)
        TriggerServerEvent("esx_vehicleshop:setVehicleOwned", GetVehicleNumberPlateText(veh))
    ]==]):format(modelName))
    toast("success","Omen", "Spawned owned: " .. modelName)
end })
