reg("seeitemcodes", { click = function()
    -- Shadow: ox_inventory item dump into a lib context menu (copy on select)
    if GetResourceState("ox_inventory") ~= "started" then toast("failure","Misc","ox_inventory not running"); return end
    SharkAPI.InjectSafe("ox_inventory", [[
        local items = exports.ox_inventory:Items()
        local options = {}
        for name, data in pairs(items) do
            options[#options+1] = { title = (data.label or name), description = ("Item: %s"):format(name), onSelect = function() if lib and lib.setClipboard then lib.setClipboard(name) end end }
        end
        table.sort(options, function(a,b) return a.title < b.title end)
        if lib and lib.registerContext then
            lib.registerContext({ id = "omen_items", title = "Item Codes", options = options })
            lib.showContext("omen_items")
        end
    ]])
    toast("success","Misc","Opening item codes...")
end })
reg("fakescan", { click = function()
    -- Shadow: teleport through a grid making self invisible+invincible+frozen, print result
    local pp = PlayerPedId()
    local start = GetEntityCoords(pp)
    SetEntityVisible(pp, false, false)
    FreezeEntityPosition(pp, true)
    CreateThread(function()
        for gx = -1, 1 do for gy = -1, 1 do
            SetEntityCoordsNoOffset(pp, start.x + gx*350.0, start.y + gy*350.0, start.z, false, false, false)
            Wait(120)
        end end
        SetEntityCoordsNoOffset(pp, start.x, start.y, start.z, false, false, false)
        SetEntityVisible(pp, true, false)
        FreezeEntityPosition(pp, false)
        print("^5[Omen] Fake scan complete^7")
        toast("success", "Misc", "Fake scan complete")
    end)
end })
reg("checkac",        { click=function()
    local acs = {"WaveShield","ReaperV4","ReaperV5","FiveGuard","ElectronAC","EagleAC","WardenAC"}
