    if type(GetResourceState) == "function" then
        for _, ac in ipairs(acs) do
            if GetResourceState and GetResourceState(ac) == "started" then found[#found+1] = ac end
        end
    end
    local msg = #found > 0 and table.concat(found, ", ") or "None detected"
    toast("info","Omen","AC: "..msg)
end })
