reg("antiVDM", {
    toggle_on  = function()
        Omen.State.antiVDM = true
        startTick("antiVDM", 200, function()
            if not Omen.State.antiVDM then stopTick("antiVDM"); return end
            local ped = PlayerPedId()
            -- real anti-VDM: immune to vehicle/collision damage (not just clear blood).
            -- config flag 60 = can't be knocked off bike; proofs block vehicle damage.
            SetEntityProofs(ped, false, false, false, false, false, true, 1, false)  -- drive-by/collision proof
            SetPedConfigFlag(ped, 60, true)
            if IsPedBeingStunned(ped, 0) then ClearPedBloodDamage(ped) end
        end)
    end,
    toggle_off = function()
        Omen.State.antiVDM = false
        stopTick("antiVDM")
        local ped = PlayerPedId()
        SetEntityProofs(ped, false, false, false, false, false, false, 0, false)
    end,
})
