})
reg("antiTxFreeze", {
    toggle_on = function()
        Omen.State.antiTxFreeze = true
        if not _G.__AntiTxThread then
            _G.__AntiTxThread = true
            CreateThread(function()
                while Omen.State.antiTxFreeze or Omen.State.antiTxAttach do
                    Wait(0)
                    local ped = PlayerPedId()
                    if Omen.State.antiTxFreeze then FreezeEntityPosition(ped, false) end
                    if Omen.State.antiTxAttach then
                        for _, veh in ipairs(GetGamePool("CVehicle") or {}) do
                            if IsEntityAttachedToAnyPed(veh) and GetEntityAttachedTo(veh) == ped then
                                NetworkRequestControlOfEntity(veh)
                                DetachEntity(veh, 0, true)
                            end
                        end
                    end
                end
                _G.__AntiTxThread = false
            end)
        end
        toast("success","Anti-Admin","Anti TX Freeze ON")
    end,
    toggle_off = function() Omen.State.antiTxFreeze = false; toast("info","Anti-Admin","Anti TX Freeze OFF") end,
})
