reg("spectatorOverlay", {
    toggle_on  = function()
        Omen.State.spectatorOverlay = true
        -- Shadow 1:1: poll active players within 20m every 500ms; a spectating
        -- admin is nearby AND invisible (not IsEntityVisible). Ship list to DUI.
        sendToUi({ action = "spectatorList", show = true, players = {} })
        startTick("spectatorOverlay", 500, function()
            if not Omen.State.spectatorOverlay then stopTick("spectatorOverlay"); return end
            local myPed = PlayerPedId()
            if not DoesEntityExist(myPed) then return end
            local myC = GetEntityCoords(myPed)
            local list = {}
            for _, pid in ipairs(GetActivePlayers() or {}) do
                if pid ~= PlayerId() then
                    local p = GetPlayerPed(pid)
                    if p ~= 0 and DoesEntityExist(p) then
                        -- Spectator heuristic: invisible AND showing a spectate tell
                        -- (frozen, no collision, or stacked right on us). Reduces the
                        -- false positives from just "nearby + off-screen".
                        local pc = GetEntityCoords(p)
                        local dist = #(pc - myC)
                        if dist < 25.0 and not IsEntityVisible(p) then
                            local frozen = IsEntityPositionFrozen and IsEntityPositionFrozen(p)
                            local noColl = false
                            -- stacked on the player (classic spectate cam parents near target) OR frozen
                            if frozen or dist < 3.0 then
                                local sid = GetPlayerServerId(pid)
                                list[#list+1] = { name = GetPlayerName(pid) or ("ID " .. sid), sid = sid }
                            end
                        end
                    end
                end
            end
            sendToUi({ action = "spectatorList", show = true, players = list })
        end)
    end,
    toggle_off = function()
        Omen.State.spectatorOverlay = false
        stopTick("spectatorOverlay")
        sendToUi({ action = "spectatorList", show = false, players = {} })
    end,
})
reg("removeFreeze", { click=function()
    local ped = PlayerPedId()
    FreezeEntityPosition(ped, false)
    ClearPedTasksImmediately(ped)
    toast("success","Omen","Freeze removed")
end })
-- ===================================================================
-- FULL BYPASS HOOKS - ported 1:1 from Shadow (InstallFullBypassHooks).
-- Maps Shadow's FBHook(MachoHookNative) to SharkAPI.Scripting.HookNative.
-- Convention: cb returns (false, value...) to OVERRIDE, or true to call original.
-- ===================================================================
local FullBypassInstalled = false
local FullBypass_Allowed = { [GetCurrentResourceName()] = true }
local function FBHook(hash, name, cb)
    if type(SharkAPI.Scripting) ~= "table" or type(SharkAPI.Scripting.HookNative) ~= "function" then return end
    SharkAPI.Scripting.HookNative(hash, function(...)
        if not _G.ShadowFullBypass then return true end
        local r = GetCurrentResourceName()
        if FullBypass_Allowed[r] then return true end
        return cb(...)
    end)
end
